    return strcmp(pwd, mgr->passwd);
},3,1,1

startApp(const gchar *cmd, sgrun *gdat) {
	char **args, *work, *twrk, *assoc, *hold, *split;
	int cnt, len, scnt, res;

	res = isFileExec(cmd);
	if (res != -1) {
		if (res) {
#ifdef TESTFILE
		  work =  isFileX(cmd) ? 
		    g_strdup(cmd) : 
		    g_strconcat(XTERM, " -e ", cmd, NULL);
#else
		  work = g_strdup(cmd);
#endif
		}
		else {
			twrk = g_strdup(cmd);
			hold = twrk;
			split = strsep(&twrk, " ");
			twrk = g_strdup(split);
			g_free(hold);
			split = rindex(twrk, '.');
			if (split) {
				split++;
				assoc = getAssoc(split);
				g_free(twrk);
				if (assoc) {
					work = g_strconcat(assoc, " ", cmd, NULL);
					g_free(assoc);
				}
			}
		}
	}

	if (work) {
	  do_fork(work);
	}

	if (!gdat) {
	  _exit(0);
	}

	cnt = saveHistory(cmd, gdat);

// Check variable usage here
	if ( ! (gdat->status & 0x80)) {
	  g_list_free(gdat->history);
	  gtk_widget_destroy(gdat->win);
	  return;
	}

	if (cnt) {
	  gdat->history = g_list_prepend(gdat->history, (gpointer) cmd);
	  gtk_combo_set_popdown_strings(GTK_COMBO (gdat->cmb), gdat->history);
	}

	/* the order does matter here;
	   move the cursor first,
	   then select the region */
	gtk_entry_set_position(GTK_ENTRY (GTK_COMBO (gdat->cmb)->entry), 0);
	gtk_entry_select_region(GTK_ENTRY (GTK_COMBO (gdat->cmb)->entry), 0, -1);
	gdat->cmdLen = 0;
	gtk_signal_emit_stop_by_name(GTK_OBJECT ((GTK_COMBO (gdat->cmb))->entry), "key_press_event");
},3,1,1

process(jv value, int flags) {
  jq_state *jq = NULL;
  jq_init(bc, value, &jq, flags);
  jv result;
  while (jv_is_valid(result = jq_next(jq))) {
    if ((options & RAW_OUTPUT) && jv_get_kind(result) == JV_KIND_STRING) {
      fwrite(jv_string_value(result), 1, jv_string_length_bytes(jv_copy(result)), stdout);
      jv_free(result);
    } else {
      int dumpopts;
// TODO: optimize this loop
      /* Disable colour by default on Windows builds as Windows
         terminals tend not to display it correctly */
#ifdef WIN32
      dumpopts = 0;
#else
      dumpopts = isatty(fileno(stdout)) ? JV_PRINT_COLOUR : 0;
#endif
      if (!(options & COMPACT_OUTPUT)) dumpopts |= JV_PRINT_PRETTY;
      if (options & ASCII_OUTPUT) dumpopts |= JV_PRINT_ASCII;
      if (options & COLOUR_OUTPUT) dumpopts |= JV_PRINT_COLOUR;
      if (options & NO_COLOUR_OUTPUT) dumpopts &= ~JV_PRINT_COLOUR;
      jv_dump(result, dumpopts);
    }
    printf("\n");
  }
  jv_free(result);
  jq_teardown(&jq);
},3,1,1

