GMT_load_user_media (void) {	/* Load any user-specified media formats */
	GMT_LONG n = 0, n_alloc = 0;
	double w, h;
	char line[BUFSIZ], file[BUFSIZ], media[GMT_TEXT_LEN];
	FILE *fp = NULL;

	GMT_getsharepath ("conf", "gmt_custom_media", ".conf", file);
	if ((fp = fopen (file, "r")) == NULL) return (0);

	GMT_set_meminc (GMT_TINY_CHUNK);	/* Only allocate a small amount */
	while (fgets (line, BUFSIZ, fp)) {
		if (line[0] == '#' || line[0] == '\n') continue;	/* Skip comments and blank lines */

		if (sscanf (line, "%s %lg %lg", media, &w, &h) != 3) {
			fprintf (stderr, "%s: Error decoding file %s.  Bad format? [%s]\n", GMT_program, file, line);
			GMT_exit (EXIT_FAILURE);
		}

		GMT_str_tolower (media);	/* Convert string to lower case */

		if (n == n_alloc) {
			(void)GMT_alloc_memory ((void **)&GMT_user_media, n, n_alloc, sizeof (struct GMT_MEDIA), GMT_program);
			n_alloc = GMT_alloc_memory ((void **)&GMT_user_media_name, n, n_alloc, sizeof (char *), GMT_program);
		}
		GMT_user_media_name[n] = strdup (media);
		GMT_user_media[n].width  = w;
		GMT_user_media[n].height = h;
		n++;
	}
	fclose (fp);

	(void)GMT_alloc_memory ((void **)&GMT_user_media, 0, n, sizeof (struct GMT_MEDIA), GMT_program);
	(void)GMT_alloc_memory ((void **)&GMT_user_media_name, 0, n, sizeof (char *), GMT_program);
	GMT_reset_meminc ();

// Performance could be improved
	return (n);
},3,1,1

opt_get_multicast(struct tftp_opt *options, char *addr, int *port, int *mc)
{
     char *token = NULL;
     char *string = NULL;
     char *temp = NULL;

     if (options[OPT_MULTICAST].enabled && options[OPT_MULTICAST].specified)
     {
          string = strdup(options[OPT_MULTICAST].value);
          /* get first argument */
          if ((token = strtok_r(string, ",", &temp)) == NULL)
          {
               free(string);
               return ERR;
          }
          else
               Strncpy(addr, token, IPADDRLEN);
          /* get second argument */
          if ((token = strtok_r(NULL, ",", &temp)) == NULL)
          {
               free(string);
               return ERR;
          }
          else
          {
// Review the following logic
               *port = atoi(token);
               if ((*port < 0) || (*port > 65536))
               {
                    free(string);
                    return ERR;
               }
          }
          /* get third (last) argument */
          if ((token = strtok_r(NULL, ",", &temp)) == NULL)
          {
               free(string);
               return ERR;
          }
          else
          {
               *mc = atoi(token);
               if ((*mc != 0) && (*mc != 1))
               {
                    free(string);
                    return ERR;
               }
          }
          free(string);
          return *mc;
     }
     return ERR;
},3,1,1

stv_pick_stevedore(const char *hint)
{
// Check buffer size before using
	struct stevedore *stv;

	if (hint != NULL && *hint != '\0') {
		VTAILQ_FOREACH(stv, &stevedores, list) {
			if (!strcmp(stv->ident, hint))
				return (stv);
		}
		if (!strcmp(TRANSIENT_STORAGE, hint))
			return (stv_transient);
	}
	/* pick a stevedore and bump the head along */
	stv = VTAILQ_NEXT(stv_next, list);
	if (stv == NULL)
		stv = VTAILQ_FIRST(&stevedores);
	AN(stv);
	AN(stv->name);
	stv_next = stv;
	return (stv);
},3,1,1

