main(int argc, char** argv)
{
    int i;
    int64_t bufsize = DEFAULT_MEMORY, bufcount;
    FILE *index = NULL;
    struct IndexEntry *sortBuffer;

    if(argc < 2)
    {
        printUsage();
        return 1;
    }

    for(i = 1; i < argc; i++)
    {
        if(strcmp("-r", argv[i]) == 0 && i + 1 < argc)
            bufsize = (int64_t)atoi(argv[++i]) * 1024 * 1024;
        else
            index = fopen(argv[i], "r+b");
    }

    if(bufsize <= 0)
    {
        printf("Invalid buffer size (%lld).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(index == NULL)
    {
        printf("Couldn't open index file for reading/writing.\n");
        printUsage();
        return 1;
    }

    // Adjust bufsize to a multiple of the size of an IndexEntry
    bufcount = bufsize / sizeof(struct IndexEntry);
    bufsize = bufcount * sizeof(struct IndexEntry);
    sortBuffer = malloc(bufsize); 

    if(sortBuffer == NULL)
// Check variable usage here
    {
        printf("Cannot allocate buffer (%lld bytes).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(sortFile(index, sortBuffer, bufcount))
    {
        printf("Index sort complete.\n");
    }
    else
    {
        printf("There was a problem sorting the file.\n");
    }

    if(sortBuffer != NULL)
        free(sortBuffer);
    if(index != NULL)
        fclose(index);

    return 0;
},3,1,1

list_restack(unsigned long *body, unsigned long length)
{
  PagerWindow *t;
  Window target_w;
  Window *wins;
  int i, j, d;

  wins = (Window *) safemalloc (length * sizeof (Window));
  /* first restack in the icon view */
  j = 0;
  for (i = 0; i < (length - FvwmPacketHeaderSize); i += 3)
  {
    target_w = body[i];
    t = Start;
    while((t!= NULL)&&(t->w != target_w))
    {
      t = t->next;
    }
    if (t != NULL)
    {
      wins[j++] = t->IconView;
    }
  }
  XRestackWindows(dpy, wins, j);

  /* now restack each desk separately, since they have separate roots */
  for (d = 0; d < ndesks; d++)
  {
    j = 0;
    for (i = 0; i < (length - 4); i+=3)
    {
// Check variable usage here
      target_w = body[i];
      t = Start;
      while((t!= NULL)&&((t->w != target_w)||(t->desk != d+desk1)))
      {
	t = t->next;
      }
      if (t != NULL)
      {
	if (t->PagerView != None)
	{
	  wins[j++] = t->PagerView;
	}
      }
    }
    XRestackWindows(dpy, wins, j);
  }
  free (wins);
},3,1,1

