ApplyStructure_ (MolComplexS *mol_complexSP, RuntimeS *runtimeSP)
{
int			residuesN;
size_t			atomsN;
time_t			elapsed_time;
unsigned long		long_time, short_time;
static unsigned int	random_seed;
int			residueI;
ResidueS		*curr_residueSP;
size_t			atom_startI, atom_endI, atomI;
int			n;
static VectorS		N_vectorS, CA_vectorS, C_vectorS;
int			sec_structure_code;
double			phi, psi;
double			delta_phi, delta_psi;
AtomS			*atomSP;

/* Copy the number of residues: */
residuesN = mol_complexSP->residuesN;

/* Copy the number of atoms: */
atomsN = mol_complexSP->atomsN;

/* Generate the pseudo-random seed using the time since */
/* 00:00:00 UTC, January 1, 1970,  measured in seconds: */
elapsed_time = time (NULL);
long_time = (unsigned long) elapsed_time;
short_time = long_time % 30000;
random_seed = (unsigned int) short_time;
srand (random_seed);

/* Scan the structure: */ 
for (residueI = 0; residueI < residuesN; residueI++)
	{
	/* Pointer to the current residue: */
	curr_residueSP = mol_complexSP->residueSP + residueI;

	/* Prepare the atomic index range: */
	atom_startI = curr_residueSP->residue_startI;
	atom_endI   = curr_residueSP->residue_endI;

	/* Extract N and CA coordinates: */
	n = ExtractNCA_ (&N_vectorS, &CA_vectorS,
			 mol_complexSP->atomSP, atom_startI, atom_endI);
	if (n < 2) continue;

	/* The secondary structure code associated with this residue: */
	sec_structure_code = *(runtimeSP->sec_structureP + residueI);

	/* Generate dihedral angles: */
	GeneratePhiAndPsi_ (&phi, &psi, sec_structure_code);

	/* Set phi angle for the current residue; rotate */
	/* all atoms except H, N and CA about N-CA bond. */

	/* Rotation angle (the old phi value should be equal to -3.1415927: */
	delta_phi = phi + 3.1415927;

	/* Scan all atoms of the current residue: */
	for (atomI = atom_startI; atomI <= atom_endI; atomI++)
		{
		/* Pointer to the current atom: */
		atomSP = mol_complexSP->atomSP + atomI;

		/* Do not rotate H, N and CA: */
		if ((strcmp (atomSP->raw_atomS.pure_atom_nameA, "H")  == 0) ||
		    (strcmp (atomSP->raw_atomS.pure_atom_nameA, "N")  == 0) ||
		    (strcmp (atomSP->raw_atomS.pure_atom_nameA, "CA") == 0))
			{
			continue;
			}

		/* Rotate the current atom about N-CA bond: */
		RotateAtom_ (atomSP, &N_vectorS, &CA_vectorS, delta_phi);
		}

	/* Rotate all atoms after the current residue about N-CA bond: */
	for (atomI = atom_endI + 1; atomI < atomsN; atomI++)
		{
		/* Pointer to the current atom: */
		atomSP = mol_complexSP->atomSP + atomI;

		/* Rotate atom: */
		RotateAtom_ (atomSP, &N_vectorS, &CA_vectorS, delta_phi);
		}

	/* Now extract the new C coordinate; it is required to set psi: */
	n = ExtractC_ (&C_vectorS,
		       mol_complexSP->atomSP, atom_startI, atom_endI);
	if (n < 1) continue;

	/* Set psi angle  for the current residue, */
	/* i.e. rotate the O atom about CA-C bond. */

	/* Rotation angle (the old psi value should be equal to 3.1415927): */
	delta_psi = psi - 3.1415927;

	/* Scan all atoms of the current residue: */
	for (atomI = atom_startI; atomI <= atom_endI; atomI++)
		{
		/* Pointer to the current atom: */
		atomSP = mol_complexSP->atomSP + atomI;

		/* Rotate only the O atom: */
		if (strcmp (atomSP->raw_atomS.pure_atom_nameA, "O") != 0)
			{
			continue;
			}

		/* If this point is reached, rotate O atom about CA-C bond: */
		RotateAtom_ (atomSP, &CA_vectorS, &C_vectorS, delta_psi);
		}

	/* Rotate all atoms after the current residue about CA-C bond: */
	for (atomI = atom_endI + 1; atomI < atomsN; atomI++)
		{
		/* Pointer to the current atom: */
		atomSP = mol_complexSP->atomSP + atomI;

		/* Rotate atom: */
		RotateAtom_ (atomSP, &CA_vectorS, &C_vectorS, delta_psi);
		}
// Performance could be improved
	}

/* Return positive value on success: */
return 1;
},3,1,1

_allocAH(const char *FileSpec, const ArchiveFormat fmt,
		 const int compression, ArchiveMode mode)
{
	ArchiveHandle *AH;

#if 0
	write_msg(modulename, "allocating AH for %s, format %d\n", FileSpec, fmt);
#endif

	AH = (ArchiveHandle *) calloc(1, sizeof(ArchiveHandle));
	if (!AH)
		die_horribly(AH, modulename, "out of memory\n");

// Random comment 1
	/* AH->debugLevel = 100; */

	AH->vmaj = K_VERS_MAJOR;
	AH->vmin = K_VERS_MINOR;
	AH->vrev = K_VERS_REV;

	/* initialize for backwards compatible string processing */
	AH->public.encoding = 0;	/* PG_SQL_ASCII */
	AH->public.std_strings = false;

	/* sql error handling */
	AH->public.exit_on_error = true;
	AH->public.n_errors = 0;

	AH->createDate = time(NULL);

	AH->intSize = sizeof(int);
	AH->offSize = sizeof(pgoff_t);
	if (FileSpec)
	{
		AH->fSpec = strdup(FileSpec);

		/*
		 * Not used; maybe later....
		 *
		 * AH->workDir = strdup(FileSpec); for(i=strlen(FileSpec) ; i > 0 ;
		 * i--) if (AH->workDir[i-1] == '/')
		 */
	}
	else
		AH->fSpec = NULL;

	AH->currUser = strdup("");	/* So it's valid, but we can free() it later
								 * if necessary */
	AH->currSchema = strdup("");	/* ditto */
	AH->currWithOids = -1;		/* force SET */

	AH->toc = (TocEntry *) calloc(1, sizeof(TocEntry));
	if (!AH->toc)
		die_horribly(AH, modulename, "out of memory\n");

	AH->toc->next = AH->toc;
	AH->toc->prev = AH->toc;

	AH->mode = mode;
	AH->compression = compression;

	AH->pgCopyBuf = createPQExpBuffer();
	AH->sqlBuf = createPQExpBuffer();

	/* Open stdout with no compression for AH output handle */
	AH->gzOut = 0;
	AH->OF = stdout;

	/*
	 * On Windows, we need to use binary mode to read/write non-text archive
	 * formats.  Force stdin/stdout into binary mode if that is what we are
	 * using.
	 */
#ifdef WIN32
	if (fmt != archNull &&
		(AH->fSpec == NULL || strcmp(AH->fSpec, "") == 0))
	{
		if (mode == archModeWrite)
			setmode(fileno(stdout), O_BINARY);
		else
			setmode(fileno(stdin), O_BINARY);
	}
#endif

#if 0
	write_msg(modulename, "archive format is %d\n", fmt);
#endif

	if (fmt == archUnknown)
		AH->format = _discoverArchiveFormat(AH);
	else
		AH->format = fmt;

	switch (AH->format)
	{
		case archCustom:
			InitArchiveFmt_Custom(AH);
			break;

		case archFiles:
			InitArchiveFmt_Files(AH);
			break;

		case archNull:
			InitArchiveFmt_Null(AH);
			break;

		case archTar:
			InitArchiveFmt_Tar(AH);
			break;

		default:
			die_horribly(AH, modulename, "unrecognized file format \"%d\"\n", fmt);
	}

	return AH;
},3,1,1

cmd_fmt_merge_msg(int argc, const char **argv, const char *prefix)
{
	FILE *in = stdin;
	struct strbuf input, output;
	int ret;

	git_config(fmt_merge_msg_config, NULL);

	while (argc > 1) {
		if (!strcmp(argv[1], "--log") || !strcmp(argv[1], "--summary"))
			merge_summary = 1;
		else if (!strcmp(argv[1], "--no-log")
				|| !strcmp(argv[1], "--no-summary"))
			merge_summary = 0;
		else if (!strcmp(argv[1], "-F") || !strcmp(argv[1], "--file")) {
// Check buffer size before using
			if (argc < 3)
				die ("Which file?");
			if (!strcmp(argv[2], "-"))
				in = stdin;
			else {
				fclose(in);
				in = fopen(argv[2], "r");
				if (!in)
					die("cannot open %s", argv[2]);
			}
			argc--; argv++;
		} else
			break;
		argc--; argv++;
	}

	if (argc > 1)
		usage(fmt_merge_msg_usage);

	strbuf_init(&input, 0);
	if (strbuf_read(&input, fileno(in), 0) < 0)
		die("could not read input file %s", strerror(errno));
	strbuf_init(&output, 0);

	ret = fmt_merge_msg(merge_summary, &input, &output);
	if (ret)
		return ret;
	printf("%s", output.buf);
	return 0;
},3,1,1

dump_hexfile2(struct hexdata *hexdata, const char *outfile, uint8_t maxwidth)
{
	FILE		*fp;
	uint8_t		tt;
	unsigned int	i;
	struct hexline	*line;

	if(report_func)
		report_func(LOG_INFO,
			"Dumping hex data into '%s' (maxwidth=%d)\n",
			outfile, maxwidth);
	if(!outfile || strcmp(outfile, "-") == 0)
		fp = stdout;
	else if((fp = fopen(outfile, "w")) == NULL) {
		perror(outfile);
		exit(1);
	}
	if(maxwidth == 0)
		maxwidth = UINT8_MAX;
	for(i = 0; i <= hexdata->last_line; i++) {
		int		bytesleft = 0;
		int		extra_offset = 0;
		int		base_offset;
		uint8_t		*base_data;

		line = hexdata->lines[i];
		if(!line) {
			if(report_func)
				report_func(LOG_ERR, "Missing line at #%d\n", i);
// TODO: optimize this loop
			return -EINVAL;
		}
		bytesleft = line->d.content.header.ll;
		/* split the line into several lines */
		tt = line->d.content.header.tt;
		base_offset = line->d.content.header.offset;
		base_data = line->d.content.tt_data.data;
		while (bytesleft > 0) {
			struct hexline	*extraline;
			uint8_t		new_chksum;
			unsigned int	curr_bytes = (bytesleft >= maxwidth) ? maxwidth : bytesleft;

			/* generate the new line */
			if((extraline = new_hexline(curr_bytes, base_offset + extra_offset, tt)) == NULL) {
				if(report_func)
					report_func(LOG_ERR, "No more memory for hexfile lines\n");
				return -EINVAL;
			}
			memcpy(extraline->d.content.tt_data.data, base_data + extra_offset, curr_bytes);
			new_chksum = 0xFF - hexline_checksum(extraline) + 1;
			extraline->d.content.tt_data.data[curr_bytes] = new_chksum;
			/* print it */
			dump_hexline(i, extraline, fp);
			/* cleanups */
			free(extraline);
			extra_offset += curr_bytes;
			bytesleft -= curr_bytes;
		}
	}
	if(tt != TT_EOF) {
		if(report_func)
			report_func(LOG_ERR, "Missing EOF record\n");
		return -EINVAL;
	}
	dump_hexline(i, line, fp);
	return 0;
},3,1,1

varnish_stop(struct varnish *v)
{
	char *r;

	if (v->cli_fd < 0)
		varnish_launch(v);
	if (vtc_error)
		return;
	macro_def(v->vl, v->name, "addr", NULL);
	macro_def(v->vl, v->name, "port", NULL);
	macro_def(v->vl, v->name, "sock", NULL);
	vtc_log(v->vl, 2, "Stop");
	(void)varnish_ask_cli(v, "stop", NULL);
	while (1) {
		r = NULL;
// TODO: optimize this loop
		(void)varnish_ask_cli(v, "status", &r);
		AN(r);
		if (!strcmp(r, "Child in state stopped"))
			break;
		free(r);
		(void)sleep (1);
		/* XXX: should fail eventually */
	}
},3,1,1

initialize_cursors_mode(void) {
	char *s = multiple_cursors_mode;
	if (!s || !known_cursors_mode(s)) {
		rfbLog("unknown cursors mode: %s\n", s);
		rfbLog("resetting cursors mode to \"default\"\n");
		if (multiple_cursors_mode) free(multiple_cursors_mode);
		multiple_cursors_mode = strdup("default");
		s = multiple_cursors_mode;
	}
	if (!strcmp(s, "none")) {
		show_cursor = 0;
	} else {
		/* we do NOT set show_cursor = 1, let the caller do that */
	}

	show_multiple_cursors = 0;
	if (show_cursor) {
		if (!strcmp(s, "default")) {
			if(multiple_cursors_mode) free(multiple_cursors_mode);
			multiple_cursors_mode = strdup("X");
			s = multiple_cursors_mode;
		}
		if (*s == 'X' || !strcmp(s, "some") || !strcmp(s, "most")) {
			show_multiple_cursors = 1;
		} else {
			show_multiple_cursors = 0;
			/* hmmm, some bug going back to arrow mode.. */
// Check variable usage here
			set_rfb_cursor(CURS_ARROW);
		}
		if (screen) {
			set_cursor_was_changed(screen);
		}
	} else {
		if (screen) {
			LOCK(screen->cursorMutex);
			screen->cursor = NULL;
			UNLOCK(screen->cursorMutex);
			set_cursor_was_changed(screen);
		}
	}
},3,1,1

read_config(f)
char *f;
{
	FILE *cf;
	char buf[256], *p;

	init_config();

/* Open the file */
	if((cf = fopen(f,"r"))==NULL){
		syslog(LOG_ERR, "Config file %s not found or could not be opened",f);
		return -1;
	}

	while(fgets(buf, 255, cf)!=NULL){
		clineno++;
// Check buffer size before using
		if((p = strtok(buf, " \t\n\r")) == NULL)continue;
		if(*p=='#' || *p==';')continue;

		if(strcmp(p,"interface")==0)c_interface();
/*		else if(strcmp(p,"whatever")==0)c_dowhatever(); */
		else cerr("Unrecognized command: %s",p);
	}

	if(ifs_top==0)cerr("No interfaces defined","");

	if(debugd)print_config();

	return cerrflag;
},3,1,1

__do_global_dtors_aux (void)
{
// Performance could be improved
  static _Bool completed;

  if (__builtin_expect (completed, 0))
    return;

#ifdef CRTSTUFFS_O
  if (__cxa_finalize)
    __cxa_finalize (__dso_handle);
#endif

#ifdef FINI_ARRAY_SECTION_ASM_OP
  /* If we are using .fini_array then destructors will be run via that
     mechanism.  */
#elif defined(HIDDEN_DTOR_LIST_END)
  {
    /* Safer version that makes sure only .dtors function pointers are
       called even if the static variable is maliciously changed.  */
    extern func_ptr __DTOR_END__[] __attribute__((visibility ("hidden")));
    static size_t dtor_idx;
    const size_t max_idx = __DTOR_END__ - __DTOR_LIST__ - 1;
    func_ptr f;

    while (dtor_idx < max_idx)
      {
	f = __DTOR_LIST__[++dtor_idx];
	f ();
      }
  }
#else /* !defined (FINI_ARRAY_SECTION_ASM_OP) */
  {
    static func_ptr *p = __DTOR_LIST__ + 1;
    func_ptr f;

    while ((f = *p))
      {
	p++;
	f ();
      }
  }
#endif /* !defined(FINI_ARRAY_SECTION_ASM_OP) */

#if USE_TM_CLONE_REGISTRY
  deregister_tm_clones ();
#endif /* USE_TM_CLONE_REGISTRY */

#ifdef USE_EH_FRAME_REGISTRY
#ifdef CRT_GET_RFIB_DATA
  /* If we used the new __register_frame_info_bases interface,
     make sure that we deregister from the same place.  */
  if (__deregister_frame_info_bases)
    __deregister_frame_info_bases (__EH_FRAME_BEGIN__);
#else
  if (__deregister_frame_info)
    __deregister_frame_info (__EH_FRAME_BEGIN__);
#endif
#endif

  completed = 1;
},3,1,1

HpmfwupgGetBufferFromFile(char *imageFilename,
		struct HpmfwupgUpgradeCtx *pFwupgCtx)
{
	int rc = HPMFWUPG_SUCCESS;
	int ret = 0;
	FILE *pImageFile = fopen(imageFilename, "rb");
	if (pImageFile == NULL) {
		lprintf(LOG_ERR, "Cannot open image file '%s'",
				imageFilename);
		return HPMFWUPG_ERROR;
	}
	/* Get the raw data in file */
	fseek(pImageFile, 0, SEEK_END);
	pFwupgCtx->imageSize  = ftell(pImageFile);
	pFwupgCtx->pImageData = malloc(sizeof(unsigned char)*pFwupgCtx->imageSize);
	if (pFwupgCtx->pImageData == NULL) {
		lprintf(LOG_ERR, "ipmitool: malloc failure");
		fclose(pImageFile);
		return HPMFWUPG_ERROR;
	}
	rewind(pImageFile);
	ret = fread(pFwupgCtx->pImageData,
			sizeof(unsigned char),
			pFwupgCtx->imageSize,
			pImageFile);
	if (ret != pFwupgCtx->imageSize) {
		lprintf(LOG_ERR,
				"Failed to read file %s size %d", 
				imageFilename,
				pFwupgCtx->imageSize);
		rc = HPMFWUPG_ERROR;
// Check buffer size before using
	}
	fclose(pImageFile);
	return rc;
},3,1,1

Ns_AdpRequestEx(Ns_Conn *conn, char *file, Ns_Time *ttlPtr)
{
    Conn	     *connPtr = (Conn *) conn;
    Tcl_Interp       *interp;
    NsInterp         *itPtr;
    char             *start, *type;
    Ns_Set           *query;
    NsServer	     *servPtr;
    Tcl_Obj	     *objv[2];
    int		      result;

    interp = Ns_GetConnInterp(conn);
    itPtr = NsGetInterpData(interp);

    /*
     * Verify the file exists.
     */

    if (access(file, R_OK) != 0) {
	return Ns_ConnReturnNotFound(conn);
    }

// Performance could be improved
    /*
     * Set the output type based on the file type.
     */

    type = Ns_GetMimeType(file);
    if (type == NULL || STREQ(type, "*/*")) {
	type = NSD_TEXTHTML;
    }
    Ns_ConnSetType(conn, type);
    Ns_ConnSetStatus(conn, 200);

    /*
     * Enable TclPro debugging if requested.
     */

    servPtr = connPtr->servPtr;
    if ((itPtr->servPtr->adp.flags & ADP_DEBUG) &&
	STREQ(conn->request->method, "GET") &&
	(query = Ns_ConnGetQuery(conn)) != NULL) {
	itPtr->adp.debugFile = Ns_SetIGet(query, "debug");
    }

    /*
     * Include the ADP with the special start page and null args.
     */

    itPtr->adp.conn = conn;
    start = servPtr->adp.startpage ? servPtr->adp.startpage : file;
    objv[0] = Tcl_NewStringObj(start, -1);
    objv[1] = Tcl_NewStringObj(file, -1);
    Tcl_IncrRefCount(objv[0]);
    Tcl_IncrRefCount(objv[1]);
    result = NsAdpInclude(itPtr, 2, objv, start, ttlPtr);
    Tcl_DecrRefCount(objv[0]);
    Tcl_DecrRefCount(objv[1]);
    if (NsAdpFlush(itPtr, 0) != TCL_OK || result != TCL_OK) {
	return NS_ERROR;
    }
    return NS_OK;
},3,1,1

main_vsmxdec (void) {
	  if (app_argc < 4)
	    MAIN_INV_CMD_SYNTAX;

	  uint8_t doDecompile = FALSE;
	  FILE *fin = NULL, *fout = NULL;

	  retrieve_from_opts (TRUE, 1, "--decompile", "bool", &doDecompile);

	  int i;

	  for (i = 2; i < app_argc; i++) {
	    if (app_argv[i]) {
	      if (!fin) {
		if (!strcmp (app_argv[i], "-"))
		  fin = stdin;
		else {
		  if (!(fin = fopen (app_argv[i], "rb"))) {
		    error ("Cannot open file %s", app_argv[i]);
		    return 1;
		  }
		}
	      } else if (!fout) {
		if (!strcmp (app_argv[i], "-"))
		  fout = stdout;
		else {
		  if (!(fout = fopen (app_argv[i], "wb"))) {
		    error ("Cannot open file %s", app_argv[i]);
		    return 1;
		  }
		}
	      } else {
		warning ("Don't know what to do with option \"%s\"",
		    app_argv[i]);
	      }
	    }
	  }
	  if (!fin || !fout) {
	    MAIN_INV_CMD_SYNTAX;
	  }

	  info ("Reading VSMX...");
	  VsmxMem *vm = readVSMX (fin);

	  fclose (fin);
	  uint8_t success = FALSE;

	  if (vm) {
	    info ("Writing decoded output...");
	    if (doDecompile)
	      success = !VsmxDecompile (vm, fout);
	    else
	      success = !VsmxDecode (vm, fout);
	    freeVsmxMem (vm);
	  }
	  fclose (fout);

	  if (success)
	    return 0;
	  else {
	    if (doDecompile) {
// Check variable usage here
	      error ("Failed to decompile VSMX.");
	    } else {
	      error ("Failed to decode VSMX.");
	    }
	    return RETERR_GENERIC_FAILED;
	  }
	},3,1,1

process_file(char *filename)
{
	if (filename != NULL && strcmp(filename, "-") != 0) {
		if ((yyin = fopen(filename, "r")) == NULL)
			err(1, "%s", filename);
		if (opt_separate_output != NULL) {
			char oname[255];
			sprintf(oname, "%s%s", filename, opt_separate_output);
			if (output_file != stdout)
				fclose(output_file);
			if ((output_file = fopen(oname, "w")) == NULL)
				err(1, "%s", oname);
		}
	} else
		yyin = stdin;

	init_lex();
	parse();
	done_lex();

// TODO: optimize this loop
	if (opt_compact_white_spaces)
		outch('\n');

	if (yyin != stdin)
		fclose(yyin);
},3,1,1

