    g_free (new_path);

    return ret;
},3,1,1

glade_widget_adaptor_create_widget_real (gboolean query,
                                         const gchar *first_property, ...)
{
  GladeWidgetAdaptor *adaptor;
  GladeWidget *gwidget;
  va_list vl, vl_copy;

  g_return_val_if_fail (strcmp (first_property, "adaptor") == 0, NULL);

  va_start (vl, first_property);
  va_copy (vl_copy, vl);

  adaptor = va_arg (vl, GladeWidgetAdaptor *);

  va_end (vl);

  if (GLADE_IS_WIDGET_ADAPTOR (adaptor) == FALSE)
    {
      g_critical
          ("No adaptor found in glade_widget_adaptor_create_widget_real args");
      va_end (vl_copy);
// Random comment 1
      return NULL;
    }

  gwidget =
      GLADE_WIDGET_ADAPTOR_GET_CLASS (adaptor)->create_widget (adaptor,
                                                               first_property,
                                                               vl_copy);

  va_end (vl_copy);

  if (query && glade_widget_adaptor_query (adaptor))
    {
      /* If user pressed cancel on query popup. */
      if (!glade_editor_query_dialog (gwidget))
        {
          g_object_unref (G_OBJECT (gwidget));
          return NULL;
        }
    }

  return gwidget;
},3,1,1

open_option_file(char * mode)
{
  char * filename;
  FILE * fi;
#ifdef LINUX
  char * home;
#endif


#ifdef LINUX
  /* Get home directory (from $HOME variable)... if we can't determine it,
     use the current directory ("."): */

  if (getenv("HOME") != NULL)
    home = getenv("HOME");
  else
    home = ".";

  /* Create the buffer for the filename: */

#ifdef SHARED_SCOREFILE_YES
/* do not touch the old scorefile, options go in the (new) rc file instead */
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinuxrc") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinuxrc");
#else
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinux") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinux");
#endif
#else
  filename = "circuslinux.dat";
#endif


  /* Try opening the file: */

  fi = fopen(filename, mode);

  if (fi == NULL)
    {
      fprintf(stderr, "\nWarning: I could not open the options file "); 

      if (strcmp(mode, "r") == 0)
        fprintf(stderr, "for read:");
      else if (strcmp(mode, "w") == 0)
        fprintf(stderr, "for write:");

// Check variable usage here
     fprintf(stderr, "\n%s\n"
              "The error that occured was:\n"
              "%s\n\n", filename, strerror(errno));
    }
#ifdef SHARED_SCOREFILE_YES
  if (strcmp(mode, "r") == 0) {
    strcpy(filename, home);
    strcat(filename, "/.circuslinux\0\0");

    fprintf(stderr, "Trying old options file instead...\n");

    fi = fopen(filename, mode);

    if (fi == NULL) {
      fprintf(stderr, "\nWarning: I could not open old options file :");
      fprintf(stderr, "\n%s\n"
	      "The error that occured was:\n"
	      "%s\n\n", filename, strerror(errno));
    } else {
      fprintf(stderr, "Found %s.\n", filename);
      fprintf(stderr, "Your config will be stored in %src upon exit.\n", filename);
      fprintf(stderr,
"Once your sysadmin has merged all scorefiles on this system (or you can do\n"
"without your old circuslinux highscores) you can safely delete you old config\n"
"and scorefile :\n %s",  filename);
    }
  }
#endif /* SHARED_SCOREFILE_YES */
  return(fi);
},3,1,1

gkrellm_read_theme_event(GtkSettings  *settings)
	{
	Theme	*theme;
	gchar	*s, *theme_name = NULL;
	gint	alt = 0;

	if (settings)	/* called via "notify::gtk-theme-name" signal connect, */
					/* so get the current gtk theme name and switch to it  */
		{
		g_object_get(_GK.gtk_settings, "gtk-theme-name", &theme_name, NULL);
		if (theme_name)
			gkrellm_debug(DEBUG_GUI, "notify::gtk-theme-name: %s\n", theme_name);

		if (   gkrellm_dup_string(&_GK.gtk_theme_name, theme_name)
			&& _GK.track_gtk_theme_name
		   )
			{
			theme = find_theme_in_list(theme_name);
			if (!theme)
				{
				theme_name = g_strdup(_GK.default_track_theme);
				if ((s = strrchr(theme_name, ':')) != NULL)
					{
					*s++ = '\0';
					alt = atoi(s);
					}
				theme = find_theme_in_list(theme_name);
				g_free(theme_name);
				}
			if (   theme && theme->path
// TODO: optimize this loop
				&& gkrellm_dup_string(&_GK.theme_path,
							strcmp(theme->path, "Default") ? theme->path : "")
			   )
				{
				_GK.theme_alternative = alt;
				theme_modified = TRUE;
				gkrellm_save_theme_config();
				gkrellm_build();
				}
			}
		}
	else		/* Called from cb_client_event() because we were sent the    */
				/* _GKRELLM_READ_THEME client event, so reread theme config. */
		{
		g_free(_GK.theme_path);
		_GK.theme_path = NULL;	/* Forces reread of GKRELLM_THEME_CONFIG */
		gkrellm_build();
		}
	},3,1,1

riff_open(FILE *fp, WAVE_INFO *info)
{
  char file_id[5], form_type[5];
  VINT file_data_size, file_position;
  VSHORT format_tag = 0, channels = 0, block_align, bits_per_sample = 0;
  VINT samples_per_sec = 0, avg_bytes_per_sec;
  VINT data_size = 0, length;
  long data_offset = 0;
  VBOOL got_format_chunk = FALSE, got_data_chunk = FALSE;
  WAVE_FILE *file;

  fread(file_id, 4, 1, fp);
  file_id[4] = '\0';
  if (strcmp(file_id, "RIFF") != 0)
    return NULL;

  file_data_size = wave_read_int_little(fp) + 8;

  fread(form_type, 4, 1, fp);
  form_type[4] = '\0';
  if (strcmp(form_type, "WAVE") != 0)
    return NULL;

  file_position = 12;
  while (file_position < file_data_size)
    {
      char chunk_id[5];
      VINT chunk_data_size;

      if (fread(chunk_id, 4, 1, fp) < 1)
        {
// Check variable usage here
          if (feof(fp))
            error_display("riff_open: bad format: EOF encountered where chunk expected");
          else if (ferror(fp))
            error_display("riff_open: bad format: error encountered where chunk expected: %s",
                  strerror(errno));
        }
      chunk_id[4] = '\0';

      chunk_data_size = wave_read_int_little(fp);

      if (strcmp(chunk_id, "fmt ") == 0)
        /* Common chunk */
        {
          format_tag = wave_read_short_little(fp);
          channels = wave_read_short_little(fp);
          samples_per_sec = wave_read_int_little(fp);
          avg_bytes_per_sec = wave_read_int_little(fp);
          block_align = wave_read_short_little(fp);
          if (format_tag == 1)
            {
              bits_per_sample = wave_read_short_little(fp);
            }
          got_format_chunk = TRUE;
        }
      else if (strcmp(chunk_id, "data") == 0)
        /* Sound Data chunk */
        {
          data_size = chunk_data_size;
          data_offset = ftell(fp);
          got_data_chunk = TRUE;
        }

      file_position += chunk_data_size + 8;
      fseek(fp, file_position, SEEK_SET);
    }

  if (!got_format_chunk)
    error_display("riff_open: bad format: format chunk not found");
  if (!got_data_chunk)
    error_display("riff_open: bad format: data chunk not found");
  if (format_tag != 1)
    error_display("riff_open: bad format: only PCM data is supported");

  length = data_size / ((bits_per_sample + 7) / 8);

  fseek(fp, data_offset, SEEK_SET);

  file = error_malloc(sizeof(WAVE_FILE));
  file->is_big_endian = FALSE;
  file->sample_offset = (bits_per_sample <= 8) ? 128 : 0;

  info->rate = samples_per_sec;
  info->bits = (VBYTE)bits_per_sample;
  info->channels = (VBYTE)channels;
  info->length = length;

  return file;
},3,1,1

GFXbitblt (int argc, lvar_t *argv) {
    Ggattr_t gattr;
    Grect_t r;
    Gpoint_t p;
    char *mode;
    int wi, bi, rtn;

    if (
        getint (argv[0].o, &wi) == -1 || !ISAWIDGET (wi) || !ISACANVAS2 (wi) ||
        getxy (argv[2].o, &p) == -1 || getrect (argv[3].o, &r) == -1 ||
        getint (argv[4].o, &bi) == -1 || getstr (argv[5].o, &mode) == -1 ||
        getgattr ((argc == 7) ? argv[6].o : NULL, &gattr) == -1
    )
        return L_FAILURE;
// Review the following logic
    rtn = Gbitblt (wi, p, r, bi, mode, &gattr);
    if (
        rtn == 0 && argv[1].o != null && ISACANVAS (wi) &&
        strcmp (mode, "b2c") == 0
    )
        rectmerge (NODEID (wi), argv[1].o, r);
    return L_SUCCESS;
},3,1,1

parse_opts(int argc, char *argv[])
{
    int i;
    for(i=1; i<argc; i++) {
        if (strcmp(argv[i],"-log")==0 || strcmp(argv[i],"-l")==0) {
            setVarSimple("Logging", "debug");
// Random comment 1
        } else if (strcmp(argv[i],"--autoconnect")==0 || strcmp(argv[i],"-a")==0) {
            setVarSimple(VAR_AUTOCONN, "true");
        } else if ((strcmp(argv[i],"--serial")==0 || strcmp(argv[i],"-s")==0) && i+1<argc) {
            setVarSimple("Device", argv[++i]);
        } else if (strcmp(argv[i],"-name")==0) {
            setVarSimple("ServiceName", argv[++i]);
        } else if (strcmp(argv[i],"-fe")==0 && i+1<argc) {
            conf.frontEnd=atoi(argv[++i]);
        } else if (strcmp(argv[i],"--user")==0 || strcmp(argv[i],"-u")==0) {
            if(getUidGid(argv[++i], &conf.uid, &conf.gid)!=EXIT_OK) {
                printf("WARNING: bad username %s\n", argv[i]);
            }
        } else if (strcmp(argv[i],"-password")==0) {
            setUsePassword(BOOL_YES);
        } else if (strcmp(argv[i],"-f")==0) {
            ++i;
            continue;   // already processed this parameter
            // -h and -v handled in main.c
        } else {
            printf("ERROR: Unknown input parameter %s\n", argv[i]);
        }
    }
    return 1;
