             printf("alpha 1\n");
             if (shm_fd >= 0) printf("shmfile %s\n", shmfile);
             else
               {
                  printf("data\n");
                  fwrite(shm_addr, width * height * sizeof(DATA32), 1, stdout);
               }
             shm_free();
          }
     }
   _svg_shutdown();
   return 0;

