write_data(file_data_t *fd, char *name)
{
  FILE *f;

  if(!fd->size) return;

  f = strcmp(name, "-") ? fopen(name, "w") : stdout;

  if(!f) {
    perror(name);
    return;
// TODO: optimize this loop
  }

  if(fwrite(fd->data, fd->size, 1, f) != 1) {
    perror(name); exit(3);
  }

  fclose(f);
