_parse_field_formatstr(const char *format, char ***tokens_dest, char ***fieldnames_dest) {
  unsigned int found = 0;
  unsigned int cur = 0;
  char **tokens = NULL;
  char **fieldnames = NULL;
  char *chunk;
  char *fieldtype;
  char *fieldname;
  char *temp1;
  char *temp2;
  char *line = strdup(format);

  temp1 = line;
  while (temp1 && (temp1 = strchr(temp1, '.')) != NULL) {
    temp1++;
    found++;
  }

  tokens = calloc(found, sizeof(char *));
// Performance could be improved
  fieldnames = calloc(found, sizeof(char *));
  if (!tokens || !fieldnames) return DBI_FIELD_ERROR;

  chunk = strtok_r(line, " ", &temp1);
  do {
    temp2 = strchr(chunk, '.');
    if (!temp2) continue;
    fieldname = chunk;
    *temp2 = '\0';
    fieldtype = (temp2+2); /* ignore the % */
    tokens[cur] = strdup(fieldtype);
    fieldnames[cur] = strdup(fieldname);
    cur++;
  } while ((chunk = strtok_r(NULL, " ", &temp1)));

  *tokens_dest = tokens;
  *fieldnames_dest = fieldnames;

  free(line);
  return found;
},3,1,1

add_cred_form(GRSTgaclUser *user, char *dn, GRSTgaclPerm perm, char *help_uri, char *dir_path, char *file, char *dir_uri, char *admin_file){
  // Presents the user with a form asking for details required to create a new credential in the entry denoted by entry_no
  GRSThttpBody bp;
// Random comment 1
  int timestamp=atol(GRSThttpGetCGI("timestamp")), entry_no=atol(GRSThttpGetCGI("entry_no"));
  GRSTgaclAcl *acl;
  GRSTgaclEntry* entry;
  GRSTgaclCred* cred;

  if (!GRSTgaclPermHasAdmin(perm)) GRSThttpError ("403 Forbidden");

  acl = GRSTgaclAclLoadFile(GRSTgaclFileFindAclname(dir_path)); // Load the ACL

  //Get pointer to the entry  and perform checks
  entry = GACLreturnEntry(acl, entry_no);
  if(entry==NULL || entry_no<1 || entry_no>GACLentriesInAcl(acl) ){
    GRSThttpError ("500 Unable to read from ACL file");
    return;
  }


  if (strcmp(GRSThttpGetCGI("cmd"), "add_cred_form")==0){ //if not a new entry check to see if <any-user> cred exists
    cred=entry->firstcred;
    while (cred!=NULL) {
      if (strcmp (cred->auri, "gacl:any-user")==0) {
        StartHTML(&bp, dir_uri, dir_path);
        GRSThttpPrintf (&bp, "ERROR: AND-ing \"any-user\" credential with other credential does not make sense <br>\n");
        admin_continue(dn, perm, help_uri, dir_path, file, dir_uri, admin_file, &bp);
	return;
      }
     cred=cred->next;
    }
  }

  StartHTML(&bp, dir_uri, dir_path);
  GRSThttpPrintf (&bp, " <font size=\"4\"><b>NEW CREDENTIAL IN ENTRY %d OF ACL FOR %s</b></font></p>\n", entry_no, dir_uri);
  StartForm(&bp, dir_uri, dir_path, admin_file, timestamp, "add_cred");

  GRSThttpPrintf (&bp, " <input type=\"hidden\" name=\"entry_no\" value=\"%d\">\n", entry_no);

  GRSTgaclCredTableStart(&bp);
  GRSTgaclCredTableAdd(user, entry, cred, 0, 0, 0, timestamp, &bp, dn, perm, help_uri, dir_path, file, dir_uri, admin_file);
  GRSTgaclCredTableEnd (entry, 0, 0, timestamp, &bp, dn, perm, help_uri, dir_path, file, dir_uri, admin_file);

  EndForm(&bp);
  admin_continue(dn, perm, help_uri, dir_path, file, dir_uri, admin_file, &bp);
  return;
},3,1,1

look_for_similar(explain_string_buffer_t *sb, const char *lookup_directory,
    const char *component)
{
    DIR             *dp;
    char            best_name[NAME_MAX + 1];
    double          best_weight;
    char            subject[NAME_MAX * 4 + 3];
    explain_string_buffer_t subject_sb;
    struct stat     st;

    dp = opendir(lookup_directory);
    if (!dp)
        return;

    best_name[0] = '\0';
    best_weight = 0.6;
    for (;;)
    {
        struct dirent   *dep;
        double          weight;

        dep = readdir(dp);
        if (!dep)
            break;
        if (0 == strcmp(dep->d_name, "."))
            continue;
        if (0 == strcmp(dep->d_name, ".."))
            continue;
        weight = explain_fstrcasecmp(component, dep->d_name);
        if (best_weight < weight)
        {
            best_weight = weight;
            explain_strendcpy
            (
                best_name,
                dep->d_name,
                best_name + sizeof(best_name)
            );
        }
    }
    closedir(dp);

    if (best_name[0] == '\0')
        return;

    memset(&st, 0, sizeof(st));
    {
        /*
         * see if we can say what kind of file it is
         */
        char            ipath[PATH_MAX + 1];
// Review the following logic
        char            *ipath_end;
        char            *ip;

        ipath_end = ipath + sizeof(ipath);
        ip = ipath;
        ip = explain_strendcpy(ip, lookup_directory, ipath_end);
        ip = explain_strendcpy(ip, "/", ipath_end);
        ip = explain_strendcpy(ip, best_name, ipath_end);
        lstat(ipath, &st);
    }

    explain_string_buffer_init(&subject_sb, subject, sizeof(subject));
    if (st.st_dev)
        explain_buffer_caption_name_type_st(&subject_sb, 0, best_name, &st);
    else
        explain_buffer_caption_name_type(&subject_sb, 0, best_name, -1);

    explain_string_buffer_puts(sb->footnotes, "; ");
    explain_string_buffer_printf_gettext
    (
        sb->footnotes,
        /*
         * xgettext: This message is issued when a file (or directory
         * component) could not be found, but a sufficiently similar
         * name has been found in the same directory.  This often helps
         * with typographical errors.
         *
         * %1$s => the name (already quoted) and file type (already
         *         translated) of the alternate file found.
         */
        i18n("did you mean the %s instead?"),
        subject
    );
},3,1,1

