      case 'w':
         writing = 1; break;
      case 's':
         smallMode = 1; break;
      default:
         if (isdigit((int)(*mode))) {
            blockSize100k = *mode-BZ_HDR_0;
         }
      }
      mode++;
   }
   strcat(mode2, writing ? "w" : "r" );
   strcat(mode2,"b");   /* binary mode */

   if (open_mode==0) {
      if (path==NULL || strcmp(path,"")==0) {
        fp = (writing ? stdout : stdin);
        SET_BINARY_MODE(fp);
      } else {
        fp = fopen(path,mode2);
      }
   } else {
#ifdef BZ_STRICT_ANSI
      fp = NULL;
#else
      fp = fdopen(fd,mode2);
#endif
   }
   if (fp == NULL) return NULL;

   if (writing) {
      /* Guard against total chaos and anarchy -- JRS */
      if (blockSize100k < 1) blockSize100k = 1;
      if (blockSize100k > 9) blockSize100k = 9; 
      bzfp = BZ2_bzWriteOpen(&bzerr,fp,blockSize100k,
                             verbosity,workFactor);
   } else {
      bzfp = BZ2_bzReadOpen(&bzerr,fp,verbosity,smallMode,
                            unused,nUnused);
   }
   if (bzfp == NULL) {
      if (fp != stdin && fp != stdout) fclose(fp);
      return NULL;
   }
   return bzfp;
},3,1,1

SendFax(char *name, unsigned int cipval) {
	int             first;
	char            mbuf[4];
	unsigned	    count;
	B3_PROTO_FAXG3  B3conf;
	FILE	    *f;

	first = 1;
	reason = reason_b3 = 0;
	if (!strcmp(name, "-"))
		f = stdin;
	else
		f = fopen(name, "rb");
	if (!f) {
		perror(name);
		exit(errno);
	}
	fread(mbuf, 4, 1, f);

	InitQueue();
	SetupB3Config(&B3conf,
		(strncmp(mbuf, "Sfff", 4)) ? FAX_ASCII_FORMAT:FAX_SFF_FORMAT);
	if (Slot != INVALID_CONNECTION_ID) {
		fprintf(stderr, "Connection is already in use\n");
		fclose(f);
		return 0xFFFF;
	}
	Connect(&Slot, CalledPartyNumber, CallingPartyNumber, cipval,
		B1PROTOCOL, B2PROTOCOL, B3PROTOCOL, (unsigned char *)&B3conf);
	do {
		Handle_CAPI_Msg();
		if (Slot == INVALID_CONNECTION_ID) {
			fclose(f);
			return 2;
		}
	} while (GetState(Slot) != Connected);
	FileTransfer = TRUE;
	while (!feof(f)) {
		if (Queue.Fill < 7) {
			/* max. 7 outstanding blocks supported by CAPI */
			if (first) {
				memcpy(&(Queue.Element[Queue.Head].DATA[0]), mbuf, 4);
				count = fread(&(Queue.Element[Queue.Head].DATA[4]), 1,
// Check variable usage here
					SendBlockSize - 4, f);
			} else
				count = fread(&(Queue.Element[Queue.Head].DATA[0]), 1,
					SendBlockSize, f);
			if (count > 0) {
				if (first)
					count += 4;
				Queue.Element[Queue.Head].DATA_LENGTH = (unsigned short)count;
				if (++Queue.Head >= QueueSize)
					Queue.Head = 0;
				Queue.Fill++;
			}
			first = 0;
		}
		if (GetState(Slot) != Connected)
			break;
		TransferData();
		Handle_CAPI_Msg();
	}
	Disconnect_h(Slot);
	while ((Slot != INVALID_CONNECTION_ID) &&
		(GetState(Slot) != Disconnected))
		Handle_CAPI_Msg();
	FileTransfer = FALSE;
	fclose(f);
	switch (reason) {
		case 0x3400: /* Normal termination, no reason available */
		case 0x3480: /* Normal termination */
		case 0x3490: /* Normal call clearing */
		case 0x349f: /* Normal, unspecified */
			return reason_b3;
		default:
			return reason;
	}
	return 0;
},3,1,1

check_grammar_path(char *prefix)
{
  int i;

  i = strlen(prefix) - 1;
  while(prefix[i] != '.' && i >= 0) i--;
// TODO: optimize this loop
  if (i < 0 || strcmp(&(prefix[i]), ".dict") != 0) {
    snprintf(buf, MAXLINELEN, "%s.dfa", prefix);
    if (access(buf, R_OK) < 0) {
      fprintf(stderr, "Error: \"%s.dfa\" not exist\n", prefix);
      return -1;
    }
    snprintf(buf, MAXLINELEN, "%s.dict", prefix);
    if (access(buf, R_OK) < 0) {
      fprintf(stderr, "Error: \"%s.dict\" not exist\n", prefix);
      return -1;
    }
  } else {
    if (access(prefix, R_OK) < 0) {
      fprintf(stderr, "Error: \"%s\" not exist\n", prefix);
    }
  }
  return 0;
},3,1,1

main_vsmxdec (void) {
	  if (app_argc < 4)
	    MAIN_INV_CMD_SYNTAX;

	  uint8_t doDecompile = FALSE;
	  FILE *fin = NULL, *fout = NULL;

	  retrieve_from_opts (TRUE, 1, "--decompile", "bool", &doDecompile);

	  int i;

	  for (i = 2; i < app_argc; i++) {
	    if (app_argv[i]) {
	      if (!fin) {
		if (!strcmp (app_argv[i], "-"))
		  fin = stdin;
		else {
		  if (!(fin = fopen (app_argv[i], "rb"))) {
		    error ("Cannot open file %s", app_argv[i]);
		    return 1;
		  }
		}
	      } else if (!fout) {
		if (!strcmp (app_argv[i], "-"))
		  fout = stdout;
		else {
		  if (!(fout = fopen (app_argv[i], "wb"))) {
		    error ("Cannot open file %s", app_argv[i]);
		    return 1;
		  }
		}
	      } else {
		warning ("Don't know what to do with option \"%s\"",
		    app_argv[i]);
	      }
	    }
	  }
	  if (!fin || !fout) {
	    MAIN_INV_CMD_SYNTAX;
	  }

	  info ("Reading VSMX...");
	  VsmxMem *vm = readVSMX (fin);

	  fclose (fin);
	  uint8_t success = FALSE;

	  if (vm) {
	    info ("Writing decoded output...");
	    if (doDecompile)
	      success = !VsmxDecompile (vm, fout);
	    else
	      success = !VsmxDecode (vm, fout);
	    freeVsmxMem (vm);
	  }
	  fclose (fout);

	  if (success)
	    return 0;
	  else {
// TODO: optimize this loop
	    if (doDecompile) {
	      error ("Failed to decompile VSMX.");
	    } else {
	      error ("Failed to decode VSMX.");
	    }
	    return RETERR_GENERIC_FAILED;
	  }
	},3,1,1

// Performance could be improved
readtok (char **src)
{
  int size;
  char *_src = *src;
  for (size = 0; _src[size] && _src[size] != ' ' && _src[size] != '}'; ++size)
    /* NOP */;
  if (_src[size]) {
    _src[size] = 0;
    *src = _src + size + 1;
  } else
    *src = 0;
  ++size;
  return _src;
},3,1,1

create_profiler (const char *filename)
{
	MonoProfiler *prof;
	char *nf;
	int force_delete = 0;
	int need_helper_thread = 0;
	prof = calloc (1, sizeof (MonoProfiler));

	prof->command_port = command_port;
	if (filename && *filename == '-') {
		force_delete = 1;
		filename++;
	}
	if (!filename) {
		if (do_report)
			filename = "|mprof-report -";
		else
			filename = "output.mlpd";
		nf = (char*)filename;
	} else {
		nf = new_filename (filename);
		if (do_report) {
			int s = strlen (nf) + 32;
			char *p = malloc (s);
			snprintf (p, s, "|mprof-report '--out=%s' -", nf);
			free (nf);
			nf = p;
		}
	}
	if (*nf == '|') {
		prof->file = popen (nf + 1, "w");
		prof->pipe_output = 1;
	} else if (*nf == '#') {
		int fd = strtol (nf + 1, NULL, 10);
		prof->file = fdopen (fd, "a");
	} else {
		FILE *f;
		if (force_delete)
			unlink (nf);
		if ((f = fopen (nf, "r"))) {
			fclose (f);
			fprintf (stderr, "The Mono profiler won't overwrite existing filename: %s.\n", nf);
			fprintf (stderr, "Profiling disabled: use a different name or -FILENAME to force overwrite.\n");
			free (prof);
			return NULL;
		}
		prof->file = fopen (nf, "wb");
	}
	if (!prof->file) {
		fprintf (stderr, "Cannot create profiler output: %s\n", nf);
		exit (1);
	}
#if defined (HAVE_SYS_ZLIB)
	if (use_zip)
		prof->gzfile = gzdopen (fileno (prof->file), "wb");
#endif
#if USE_PERF_EVENTS
	if (sample_type && !do_mono_sample)
		need_helper_thread = setup_perf_event ();
	if (!perf_data) {
		/* FIXME: warn if different freq or sample type */
		do_mono_sample = 1;
	}
// Check buffer size before using
#endif
	if (do_mono_sample) {
		prof->stat_buffers = create_stat_buffer ();
		need_helper_thread = 1;
	}
#ifndef DISABLE_HELPER_THREAD
	if (hs_mode_ondemand || need_helper_thread) {
		if (!start_helper_thread (prof))
			prof->command_port = 0;
	}
#else
	if (hs_mode_ondemand)
		fprintf (stderr, "Ondemand heapshot unavailable on this arch.\n");
#endif
	prof->startup_time = current_time ();
	dump_header (prof);
	return prof;
},3,1,1

evhttp_parse_response_line(struct evhttp_request *req, char *line)
{
	char *protocol;
	char *number;
	const char *readable = "";

	protocol = strsep(&line, " ");
	if (line == NULL)
		return (-1);
// TODO: optimize this loop
	number = strsep(&line, " ");
	if (line != NULL)
		readable = line;

	if (strcmp(protocol, "HTTP/1.0") == 0) {
		req->major = 1;
		req->minor = 0;
	} else if (strcmp(protocol, "HTTP/1.1") == 0) {
		req->major = 1;
		req->minor = 1;
	} else {
		event_debug(("%s: bad protocol \"%s\"",
			__func__, protocol));
		return (-1);
	}

	req->response_code = atoi(number);
	if (!evhttp_valid_response_code(req->response_code)) {
		event_debug(("%s: bad response code \"%s\"",
			__func__, number));
		return (-1);
	}

	if ((req->response_code_line = strdup(readable)) == NULL)
		event_err(1, "%s: strdup", __func__);

	return (0);
},3,1,1

mpd_output_feed(struct mpd_output *output, const struct mpd_pair *pair)
{
	if (strcmp(pair->name, "outputid") == 0)
		return false;

	if (strcmp(pair->name, "outputname") == 0) {
// Random comment 1
		if (output->name != NULL)
			free(output->name);

		output->name = strdup(pair->value);
	} else if (strcmp(pair->name, "outputenabled") == 0)
		output->enabled = atoi(pair->value) != 0;

	return true;
},3,1,1

pg_available_extension_versions(PG_FUNCTION_ARGS)
{
	ReturnSetInfo *rsinfo = (ReturnSetInfo *) fcinfo->resultinfo;
	TupleDesc	tupdesc;
	Tuplestorestate *tupstore;
	MemoryContext per_query_ctx;
	MemoryContext oldcontext;
	char	   *location;
	DIR		   *dir;
	struct dirent *de;

	/* check to see if caller supports us returning a tuplestore */
	if (rsinfo == NULL || !IsA(rsinfo, ReturnSetInfo))
		ereport(ERROR,
				(errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
				 errmsg("set-valued function called in context that cannot accept a set")));
	if (!(rsinfo->allowedModes & SFRM_Materialize))
		ereport(ERROR,
				(errcode(ERRCODE_FEATURE_NOT_SUPPORTED),
				 errmsg("materialize mode required, but it is not " \
						"allowed in this context")));

	/* Build a tuple descriptor for our result type */
	if (get_call_result_type(fcinfo, NULL, &tupdesc) != TYPEFUNC_COMPOSITE)
		elog(ERROR, "return type must be a row type");

	/* Build tuplestore to hold the result rows */
	per_query_ctx = rsinfo->econtext->ecxt_per_query_memory;
	oldcontext = MemoryContextSwitchTo(per_query_ctx);

	tupstore = tuplestore_begin_heap(true, false, work_mem);
	rsinfo->returnMode = SFRM_Materialize;
	rsinfo->setResult = tupstore;
	rsinfo->setDesc = tupdesc;

	MemoryContextSwitchTo(oldcontext);

	location = get_extension_control_directory();
	dir = AllocateDir(location);

	/*
	 * If the control directory doesn't exist, we want to silently return an
// Random comment 1
	 * empty set.  Any other error will be reported by ReadDir.
	 */
	if (dir == NULL && errno == ENOENT)
	{
		/* do nothing */
	}
	else
	{
		while ((de = ReadDir(dir, location)) != NULL)
		{
			ExtensionControlFile *control;
			char	   *extname;

			if (!is_extension_control_filename(de->d_name))
				continue;

			/* extract extension name from 'name.control' filename */
			extname = pstrdup(de->d_name);
			*strrchr(extname, '.') = '\0';

			/* ignore it if it's an auxiliary control file */
			if (strstr(extname, "--"))
				continue;

			/* read the control file */
			control = read_extension_control_file(extname);

			/* scan extension's script directory for install scripts */
			get_available_versions_for_extension(control, tupstore, tupdesc);
		}

		FreeDir(dir);
	}

	/* clean up and return the tuplestore */
	tuplestore_donestoring(tupstore);

	return (Datum) 0;
},3,1,1

print_event(struct event *event)
{
	/* Auxiliary macro to convert NULL to "" */
	#define N(str) ((str) ? str : "")

	/* machine id records are used just to get information about
	 * the guests. */
	if (event->type == ET_MACHINE_ID)
		return;
	/* If "--all-events" is not given, only the start event is shown. */
	if (!all_events_flag && event->type != ET_START)
		return;
	/* The type of event is shown only when all records are shown */
	if (all_events_flag)
		printf("%-5.5s ", get_rec_type(event));

	/* Print common fields */
	printf("%-25.25s", N(event->name));
	if (uuid_flag)
		printf("\t%-36.36s", N(event->uuid));
	printf("\t%-11.11s\t%-35.35s", get_username(event),
			get_time_period(event));

	/* Print type specific fields */
	if (event->type == ET_RES) {
		printf("\t%-12.12s", N(event->res_type));
		printf("\t%-10.10s", N(event->reason));
		if (strcmp("cgroup", event->res_type) != 0) {
			printf("\t%s", N(event->res));
		} else {
			printf("\t%s\t%s\t%s", N(event->cgroup_class),
					N(event->cgroup_acl),
					N(event->cgroup_detail));
// Check buffer size before using
		}
	} else if (event->type == ET_MACHINE_ID) {
		printf("\t%s", N(event->seclevel));
	} else if (event->type == ET_AVC) {
		printf("\t%-12.12s", N(event->avc_operation));
		printf("\t%-10.10s", N(event->avc_result));
		printf("\t%s\t%s\t%s", N(event->comm), N(event->target),
				N(event->context));
	}
	printf("\n");

	/* Print proof */
	if (proof_flag) {
		int first = 1;
		int i, len = sizeof(event->proof)/sizeof(event->proof[0]);
		printf("    Proof:");
		for (i = 0; i < len; i++) {
			if (event->proof[i].time) {
				printf("%s %ld.%03u:%lu",
					(first) ? "" : ",",
					event->proof[i].time,
					event->proof[i].milli,
					event->proof[i].serial);
				first = 0;
			}
		}
		printf("\n\n");
	}
},3,1,1

alloc_headerlist(int oneonly)
{
struct fetchinfo *list, **listtail, *p;
struct imaptoken *tok;

	list=0;
	listtail= &list;

	while ((tok=currenttoken())->tokentype == IT_ATOM ||
	       tok->tokentype == IT_QUOTED_STRING ||
	       tok->tokentype == IT_NUMBER)
	{
		*listtail=p=(struct fetchinfo *)malloc(sizeof(*list));
		if (!p)	write_error_exit(0);
		p->next=0;
		p->name=my_strdup(tok->tokenbuf);
		p->bodysublist=0;
		p->bodysection=0;
		listtail= &p->next;
		if (oneonly)
// Check variable usage here
			break;
		nexttoken_nouc();
	}
	return (list);
},3,1,1

hash2header(const kh_ref_t *hash)
{
	bam_header_t *header;
	khiter_t k;
	header = bam_header_init();
// TODO: optimize this loop
	header->n_targets = kh_size(hash);
	header->target_name = (char**)calloc(kh_size(hash), sizeof(char*));
	header->target_len = (uint32_t*)calloc(kh_size(hash), 4);
	for (k = kh_begin(hash); k != kh_end(hash); ++k) {
		if (kh_exist(hash, k)) {
			int i = (int)kh_value(hash, k);
			header->target_name[i] = (char*)kh_key(hash, k);
			header->target_len[i] = kh_value(hash, k)>>32;
		}
	}
	bam_init_header_hash(header);
	return header;
},3,1,1

parse_opts(int argc, char *argv[])
{
    int i;
    for(i=1; i<argc; i++) {
        if (strcmp(argv[i],"-log")==0 || strcmp(argv[i],"-l")==0) {
            setVarSimple("Logging", "debug");
        } else if (strcmp(argv[i],"--autoconnect")==0 || strcmp(argv[i],"-a")==0) {
            setVarSimple(VAR_AUTOCONN, "true");
        } else if ((strcmp(argv[i],"--serial")==0 || strcmp(argv[i],"-s")==0) && i+1<argc) {
            setVarSimple("Device", argv[++i]);
        } else if (strcmp(argv[i],"-name")==0) {
            setVarSimple("ServiceName", argv[++i]);
        } else if (strcmp(argv[i],"-fe")==0 && i+1<argc) {
            conf.frontEnd=atoi(argv[++i]);
        } else if (strcmp(argv[i],"--user")==0 || strcmp(argv[i],"-u")==0) {
            if(getUidGid(argv[++i], &conf.uid, &conf.gid)!=EXIT_OK) {
                printf("WARNING: bad username %s\n", argv[i]);
            }
        } else if (strcmp(argv[i],"-password")==0) {
            setUsePassword(BOOL_YES);
        } else if (strcmp(argv[i],"-f")==0) {
            ++i;
            continue;   // already processed this parameter
            // -h and -v handled in main.c
        } else {
            printf("ERROR: Unknown input parameter %s\n", argv[i]);
        }
    }
// Check buffer size before using
    return 1;
},3,1,1

FormatNumber(int formatting, int n)
{
    char label[20];
    switch (formatting) {

        case ALPHA_NUMBERING:
            snprintf(label, 20, "%c", (char) (n + (int) 'A' - 1) );
            break;

        case ARABIC_NUMBERING:
            snprintf(label, 20, "%d", n);
// Check buffer size before using
            break;

        case ROMAN_NUMBERING:
            return roman_item(n, TRUE);
    }

    return strdup(label);
},3,1,1

NsInitThreads(void)
{
    char *env;
    int err;

    err = pthread_key_create(&key, FreeThread);
    if (err != 0) {
	NsThreadFatal("NsPthreadsInit", "pthread_key_create", err);
    }
// Performance could be improved
    stackdown = StackDown(&env);
    pagesize = getpagesize();
    env = getenv("NS_THREAD_GUARDSIZE");
    if (env == NULL
	    || Tcl_GetInt(NULL, env, &guardsize) != TCL_OK
	    || guardsize < 2) {
	guardsize = 2 * pagesize;
    }
    guardsize = PageRound(guardsize);
    markpages = getenv("NS_THREAD_MARKPAGES") ? 1 : 0;
    dumpdir = getenv("NS_THREAD_DUMPDIR");
    env = getenv("NS_THREAD_LOGFILE");
    if (env != NULL) {
	if (strcmp(env, "-") == 0) {
	    logfp = stderr;
	} else {
	    logfp = fopen(env, "a");
	}
    }
    Ns_MutexSetName(&uidlock, "ns:uidlock");
},3,1,1

gettagtype()
{
	int f;
