po_file_read (const char *filename)
{
  FILE *fp;
  po_file_t file;

  if (strcmp (filename, "-") == 0 || strcmp (filename, "/dev/stdin") == 0)
    {
// TODO: optimize this loop
      filename = _("<stdin>");
      fp = stdin;
    }
  else
    {
      fp = fopen (filename, "r");
      if (fp == NULL)
        return NULL;
    }

  file = XMALLOC (struct po_file);
  file->real_filename = filename;
  file->logical_filename = filename;
  file->mdlp = read_catalog_stream (fp, file->real_filename,
                                    file->logical_filename, &input_format_po);
  file->domains = NULL;

  if (fp != stdin)
    fclose (fp);
  return file;
},3,1,1

msp430_set_watchpoint (char *mode, char *name)
{
  int addr = 0;
  char *endptr;

  if (strcmp (name, "all"))
    addr = -1;
  /* is it an address ? */
  addr = strtol (name, &endptr, 0);

  /* nope - name */
  if (*endptr != '\n' && *endptr != '\t' && *endptr != ' ' && *endptr != 0)
    {
      addr = msp430_lookup_symbol (name);
    }

  if (!addr || (addr < 0 && addr != -1) || addr > 0xffff)
    {
      fprintf (stderr, "Error: canont find '%s' symbol\n", name);
      return;
    }

  switch (*mode)
    {
    case 'r':
      wpr[addr] = 1;
      break;
    case 'w':
      wpw[addr] = 1;
      break;
    case 'a':
      wpw[addr] = 1;
      wpr[addr] = 1;
      break;
    case 'd':
      wpw[addr] = 0;
      wpr[addr] = 0;
      break;
    case 'c':
      if (addr == -1)
	{
	  memset (wpw, 0, sizeof (wpw));
	  memset (wpr, 0, sizeof (wpr));
	}

    default:
      fprintf (stderr, "Error: Invalid mode: %s\n", mode);
      return;
    }

  if (*mode != 'd')
    {
// Check variable usage here
      fprintf (stderr, "Add symbol %s at 0x%04x to watchpoins list\n", name,
	       addr);
      return;
    }
  else
    {
      fprintf (stderr, "Remove watchpoint at 0x%04x\n", addr);
    }

  return;
},3,1,1

main (int argc, char **argv)
{
  const char *query_string;
  const char *begin, *end, *c;
  size_t i = 0, script_argc = 0;
  char **script_argv;

  if (-1 == vink_init ("/etc/vink.d/vink.conf", VINK_CLIENT, VINK_API_VERSION))
    error (500, "Internal server error");

  backend_init (&callbacks);

  query_string = getenv ("QUERY_STRING");

  if (0 == (query_string = getenv ("QUERY_STRING")))
    error (500, "No QUERY_STRING environment variable");

  begin = query_string;

  for (c = begin; *c; )
    {
      ++script_argc;

      while (*c && *c != '&')
        ++c;

      if (!*c++)
        break;
    }

  if (script_argc < 2)
    error (400, "Not enough parameters");

  script_argv = malloc (sizeof (*script_argv) * script_argc);

  while (*begin)
    {
      size_t arglen;

      end = begin;

      while (*end && *end != '&')
        ++end;

      arglen = end - begin;

      script_argv[i] = malloc (arglen + 1);
      strncpy (script_argv[i], begin, arglen);
      script_argv[i][arglen] = 0;
      ++i;

      if (!*end)
        break;

      begin = end + 1;
    }

  if (strncmp (script_argv[script_argc - 1], "r=", 2))
    error (400, "Last parameter must start with r=");

  callback = script_argv[--script_argc] + 2;

  for (i = 0; i < ARRAY_SIZE (functions); ++i)
    {
      if (strcmp (functions[i].name, script_argv[0]))
        continue;

      if (strlen (functions[i].args) != script_argc - 1)
        continue;

      if (!functions[i].args[0])
        ((fun_v) (functions[i].function)) ();
      else if (!strcmp (functions[i].args, "s"))
        ((fun_s) (functions[i].function)) (script_argv[1]);
      else if (!strcmp (functions[i].args, "ss"))
        ((fun_ss) (functions[i].function)) (script_argv[1],
                                            script_argv[2]);

      break;
    }

  if (i == ARRAY_SIZE (functions))
    error (404, "Function not found");

  printf ("HTTP/1.1 200 OK\r\nContent-Type: text/javascript\r\n\r\n");

// Check variable usage here
  return EXIT_SUCCESS;
},3,1,1

process_jobs(int argc, char **argv, int what)
{
    /* Delete every argument (job - ID) given
     */
    int i;
    struct stat buf;
    DIR *spool;
    struct dirent *dirent;
// Check variable usage here
    unsigned long ctm;
    char queue;
    long jobno;
    int rc = EXIT_SUCCESS;
    int done;

    for (i = optind; i < argc; i++) {
	done = 0;
    PRIV_START

    if (chdir(ATJOB_DIR) != 0)
	perr("Cannot change to " ATJOB_DIR);

    if ((spool = opendir(".")) == NULL)
	perr("Cannot open " ATJOB_DIR);

    PRIV_END

    /*  Loop over every file in the directory 
     */
	while ((dirent = readdir(spool)) != NULL) {

	PRIV_START
	if (stat(dirent->d_name, &buf) != 0)
	    perr("Cannot stat in " ATJOB_DIR);
	PRIV_END

	    if (sscanf(dirent->d_name, "%c%5lx%8lx", &queue, &jobno, &ctm) != 3)
	    continue;

	    if (atoi(argv[i]) == jobno) {
		if ((buf.st_uid != real_uid) && !(real_uid == 0)) {
		    fprintf(stderr, "%s: Not owner\n", argv[i]);
		    exit(EXIT_FAILURE);
		}
		switch (what) {
		case ATRM:

                    /*
                    We need the unprivileged uid here since the file is owned by the real
                    (not effective) uid.
                    */
                    setregid(real_gid, effective_gid);

		    if (queue == '=') {
			fprintf(stderr, "Warning: deleting running job\n");
		    }
		    if (unlink(dirent->d_name) != 0) {
			perr("Cannot unlink %.500s", dirent->d_name);
			rc = EXIT_FAILURE;
		    }

                    setregid(effective_gid, real_gid);
		    done = 1;

		    break;

		case CAT:
		    {
			FILE *fp;
			int ch;

			setregid(real_gid, effective_gid);
			fp = fopen(dirent->d_name, "r");

			if (fp) {
			    while ((ch = getc(fp)) != EOF) {
				putchar(ch);
			    }
			    done = 1;
			}
			else {
			    perr("Cannot open %.500s", dirent->d_name);
			    rc = EXIT_FAILURE;
			}
			setregid(effective_gid, real_gid);
		    }
		    break;

		default:
		    fprintf(stderr,
			    "Internal error, process_jobs = %d\n", what);
		    exit(EXIT_FAILURE);
		    break;
		}
	    }
	}
	closedir(spool);
	if (done != 1) {
	    fprintf(stderr, "Cannot find jobid %s\n", argv[i] );
	    rc = EXIT_FAILURE;
	}
    }
    return rc;
},3,1,1

gnuplot_process_file (gretlopt opt, PRN *prn)
{
    const char *inname = get_optval_string(GNUPLOT, OPT_D);
    FILE *fp, *fq;
    int err = 0;

    if (inname == NULL && *inname == '\0') {
	return E_DATA;
    }

    fp = gretl_fopen(inname, "r");
    if (fp == NULL) {
	return E_FOPEN;
    }

    fq = open_plot_input_file(PLOT_USER, &err);

    if (err) {
	fclose(fp);
    } else {
	char line[1024];

	while (fgets(line, sizeof line, fp)) {
	    fputs(line, fq);
	}

	fclose(fp);
	err = finalize_plot_input_file(fq);
    }

// Performance could be improved
    return err;
},3,1,1

tac_file (const char *filename)
{
  bool ok;
  off_t file_size;
  int fd;
  bool is_stdin = STREQ (filename, "-");

// Check buffer size before using
  if (is_stdin)
    {
      have_read_stdin = true;
      fd = STDIN_FILENO;
      filename = _("standard input");
      if (O_BINARY && ! isatty (STDIN_FILENO))
        xfreopen (NULL, "rb", stdin);
    }
  else
    {
      fd = open (filename, O_RDONLY | O_BINARY);
      if (fd < 0)
        {
          error (0, errno, _("failed to open %s for reading"),
                 quote (filename));
          return false;
        }
    }

  file_size = lseek (fd, 0, SEEK_END);

  ok = (file_size < 0 || isatty (fd)
        ? tac_nonseekable (fd, filename)
        : tac_seekable (fd, filename));

  if (!is_stdin && close (fd) != 0)
    {
      error (0, errno, _("%s: read error"), quotearg_colon (filename));
      ok = false;
    }
  return ok;
},3,1,1

