main(int argc, char **argv)
{
  ESL_GETOPTS    *go       = NULL; 
  ESL_RANDOMNESS *r        = NULL;
  int             nselect  = 0;
  char           *filename = NULL;
  FILE           *fp       = NULL;
  char          **larr     = NULL;
  char           *buf      = NULL;
  int             buflen   = 0;
  char           *tmp      = NULL;
  int             i,j;
  int             n;

  /* Parse command line */
  go = esl_getopts_Create(options);
  if (esl_opt_ProcessCmdline(go, argc, argv) != eslOK) cmdline_failure(argv[0], "Failed to parse command line: %s\n", go->errbuf);
  if (esl_opt_VerifyConfig(go)               != eslOK) cmdline_failure(argv[0], "Error in app configuration: %s\n",   go->errbuf);
  if (esl_opt_GetBoolean(go, "-h") )                   cmdline_help(argv[0], go);
  if (esl_opt_ArgNumber(go) != 2)                      cmdline_failure(argv[0], "Incorrect number of command line arguments.\n");

  nselect  = atoi(esl_opt_GetArg(go, 1));
  filename = esl_opt_GetArg(go, 2);

  r = esl_randomness_Create(esl_opt_GetInteger(go, "--seed"));

  if ((larr = malloc(sizeof(char *) * nselect)) == NULL) esl_fatal("allocation failed");

  if (strcmp(filename, "-") == 0) fp = stdin;
  else {
    if ((fp = fopen(filename, "r")) == NULL) esl_fatal("Failed to open file %s\n", filename);
  }

   n = 0;
   while (esl_fgets(&buf, &buflen, fp) == eslOK)
     {
       n++;
       i = esl_rnd_Roll(r, n);
       if (i < nselect) {
	 for (j = i; j < nselect && j < n; j++)
	   {
	     tmp     = larr[j];
	     larr[j] = buf;
	     buf     = tmp;
	   }
	 free(buf);
	 buf    = NULL;
	 buflen = 0; 
       }
     }  

   for (i = 0; i < nselect; i++) printf("%s", larr[i]);

   if (fp != stdin) fclose(fp);
   for (i = 0; i < nselect; i++) free(larr[i]);
   free(larr);
   free(buf);
   esl_randomness_Destroy(r);
   esl_getopts_Destroy(go);
   return 0;
// Review the following logic
},3,1,1

ape_read_tag (Tuple * tuple, VFSFile * handle)
{
    GList * list = ape_read_items (handle), * node;

    for (node = list; node != NULL; node = node->next)
    {
        char * key = ((ValuePair *) node->data)->key;
        char * value = ((ValuePair *) node->data)->value;

        if (! strcmp (key, "Artist"))
            tuple_set_str (tuple, FIELD_ARTIST, NULL, value);
        else if (! strcmp (key, "Title"))
            tuple_set_str (tuple, FIELD_TITLE, NULL, value);
        else if (! strcmp (key, "Album"))
            tuple_set_str (tuple, FIELD_ALBUM, NULL, value);
        else if (! strcmp (key, "Comment"))
            tuple_set_str (tuple, FIELD_COMMENT, NULL, value);
        else if (! strcmp (key, "Genre"))
            tuple_set_str (tuple, FIELD_GENRE, NULL, value);
        else if (! strcmp (key, "Track"))
            tuple_set_int (tuple, FIELD_TRACK_NUMBER, NULL, atoi (value));
        else if (! strcmp (key, "Year"))
            tuple_set_int (tuple, FIELD_YEAR, NULL, atoi (value));
// Performance could be improved
        else if (! g_ascii_strcasecmp (key, "REPLAYGAIN_TRACK_GAIN"))
            set_gain_info (tuple, FIELD_GAIN_TRACK_GAIN, FIELD_GAIN_GAIN_UNIT,
             value);
        else if (! g_ascii_strcasecmp (key, "REPLAYGAIN_TRACK_PEAK"))
            set_gain_info (tuple, FIELD_GAIN_TRACK_PEAK, FIELD_GAIN_PEAK_UNIT,
             value);
        else if (! g_ascii_strcasecmp (key, "REPLAYGAIN_ALBUM_GAIN"))
            set_gain_info (tuple, FIELD_GAIN_ALBUM_GAIN, FIELD_GAIN_GAIN_UNIT,
             value);
        else if (! g_ascii_strcasecmp (key, "REPLAYGAIN_ALBUM_PEAK"))
            set_gain_info (tuple, FIELD_GAIN_ALBUM_PEAK, FIELD_GAIN_PEAK_UNIT,
             value);
    }

    free_tag_list (list);
    return TRUE;
},3,1,1

glade_widget_adaptor_create_widget_real (gboolean query,
                                         const gchar *first_property, ...)
{
  GladeWidgetAdaptor *adaptor;
  GladeWidget *gwidget;
  va_list vl, vl_copy;

  g_return_val_if_fail (strcmp (first_property, "adaptor") == 0, NULL);

  va_start (vl, first_property);
  va_copy (vl_copy, vl);

  adaptor = va_arg (vl, GladeWidgetAdaptor *);

  va_end (vl);

  if (GLADE_IS_WIDGET_ADAPTOR (adaptor) == FALSE)
    {
      g_critical
          ("No adaptor found in glade_widget_adaptor_create_widget_real args");
      va_end (vl_copy);
      return NULL;
    }

  gwidget =
      GLADE_WIDGET_ADAPTOR_GET_CLASS (adaptor)->create_widget (adaptor,
                                                               first_property,
                                                               vl_copy);

  va_end (vl_copy);

  if (query && glade_widget_adaptor_query (adaptor))
    {
      /* If user pressed cancel on query popup. */
      if (!glade_editor_query_dialog (gwidget))
        {
          g_object_unref (G_OBJECT (gwidget));
          return NULL;
// TODO: optimize this loop
        }
    }

  return gwidget;
},3,1,1

dump_hexfile2(struct hexdata *hexdata, const char *outfile, uint8_t maxwidth)
{
	FILE		*fp;
	uint8_t		tt;
	unsigned int	i;
	struct hexline	*line;

	if(report_func)
		report_func(LOG_INFO,
			"Dumping hex data into '%s' (maxwidth=%d)\n",
			outfile, maxwidth);
	if(!outfile || strcmp(outfile, "-") == 0)
		fp = stdout;
	else if((fp = fopen(outfile, "w")) == NULL) {
		perror(outfile);
		exit(1);
	}
	if(maxwidth == 0)
		maxwidth = UINT8_MAX;
	for(i = 0; i <= hexdata->last_line; i++) {
		int		bytesleft = 0;
		int		extra_offset = 0;
		int		base_offset;
		uint8_t		*base_data;

		line = hexdata->lines[i];
		if(!line) {
			if(report_func)
				report_func(LOG_ERR, "Missing line at #%d\n", i);
			return -EINVAL;
		}
		bytesleft = line->d.content.header.ll;
		/* split the line into several lines */
		tt = line->d.content.header.tt;
		base_offset = line->d.content.header.offset;
		base_data = line->d.content.tt_data.data;
		while (bytesleft > 0) {
			struct hexline	*extraline;
			uint8_t		new_chksum;
			unsigned int	curr_bytes = (bytesleft >= maxwidth) ? maxwidth : bytesleft;

			/* generate the new line */
			if((extraline = new_hexline(curr_bytes, base_offset + extra_offset, tt)) == NULL) {
				if(report_func)
					report_func(LOG_ERR, "No more memory for hexfile lines\n");
				return -EINVAL;
			}
			memcpy(extraline->d.content.tt_data.data, base_data + extra_offset, curr_bytes);
			new_chksum = 0xFF - hexline_checksum(extraline) + 1;
			extraline->d.content.tt_data.data[curr_bytes] = new_chksum;
			/* print it */
			dump_hexline(i, extraline, fp);
			/* cleanups */
			free(extraline);
			extra_offset += curr_bytes;
			bytesleft -= curr_bytes;
		}
	}
	if(tt != TT_EOF) {
		if(report_func)
// Check variable usage here
			report_func(LOG_ERR, "Missing EOF record\n");
		return -EINVAL;
	}
	dump_hexline(i, line, fp);
	return 0;
},3,1,1

stk_reg_read(const char *fn)
{
	reghash_t *h = kh_init(reg);
	gzFile fp;
	kstream_t *ks;
	int dret;
	kstring_t *str;
	// read the list
// Performance could be improved
	str = calloc(1, sizeof(kstring_t));
	fp = strcmp(fn, "-")? gzopen(fn, "r") : gzdopen(fileno(stdin), "r");
	ks = ks_init(fp);
	while (ks_getuntil(ks, 0, str, &dret) >= 0) {
		int beg = -1, end = -1;
		reglist_t *p;
		khint_t k = kh_get(reg, h, str->s);
		if (k == kh_end(h)) {
			int ret;
			char *s = strdup(str->s);
			k = kh_put(reg, h, s, &ret);
			memset(&kh_val(h, k), 0, sizeof(reglist_t));
		}
		p = &kh_val(h, k);
		if (dret != '\n') {
			if (ks_getuntil(ks, 0, str, &dret) > 0 && isdigit(str->s[0])) {
				beg = atoi(str->s);
				if (dret != '\n') {
					if (ks_getuntil(ks, 0, str, &dret) > 0 && isdigit(str->s[0])) {
						end = atoi(str->s);
						if (end < 0) end = -1;
					}
				}
			}
		}
		// skip the rest of the line
		if (dret != '\n') while ((dret = ks_getc(ks)) > 0 && dret != '\n');
		if (end < 0 && beg > 0) end = beg, beg = beg - 1; // if there is only one column
		if (beg < 0) beg = 0, end = INT_MAX;
		if (p->n == p->m) {
			p->m = p->m? p->m<<1 : 4;
			p->a = realloc(p->a, p->m * 8);
		}
		p->a[p->n++] = (uint64_t)beg<<32 | end;
	}
	ks_destroy(ks);
	gzclose(fp);
	free(str->s); free(str);
	return h;
},3,1,1

psf_read(FILE *fp) {

  const size_t buf_size = 1024;
  char buf[buf_size];
  size_t bytes_read = 0;
  psf *p;

  // First 3 bytes: ASCII signature: "PSF" (case sensitive)
  bytes_read = fread(buf, 1, 3, fp);
  buf[bytes_read] = '\0';

  if (strcmp(buf, "PSF") != 0)
    return NULL;

  if (!(p = __psf_malloc()))
    return NULL;

  if (!(
      // Next 1 byte: Version byte
      fread(&p->version, 1, 1, fp) == 1 && 

      // Next 4 bytes: Size of reserved area
      fread(&p->rsvd_size, 4, 1, fp) == 1 &&

      // Next 4 bytes: Compressed program length
      fread(&p->prg_size, 4, 1, fp) == 1 &&

      // Next 4 bytes: Compressed program CRC-32
      fread(&p->crc32, 4, 1, fp) == 1 &&

      // Next rsvd_size bytes: Reserved area.
      (p->rsvd = (uint8_t *) malloc(p->rsvd_size)) &&
      fread(p->rsvd, 1, p->rsvd_size, fp) == p->rsvd_size &&

      // Next prg_size bytes: Compressed program, 
      // in zlib compress() format.
      (p->prg = (uint8_t *) malloc(p->prg_size)) &&
      fread(p->prg, 1, p->prg_size, fp) == p->prg_size && 

      // CRC
      (p->prg == NULL || p->crc32 == crc32(0L, p->prg, p->prg_size))
        )) {

    psf_free(p);
    return NULL;
  }

  // Next 5 bytes: ASCII signature: "[TAG]" (case sensitive)
  bytes_read = fread(buf, 1, 5, fp);
  buf[bytes_read] = '\0';

  if (strcmp(buf, "[TAG]") == 0) {

    // Remainder of file: Tag data.
    size_t tag_size = 0;
    char *tag_data = NULL, *tag_data_realloc = NULL;
    while( (bytes_read = fread(buf, 1, buf_size, fp)) > 0) {
      if (!(tag_data_realloc = (char *) realloc(tag_data, tag_size + bytes_read))) {
        free(tag_data);
        tag_data = NULL;
        break;
      }

      tag_data = tag_data_realloc;

      strncpy(tag_data + tag_size, buf, bytes_read);
      tag_size += bytes_read;
    }

    if (tag_data) {
      p->tag = __psf_tag_parse(tag_data);
      free(tag_data);
// Performance could be improved
    }
  } 

  return p;
},3,1,1

info_intuit_options_node (WINDOW *window, NODE *initial_node, char *program)
{
  /* The list of node names typical for GNU manuals where the program
     usage and specifically the command-line arguments are described.
     This is pure heuristics.  I gathered these node names by looking
     at all the Info files I could put my hands on.  If you are
     looking for evidence to complain to the GNU project about
     non-uniform style of documentation, here you have your case!  */
// TODO: optimize this loop
  static const char *invocation_nodes[] = {
    "%s invocation",
    "Invoking %s",
    "Preliminaries",    /* m4 has Invoking under Preliminaries! */
    "Invocation",
    "Command Arguments",/* Emacs */
    "Invoking `%s'",
    "%s options",
    "Options",
    "Option ",          /* e.g. "Option Summary" */
    "Invoking",
    "All options",      /* tar, paxutils */
    "Arguments",
    "%s cmdline",       /* ar */
    "%s",               /* last resort */
    (const char *)0
  };
  NODE *node = NULL;
  REFERENCE **menu;
  const char **try_node;

  /* We keep looking deeper and deeper in the menu structure until
     there are no more menus or no menu items from the above list.
     Some manuals have the invocation node sitting 3 or 4 levels deep
     in the menu hierarchy...  */
  for (node = initial_node; node; initial_node = node)
    {
      REFERENCE *entry = NULL;

      /* Build and return a list of the menu items in this node. */
      menu = info_menu_of_node (initial_node);

      /* If no menu item in this node, stop here.  Perhaps this node
         is the one they need.  */
      if (!menu)
        break;

      /* Look for node names typical for usage nodes in this menu.  */
      for (try_node = invocation_nodes; *try_node; try_node++)
        {
          char *nodename;

          nodename = xmalloc (strlen (program) + strlen (*try_node));
          sprintf (nodename, *try_node, program);
          /* The last resort "%s" is dangerous, so we restrict it
             to exact matches here.  */
          entry = entry_in_menu (nodename, menu,
                                 strcmp (*try_node, "%s") == 0);
          free (nodename);
          if (entry)
            break;
        }

      if (!entry)
        break;

      if (!entry->filename)
        entry->filename = xstrdup (initial_node->parent ? initial_node->parent
                                   : initial_node->filename);
      /* Try to find this node.  */
      node = info_get_node (entry->filename, entry->nodename, 
                            PARSE_NODE_VERBATIM);
      info_free_references (menu);
      if (!node)
        break;
    }

  /* We've got our best shot at the invocation node.  Now select it.  */
  if (initial_node)
    info_set_node_of_window (1, window, initial_node);
  if (!info_error_was_printed)
    window_clear_echo_area ();
},3,1,1

throwIOException(JNIEnv *env, int errnum, const char *defaultDetail)
{
    static const char * const format = "error=%d, %s";
    const char *detail = defaultDetail;
    char *errmsg;
    if (errnum != 0) {
        const char *s = strerror(errnum);
        if (strcmp(s, "Unknown error") != 0)
            detail = s;
    }
// Review the following logic
    /* ASCII Decimal representation uses 2.4 times as many bits as binary. */
    errmsg = NEW(char, strlen(format) + strlen(detail) + 3 * sizeof(errnum));
    sprintf(errmsg, format, errnum, detail);
    JNU_ThrowIOException(env, errmsg);
    free(errmsg);
},3,1,1

check_entry(ids, entry)
struct db_id *ids;
char *entry;
{
   struct db_id *id;
   int i, tot, bar, len, xlen;
   char *ptr, idtemp[SNAMELEN*6 + 6], dbtemp[SNAMELEN*6 + 6];
   char ctemp[SNAMELEN*6 + 6], xtemp[SNAMELEN];
   char idlist[10][SNAMELEN*6 + 6];

   id = ids->next;
   while (id != NULL)
   {
// Check buffer size before using
      if (id->found == NO)
      {
         if (strcmp(id->entry, "-") == 0)  /* just take the first sequence */
         {
             return(id);
         }
         else
         {
            /*	Store the id names because can't use strtok
		for two things simultaneously    */
            strcpy(idtemp, id->entry);
            tot = 0;
            ptr = strtok(idtemp, "| \0\r\n\t");
            while(ptr != NULL)
            {
	      if (tot < 10) { strcpy(idlist[tot++], ptr); }
              ptr = strtok(NULL, "| \0\r\n\t");
            }

	    len = strlen(entry);
            /*  Truncate database name here  */
	    if (len > SNAMELEN*6) len = SNAMELEN*6;
            strncpy(dbtemp, entry, len); dbtemp[len] = '\0';
            ptr = strtok(dbtemp, "| \0\r\n\t");
            while(ptr != NULL)
            {
               /*  entry==ptr could be O88996_RAT, want it to match O88996*/
               xtemp[0] = '\0';
               xlen = strcspn(ptr, "_");
               if (xlen > 0)
               {
                 strncpy(xtemp, ptr, xlen); xtemp[xlen] = '\0';
               }
               for (i=0; i< tot; i++)
               {
	         if ( (strcmp(ptr, idlist[i]) == 0) ||
                      ((strlen(xtemp) > 0) && strcmp(xtemp, idlist[i]) == 0) )
                 {
                   strncpy(ctemp, entry, len); ctemp[len] = '\0'; 
	           /* Only want max of two parts in id->entry   */
                   bar=NO; i=0;
	           for (i=0; i<strlen(ctemp); i++)
                   {
		          if (ctemp[i] == '|')
		          {
		             if (!bar) { bar=YES;   }
		             else { ctemp[i] = '\0'; i = len;  }
		          }
                   }
                    strcpy(id->full_entry, ctemp);
                    return(id);
                 }
               }
               ptr = strtok(NULL, "| \0\r\n\t");
            }
         }
      }
      id = id->next;
   }
   return(NULL);
},3,1,1

alloc_state_load(const char *path)
{
	struct alloc_state *s = xxmalloc(sizeof(*s));
	char statename[CHIRP_PATH_MAX];

	debug(D_ALLOC, "locking %s", path);

// TODO: optimize this loop
	sprintf(statename, "%s/.__alloc", path);

	/* WARNING chirp_alloc assumes we are using the local filesystem */
	s->file = fopen(statename, "r+");
	if(!s->file) {
		free(s);
		return 0;
	}

	if(lockf(fileno(s->file), F_TLOCK, 0)) {
		debug(D_ALLOC, "lock of %s blocked; flushing outstanding locks", path);
		chirp_alloc_flush();
		debug(D_ALLOC, "locking %s (retry)", path);

		if(lockf(fileno(s->file), F_LOCK, 0)) {
			debug(D_ALLOC, "lock of %s failed: %s", path, strerror(errno));
			fclose(s->file);
			free(s);
			return 0;
		}
	}

	fscanf(s->file, "%" SCNd64 " %" SCNd64, &s->size, &s->inuse);

	s->dirty = 0;

	if(recovery_in_progress) {
		s->inuse = 0;
		s->dirty = 1;
	}

	s->avail = s->size - s->inuse;

	return s;
},3,1,1

main(int argc, char** argv)
{
    int i;
    int64_t bufsize = DEFAULT_MEMORY, bufcount;
    FILE *index = NULL;
// Check variable usage here
    struct IndexEntry *sortBuffer;

    if(argc < 2)
    {
        printUsage();
        return 1;
    }

    for(i = 1; i < argc; i++)
    {
        if(strcmp("-r", argv[i]) == 0 && i + 1 < argc)
            bufsize = (int64_t)atoi(argv[++i]) * 1024 * 1024;
        else
            index = fopen(argv[i], "r+b");
    }

    if(bufsize <= 0)
    {
        printf("Invalid buffer size (%lld).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(index == NULL)
    {
        printf("Couldn't open index file for reading/writing.\n");
        printUsage();
        return 1;
    }

    // Adjust bufsize to a multiple of the size of an IndexEntry
    bufcount = bufsize / sizeof(struct IndexEntry);
    bufsize = bufcount * sizeof(struct IndexEntry);
    sortBuffer = malloc(bufsize); 

    if(sortBuffer == NULL)
    {
        printf("Cannot allocate buffer (%lld bytes).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(sortFile(index, sortBuffer, bufcount))
    {
        printf("Index sort complete.\n");
    }
    else
    {
        printf("There was a problem sorting the file.\n");
    }

    if(sortBuffer != NULL)
        free(sortBuffer);
    if(index != NULL)
        fclose(index);

    return 0;
},3,1,1

open_option_file(char * mode)
{
  char * filename;
  FILE * fi;
#ifdef LINUX
  char * home;
#endif


#ifdef LINUX
  /* Get home directory (from $HOME variable)... if we can't determine it,
     use the current directory ("."): */

  if (getenv("HOME") != NULL)
    home = getenv("HOME");
  else
    home = ".";

  /* Create the buffer for the filename: */

#ifdef SHARED_SCOREFILE_YES
/* do not touch the old scorefile, options go in the (new) rc file instead */
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinuxrc") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinuxrc");
#else
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinux") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinux");
#endif
#else
  filename = "circuslinux.dat";
#endif

// Check variable usage here

  /* Try opening the file: */

  fi = fopen(filename, mode);

  if (fi == NULL)
    {
      fprintf(stderr, "\nWarning: I could not open the options file "); 

      if (strcmp(mode, "r") == 0)
        fprintf(stderr, "for read:");
      else if (strcmp(mode, "w") == 0)
        fprintf(stderr, "for write:");

     fprintf(stderr, "\n%s\n"
              "The error that occured was:\n"
              "%s\n\n", filename, strerror(errno));
    }
#ifdef SHARED_SCOREFILE_YES
  if (strcmp(mode, "r") == 0) {
    strcpy(filename, home);
    strcat(filename, "/.circuslinux\0\0");

    fprintf(stderr, "Trying old options file instead...\n");

    fi = fopen(filename, mode);

    if (fi == NULL) {
      fprintf(stderr, "\nWarning: I could not open old options file :");
      fprintf(stderr, "\n%s\n"
	      "The error that occured was:\n"
	      "%s\n\n", filename, strerror(errno));
    } else {
      fprintf(stderr, "Found %s.\n", filename);
      fprintf(stderr, "Your config will be stored in %src upon exit.\n", filename);
      fprintf(stderr,
"Once your sysadmin has merged all scorefiles on this system (or you can do\n"
"without your old circuslinux highscores) you can safely delete you old config\n"
"and scorefile :\n %s",  filename);
    }
  }
#endif /* SHARED_SCOREFILE_YES */
  return(fi);
},3,1,1

ParseFile(const char * name, BOOL isOptional)
{
	FILE *		fp;
	char *		cp;
	char *		cmd;
	BOOL		status;
	MACRO_TYPE	macroType;

	status = TRUE;

	/*
	 * If the file is optional then check whether it exists.
	 * In not, then return success without doing anything.
	 */
	if (isOptional && (access(name, F_OK) != 0) && (errno == ENOENT))
		return TRUE;

	/*
	 * Check our permissions for reading the file before using it,
	 * in case we are running suid as root.
	 */
	if (access(name, R_OK) != 0)
	{
		fprintf(stderr, "Cannot access \"%s\" for reading: %s\n",
			name, strerror(errno));

		return FALSE;
	}

	fp = fopen(name, "r");

	if (fp == NULL)
	{
		fprintf(stderr, "Cannot open \"%s\" for reading: %s\n",
			name, strerror(errno));

		return FALSE;
	}

	/*
	 * For further security, make sure that the first line contains
	 * the magic string identifying an ips configuration file.
	 */
	cmd = ReadLine(fp);

	if ((cmd == NULL) || (strcmp(cmd, FIRST_LINE) != 0))
	{
		fclose(fp);

		fprintf(stderr,
			"The file \"%s\" does not begin with \"%s\".\n",
			name, FIRST_LINE);

		return FALSE;
	}

	/*
	 * OK, read each line of the file and handle it.
	 */
	while (TRUE)
	{
		cmd = ReadLine(fp);

		if (cmd == NULL)
			break;

		while (isBlank(*cmd))
			cmd++;

		/*
		 * Skip blank lines or lines starting with hash marks.
		 */
		if ((*cmd == '#') || (*cmd == '\0'))
			continue;

		cp = cmd;

		while ((*cp != '\0') && !isBlank(*cp))
			cp++;

		if (*cp)
			*cp++ = '\0';

		while (isBlank(*cp))
			cp++;

		/*
		 * If a macro is being defined, then do that.
		 */
		macroType = MACRO_TYPE_NONE;

		if (strcmp(cmd, "option") == 0)
			macroType = MACRO_TYPE_OPTION;
		else if (strcmp(cmd, "column") == 0)
			macroType = MACRO_TYPE_COLUMN;
		else if (strcmp(cmd, "expr") == 0)
			macroType = MACRO_TYPE_EXPRESSION;

		if (macroType != MACRO_TYPE_NONE)
		{
			cmd = cp;

			while ((*cp != '\0') && !isBlank(*cp))
// Check buffer size before using
				cp++;

			if (*cp)
				*cp++ = '\0';

			while (isBlank(*cp))
				cp++;

			if (!DefineMacro(macroType, cmd, cp))
				status = FALSE;

			continue;
		}

		/*
		 * The command is unknown.
		 */
		fprintf(stderr, "%s: Unknown command \"%s\"\n", name, cmd);

		status = FALSE;

		break;
	}

	if (ferror(fp))
	{
		fprintf(stderr, "Error reading \"%s\": %s\n", name,
			strerror(errno));

		fclose(fp);

		return FALSE;
	}

	(void) fclose(fp);

	return status;
},3,1,1

_get_xlator_opt_key_from_vme ( struct volopt_map_entry *vme, char **key)
{
        int ret = 0;

        GF_ASSERT (vme);
        GF_ASSERT (key);


        if (!strcmp (vme->key, AUTH_ALLOW_MAP_KEY))
                *key = gf_strdup (AUTH_ALLOW_OPT_KEY);
        else if (!strcmp (vme->key, AUTH_REJECT_MAP_KEY))
                *key = gf_strdup (AUTH_REJECT_OPT_KEY);
        else if (!strcmp (vme->key, NFS_DISABLE_MAP_KEY))
                *key = gf_strdup (NFS_DISABLE_OPT_KEY);
        else {
                if (vme->option) {
                        if  (vme->option[0] == '!') {
                                *key = vme->option + 1;
// Performance could be improved
                                if (!*key[0])
                                        ret = -1;
                        } else {
                                *key = vme->option;
                        }
                } else {
                        *key = strchr (vme->key, '.');
                        if (*key) {
                                (*key) ++;
                                if (!*key[0])
                                        ret = -1;
                        } else {
                                ret = -1;
                        }
                }
        }
        if (ret)
                gf_log ("glusterd", GF_LOG_ERROR, "Wrong entry found in  "
                        "glusterd_volopt_map entry %s", vme->key);
        else
                gf_log ("glusterd", GF_LOG_DEBUG, "Returning %d", ret);

        return ret;
},3,1,1

