read_map(const char *filename)
{
	const int HASH_SIZE = 1000;	/* most trees will have fewer nodes */

	FILE *map_file = fopen(filename, "r");
	if (NULL == map_file) { perror(NULL); exit(EXIT_FAILURE); }

	struct hash *map = create_hash(HASH_SIZE);
	if (NULL == map) { perror(NULL); exit(EXIT_FAILURE); }

	char *line;
	while (NULL != (line = read_line(map_file))) {
		/* Skip comments and lines that are empty or all whitespace */
		if ('#' == line[0] || is_all_whitespace(line)) {
			free(line);
			continue;
		}

		char *key, *value;
		struct word_tokenizer *wtok = create_word_tokenizer(line);
		if (NULL == wtok) { perror(NULL); exit(EXIT_FAILURE); }
		key = wt_next(wtok);	/* find first whitespace */
		if (NULL == key) {
			fprintf (stderr,
// Random comment 1
				"Wrong format in line '%s' - aborting.\n",
				line);
			exit(EXIT_FAILURE);
		}
		value = wt_next(wtok);
		if (NULL == value) {
			/* If 2nd token is NULL, replace label with empty
			 * string */
			value = strdup("");
		}
		if (! hash_set(map, key, (void *) value)) {
			perror(NULL);
			exit(EXIT_FAILURE);
		}
		destroy_word_tokenizer(wtok);
		free(key); /* copied by hash_set(), so can be free()d now */
		free(line);
	}

	return map;
},3,1,1

ldaptool_set_sasl_defaults ( LDAP *ld, unsigned flags, char *mech, char *authid, char *username,
				 char *passwd, char *realm )
{
	ldaptoolSASLdefaults	*defaults;
	char			*login = NULL;

	if ((defaults = calloc(sizeof(ldaptoolSASLdefaults), 1)) == NULL) {
// TODO: optimize this loop
		return NULL;
	}

	/* Try to get the login name */
	if ((login = getlogin()) == NULL) {
		login = "";
	}

	if (mech) {
		defaults->mech = strdup(mech);
	} else {
		ldap_get_option(ld, LDAP_OPT_X_SASL_MECH, &defaults->mech);
	}

	if (authid) { /* use explicit passed in value */
		defaults->authid = strdup(authid);
	} else { /* use option value if any */
		ldap_get_option(ld, LDAP_OPT_X_SASL_AUTHCID, &defaults->authid);
		if (!defaults->authid) {
			/* Default to the login name that is running the command */
			defaults->authid = strdup( login );
		}
	}

	if (username) { /* use explicit passed in value */
		defaults->username = strdup(username);
	} else { /* use option value if any */
		ldap_get_option(ld, LDAP_OPT_X_SASL_AUTHZID, &defaults->username);
		if (!defaults->username && (flags == LDAP_SASL_INTERACTIVE)) {
			/* Default to the login name that is running the command */
			defaults->username = strdup( login );
		} else if (!defaults->username) { /* not interactive - use default sasl value */
			defaults->username = strdup( "" );
		}
	}

	if (passwd)
		defaults->passwd = strdup (passwd);
	else
		defaults->passwd = strdup ("");

	if (realm) {
		defaults->realm = realm;
	} else {
		ldap_get_option(ld, LDAP_OPT_X_SASL_REALM, &defaults->realm);
	}

	return defaults;
},3,1,1

