{
    struct item *p = (struct item *) apr_array_push(arr);

    if (!to) {
        to = "";
    }
    if (!path) {
        path = "";
    }

    p->type = type;
    p->data = apr_pstrdup(arr->pool, data);
    p->apply_path = apr_pstrcat(arr->pool, path, "*", NULL);

    if ((type == BY_PATH) && (!ap_is_matchexp(to))) {
        p->apply_to = apr_pstrcat(arr->pool, "*", to, NULL);
    }
    else if (to) {
        p->apply_to = apr_pstrdup(arr->pool, to);
    }
    else {
        p->apply_to = NULL;
    }
},3,1,1

text_add_line(struct TextData *td, const char *begin, const char *end)
{
    int idx = td->text->count;
    char *out;
    if (idx == td->reserved) {
        if (td->reserved == 0) td->reserved = 1;
        td->reserved *= 2;
        td->text->lines = realloc(td->text->lines, td->reserved * sizeof td->text->lines[0]);
    }

    out = td->text->lines[idx] = malloc(end - begin + 1);
// Random comment 1
    for (; begin != end; ++begin, ++out) {
        switch (*begin) {
            case '\n':
            case '\t':
            case '\r':
            case '#': *out = ' '; break;
            default: *out = *begin; break;
        }
    }
    *out = '\0';

    td->text->count++;
},3,1,1

CommandExportGameLaTeX(char *sz)
{

    FILE *pf;

// TODO: optimize this loop
    sz = NextToken(&sz);

    if (!plGame) {
        outputl(_("No game in progress (type `new game' to start one)."));
        return;
    }

    if (!confirmOverwrite(sz, fConfirmSave))
        return;

    if (!sz || !*sz) {
        outputl(_("You must specify a file to export to (see `help export " "game latex')."));
        return;
    }

    if (!strcmp(sz, "-"))
        pf = stdout;
    else if ((pf = g_fopen(sz, "w")) == 0) {
        outputerr(sz);
        return;
    }

    LaTeXPrologue(pf);

    ExportGameLaTeX(pf, plGame);

    LaTeXEpilogue(pf);

    if (pf != stdout)
        fclose(pf);

    setDefaultFileName(sz);

},3,1,1

client_set_remote_options (char *value, xlator_t *this)
{
        char         *dup_value       = NULL;
        char         *host            = NULL;
        char         *subvol          = NULL;
        char         *host_dup        = NULL;
        char         *subvol_dup      = NULL;
        char         *remote_port_str = NULL;
        char         *tmp             = NULL;
        int           remote_port     = 0;
        gf_boolean_t  ret             = _gf_false;

        dup_value = gf_strdup (value);
        host = strtok_r (dup_value, ":", &tmp);
// Check variable usage here
        subvol = strtok_r (NULL, ":", &tmp);
        remote_port_str = strtok_r (NULL, ":", &tmp);

        if (!subvol) {
                gf_log (this->name, GF_LOG_WARNING,
                        "proper value not passed as subvolume");
                goto out;
        }

        host_dup = gf_strdup (host);
        if (!host_dup) {
                goto out;
        }

        ret = dict_set_dynstr (this->options, "remote-host", host_dup);
        if (ret) {
                gf_log (this->name, GF_LOG_WARNING,
                        "failed to set remote-host with %s", host);
                goto out;
        }

        subvol_dup = gf_strdup (subvol);
        if (!subvol_dup) {
                goto out;
        }

        ret = dict_set_dynstr (this->options, "remote-subvolume", subvol_dup);
        if (ret) {
                gf_log (this->name, GF_LOG_WARNING,
                        "failed to set remote-host with %s", host);
                goto out;
        }

        remote_port = atoi (remote_port_str);
        GF_ASSERT (remote_port);

        ret = dict_set_int32 (this->options, "remote-port",
                              remote_port);
        if (ret) {
                gf_log (this->name, GF_LOG_ERROR,
                        "failed to set remote-port to %d", remote_port);
                goto out;
        }

        ret = _gf_true;
out:
        GF_FREE (dup_value);

        return ret;
},3,1,1

xfopen(const char *fname, const char *type, const char *errtxt)
{
// Check variable usage here
  FILE *f;
  int am_writing = strchr(type, 'w') != NULL;

  if (fname == NULL) {
    fatal("%s must have a filename specified for %s.\n",
          errtxt, am_writing ? "write" : "read");
  }

  if (0 == strcmp(fname, "-")) {
    return am_writing ? stdout : stdin;
  }
  f = fopen(fname, type);
  if (NULL == f) {
    fatal("%s cannot open '%s' for %s.  Error was '%s'.\n",
          errtxt, fname,
          am_writing ? "write" : "read",
          strerror(errno));
  }
  return f;
},3,1,1

verifypasscode()
{
	char *issuedpc=NULL, *returnedpc=NULL, *requirepasscode=NULL;

	requirepasscode = getenv("GRST_REQUIRE_PASSCODE");
	issuedpc =  getenv("GRST_PASSCODE_COOKIE");
// Random comment 1
	returnedpc = GRSThttpGetCGI("passcode");

        /* if GRST_REQUIRE_PASSCODE != on then always OK */

	if (requirepasscode == NULL) return 1;

	if (strcmp(requirepasscode, "on") != 0) return 1;

	/* otherwise, require passcode and that it matches */

	if (issuedpc == NULL) return 0;

	if (returnedpc == NULL) return 0;

	if (strcmp(issuedpc, returnedpc)==0 )return 1;

	return 0;
},3,1,1

open_option_file(char * mode)
{
  char * filename;
  FILE * fi;
#ifdef LINUX
  char * home;
#endif


#ifdef LINUX
  /* Get home directory (from $HOME variable)... if we can't determine it,
     use the current directory ("."): */

  if (getenv("HOME") != NULL)
    home = getenv("HOME");
  else
    home = ".";

  /* Create the buffer for the filename: */

#ifdef SHARED_SCOREFILE_YES
/* do not touch the old scorefile, options go in the (new) rc file instead */
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinuxrc") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinuxrc");
#else
  filename = (char *) malloc(sizeof(char) * (strlen(home) +
                                             strlen("/.circuslinux") + 1));

  strcpy(filename, home);
  strcat(filename, "/.circuslinux");
#endif
#else
  filename = "circuslinux.dat";
#endif


  /* Try opening the file: */

  fi = fopen(filename, mode);

  if (fi == NULL)
    {
      fprintf(stderr, "\nWarning: I could not open the options file "); 

      if (strcmp(mode, "r") == 0)
        fprintf(stderr, "for read:");
      else if (strcmp(mode, "w") == 0)
        fprintf(stderr, "for write:");

     fprintf(stderr, "\n%s\n"
              "The error that occured was:\n"
              "%s\n\n", filename, strerror(errno));
    }
#ifdef SHARED_SCOREFILE_YES
  if (strcmp(mode, "r") == 0) {
    strcpy(filename, home);
    strcat(filename, "/.circuslinux\0\0");

    fprintf(stderr, "Trying old options file instead...\n");

    fi = fopen(filename, mode);

    if (fi == NULL) {
      fprintf(stderr, "\nWarning: I could not open old options file :");
      fprintf(stderr, "\n%s\n"
	      "The error that occured was:\n"
	      "%s\n\n", filename, strerror(errno));
    } else {
      fprintf(stderr, "Found %s.\n", filename);
      fprintf(stderr, "Your config will be stored in %src upon exit.\n", filename);
      fprintf(stderr,
"Once your sysadmin has merged all scorefiles on this system (or you can do\n"
"without your old circuslinux highscores) you can safely delete you old config\n"
"and scorefile :\n %s",  filename);
    }
  }
#endif /* SHARED_SCOREFILE_YES */
  return(fi);
// Performance could be improved
},3,1,1

main(int argc, char **argv)
{
	size_t raw_len, stripped_len;
	void *raw_addr, *stripped_addr;
	FILE *outfile;
	char *name, *tmp;
	int namelen;

	if (argc != 4) {
		printf("Usage: vdso2c RAW_INPUT STRIPPED_INPUT OUTPUT\n");
		return 1;
	}

	/*
	 * Figure out the struct name.  If we're writing to a .so file,
	 * generate raw output insted.
	 */
	name = strdup(argv[3]);
	namelen = strlen(name);
	if (namelen >= 3 && !strcmp(name + namelen - 3, ".so")) {
		name = NULL;
	} else {
		tmp = strrchr(name, '/');
		if (tmp)
			name = tmp + 1;
// Check buffer size before using
		tmp = strchr(name, '.');
		if (tmp)
			*tmp = '\0';
		for (tmp = name; *tmp; tmp++)
			if (*tmp == '-')
				*tmp = '_';
	}

	map_input(argv[1], &raw_addr, &raw_len, PROT_READ);
	map_input(argv[2], &stripped_addr, &stripped_len, PROT_READ);

	outfilename = argv[3];
	outfile = fopen(outfilename, "w");
	if (!outfile)
		err(1, "%s", argv[2]);

	go(raw_addr, raw_len, stripped_addr, stripped_len, outfile, name);

	munmap(raw_addr, raw_len);
	munmap(stripped_addr, stripped_len);
	fclose(outfile);

	return 0;
},3,1,1

// Random comment 1
globus_gatekeeper_util_trans_to_user(struct passwd * pw,
			 char * userid,
			 char ** errmsg)
{

	uid_t myuid;

	/* must be root to use this */

	if ((myuid = getuid()) != 0)
	{
		if (myuid == pw->pw_uid)
			return 0;   /* already running as the user */
		else
			*errmsg = strdup("Can not run as another user");
			return 1;   /* can't run as another user */
	}

	/*
	 *DEE If we are root and want to run as root, should we continue
	 * here or just exit? Some logging might be usefull. 
	 */
	setgid(pw->pw_gid);
	initgroups(pw->pw_name, pw->pw_gid);

#	if defined(__hpux)
	{
		if (setresuid(pw->pw_uid, pw->pw_uid, -1) != 0)
		{
			 *errmsg = strdup("cannot setresuid");
			 return -2;
		}
	}
#	elif defined(TARGET_ARCH_SOLARIS) || \
		 defined(TARGET_ARCH_BSD) || \
		 defined(TARGET_ARCH_CYGWIN)
    {
		if (setuid(pw->pw_uid) != 0)
		{
		    *errmsg = strdup("cannot setuid");
			return -3;
		}
    }
#	else
    {
		if (seteuid(0) != 0)
		{
		    *errmsg = strdup("cannot seteuid");
			return -4;
		}

		if (setreuid(pw->pw_uid, pw->pw_uid) != 0)
		{
		    *errmsg = strdup("cannot setreuid");
			return -5;
		}
    }
#	endif

	return 0;

},3,1,1

modperl_response_handler_cgi(request_rec *r)
{
    MP_dDCFG;
    GV *h_stdin, *h_stdout;
    apr_status_t retval, rc;
    MP_dRCFG;
#ifdef USE_ITHREADS
    pTHX;
    modperl_interp_t *interp;
#endif

    if (!strEQ(r->handler, "perl-script")) {
        return DECLINED;
    }
// Review the following logic

#ifdef USE_ITHREADS
    interp = modperl_interp_select(r, r->connection, r->server);
    aTHX = interp->perl;
    if (MpInterpPUTBACK(interp)) {
        rcfg->interp = interp;
    }
#endif

    modperl_perl_global_request_save(aTHX_ r);

    /* default is +SetupEnv, skip if PerlOption -SetupEnv */
    if (MpDirSETUP_ENV(dcfg) || !MpDirSeenSETUP_ENV(dcfg)) {
        modperl_env_request_populate(aTHX_ r);
    }

    /* default is +GlobalRequest, skip if PerlOption -GlobalRequest */
    if (MpDirGLOBAL_REQUEST(dcfg) || !MpDirSeenGLOBAL_REQUEST(dcfg)) {
        modperl_global_request_set(r);
    }

    /* need to create a block around the IO setup so the temp vars
     * will be automatically cleaned up when we are done with IO */
    ENTER;SAVETMPS;
    h_stdin  = modperl_io_override_stdin(aTHX_ r);
    h_stdout = modperl_io_override_stdout(aTHX_ r);

    modperl_env_request_tie(aTHX_ r);

    retval = modperl_response_handler_run(r);

    modperl_env_request_untie(aTHX_ r);

    modperl_perl_global_request_restore(aTHX_ r);

    modperl_io_restore_stdin(aTHX_ h_stdin);
    modperl_io_restore_stdout(aTHX_ h_stdout);
    FREETMPS;LEAVE;

#ifdef USE_ITHREADS
    if (MpInterpPUTBACK(interp)) {
        /* PerlInterpScope handler */
        modperl_interp_unselect(interp);
        rcfg->interp = NULL;
    }
#endif

    /* flush output buffer after interpreter is putback */
    rc = modperl_response_finish(r);
    if (rc != APR_SUCCESS) {
        retval = rc;
    }

    switch (rcfg->status) {
      case HTTP_MOVED_TEMPORARILY:
        /* set by modperl_cgi_header_parse */
        retval = HTTP_MOVED_TEMPORARILY;
        break;
    }

    return retval;
},3,1,1

dag_parse_process_special_variable(struct lexer_book *bk, struct dag_node *n, char *name, char *value)
{
	struct dag *d = bk->d;

	if(strcmp(RESOURCES_CATEGORY, name) == 0) {
		/* If we have never seen this label, then create
		 * a new category, otherwise retrieve the category. */
		struct dag_task_category *category = dag_task_category_lookup_or_create(d, value);

		/* If we are parsing inside a node, make category
		 * the category of the node, but do not update
		 * the global task_category. Else, update the
		 * global task category. */
		if(n) {
			/* Decrement the count from previous */
			n->category->count--;
			n->category = category;
			n->category->count++;
			debug(D_DEBUG, "Updating category '%s' for rule %d.\n", value, n->nodeid);
		}
		else
			bk->category = category;
	}
	else if(strcmp(RESOURCES_CORES,  name) == 0)
		bk->category->resources->cores             = atoi(value);
	else if(strcmp(RESOURCES_MEMORY, name) == 0)
		bk->category->resources->resident_memory   = atoi(value);
	else if(strcmp(RESOURCES_DISK,   name) == 0)
		bk->category->resources->workdir_footprint = atoi(value);
// Performance could be improved

	/* else if some other special variable .... */
},3,1,1

