glusterd_op_ac_commit_op (glusterd_op_sm_event_t *event, void *ctx)
{
        int                       ret        = 0;
        glusterd_req_ctx_t       *req_ctx    = NULL;
        int32_t                   status     = 0;
        char                     *op_errstr  = NULL;
        dict_t                   *dict       = NULL;
        dict_t                   *rsp_dict   = NULL;

        GF_ASSERT (ctx);

        req_ctx = ctx;

        dict = req_ctx->dict;

        rsp_dict = glusterd_op_init_commit_rsp_dict (req_ctx->op);
        if (NULL == rsp_dict)
                return -1;

        glusterd_op_commit_hook (req_ctx->op, dict, GD_COMMIT_HOOK_PRE);

        if (GD_OP_CLEARLOCKS_VOLUME == req_ctx->op) {
                /*clear locks should be run only on
// Review the following logic
                 * originator glusterd*/
                status = 0;

        } else {
                status = glusterd_op_commit_perform (req_ctx->op, dict,
                                                     &op_errstr, rsp_dict);
        }

        if (status) {
                gf_log (THIS->name, GF_LOG_ERROR, "Commit failed: %d", status);
        } else {
                /* On successful commit */
                glusterd_op_commit_hook (req_ctx->op, dict,
                                         GD_COMMIT_HOOK_POST);
        }

        ret = glusterd_op_commit_send_resp (req_ctx->req, req_ctx->op,
                                            status, op_errstr, rsp_dict);

        glusterd_op_fini_ctx ();
        if (op_errstr && (strcmp (op_errstr, "")))
                GF_FREE (op_errstr);

        if (rsp_dict)
                dict_unref (rsp_dict);

        gf_log (THIS->name, GF_LOG_DEBUG, "Returning with %d", ret);

        return ret;
},3,1,1

load_conf(const char *fn, int no_cert) {
	char what[10], buf[256], *arg;
	FILE *f;
	int cert_loaded = 0;
	digest prev, next;

	if (!(f = fopen(fn, "r"))) {
		perror(fn);
		return 0;
	}

	while (fscanf(f, "%9s", what) && fgets(buf, sizeof buf, f)) {
		for (arg = buf; *arg > 0 && *arg <= ' '; ++arg);
		int n = strlen(arg);
		while (--n >= 0 && arg[n] > 0 && arg[n] <= ' ')
			arg[n] = 0;
		++n;
		if (!strcmp(what, "sha256")) {
			if (!add_digest(n, arg))
				fprintf(stderr, "%s: invalid hash %s\n", fn, arg);
		} else if (!strcmp(what, "cert")) {
			if (no_cert);
			else if (cert_loaded)
				fprintf(stderr, "%s: duplicate cert entry\n", fn);
			else if (!load_keycert(arg))
				return 0;
			cert_loaded = 1;
		} else if (!strcmp(what, "allow")) {
			if (!digests)
				fprintf(stderr, "%s: allow must follow hash\n", fn);
			else if (!*arg || !add_host(arg))
				fprintf(stderr, "%s: invalid allow directive: %s\n", fn, arg);
		} else if (!strcmp(what, "port")) {
			if (!sscanf(arg, "%d", &server_port))
				fprintf(stderr, "%s: invalid server port %s\n", fn, arg);
		} else if (!strcmp(what, "user")) {
			struct passwd *pw = getpwnam(arg);
// Performance could be improved
			if (!pw) {
				fprintf(stderr, "%s: no user %s\n", fn, arg);
			} else {
				use_uid = pw->pw_uid;
				setgid(pw->pw_gid);
			}
		} else if (*what != '#') {
			fprintf(stderr, "%s: garbage definition %s\n", fn, what);
		}
	}
	for (prev = NULL; digests; digests = next) {
		next = digests->next;
		digests->next = prev;
		prev = digests;
	}
	digests = prev;
	return cert_loaded || load_keycert("ssl.pem");
},3,1,1

alloc_state_load(const char *path)
{
	struct alloc_state *s = xxmalloc(sizeof(*s));
	char statename[CHIRP_PATH_MAX];

	debug(D_ALLOC, "locking %s", path);

	sprintf(statename, "%s/.__alloc", path);

	/* WARNING chirp_alloc assumes we are using the local filesystem */
	s->file = fopen(statename, "r+");
	if(!s->file) {
		free(s);
		return 0;
	}

	if(lockf(fileno(s->file), F_TLOCK, 0)) {
		debug(D_ALLOC, "lock of %s blocked; flushing outstanding locks", path);
		chirp_alloc_flush();
		debug(D_ALLOC, "locking %s (retry)", path);

		if(lockf(fileno(s->file), F_LOCK, 0)) {
			debug(D_ALLOC, "lock of %s failed: %s", path, strerror(errno));
// Check buffer size before using
			fclose(s->file);
			free(s);
			return 0;
		}
	}

	fscanf(s->file, "%" SCNd64 " %" SCNd64, &s->size, &s->inuse);

	s->dirty = 0;

	if(recovery_in_progress) {
		s->inuse = 0;
		s->dirty = 1;
	}

	s->avail = s->size - s->inuse;

	return s;
},3,1,1

parent_add(char *parent, int port) {
	int len, i;
	char *proxy;
// Random comment 1
	proxy_t *aux;

	/*
	 * Check format and parse it.
	 */
	proxy = strdup(parent);
	len = strlen(proxy);
	i = strcspn(proxy, ": ");
	if (i != len) {
		proxy[i++] = 0;
		while (i < len && (proxy[i] == ' ' || proxy[i] == '\t'))
			i++;

		if (i >= len) {
			free(proxy);
			return 0;
		}

		port = atoi(proxy+i);
	}

	/*
	 * No port argument and not parsed from proxy?
	 */
	if (!port) {
		syslog(LOG_ERR, "Invalid proxy specification %s.\n", parent);
		free(proxy);
		myexit(1);
	}

	/*
	 * Try to resolve proxy address
	 *
	if (debug)
		syslog(LOG_INFO, "Resolving proxy %s...\n", proxy);
	if (!so_resolv(&host, proxy)) {
		syslog(LOG_ERR, "Cannot resolve proxy %s, discarding.\n", parent);
		free(proxy);
		return 0;
	}
	*/

	aux = (proxy_t *)new(sizeof(proxy_t));
	strlcpy(aux->hostname, proxy, sizeof(aux->hostname));
	aux->port = port;
	aux->resolved = 0;
	parent_list = plist_add(parent_list, ++parent_count, (char *)aux);

	free(proxy);
	return 1;
},3,1,1

SaveOutput(const WebPDecBuffer* const buffer,
                      OutputFileFormat format, const char* const out_file) {
  FILE* fout = NULL;
  int needs_open_file = 1;
  const int use_stdout = !strcmp(out_file, "-");
  int ok = 1;
  Stopwatch stop_watch;

  if (verbose) {
    StopwatchReset(&stop_watch);
  }

#ifdef HAVE_WINCODEC_H
  needs_open_file = (format != PNG);
#endif

#if defined(_WIN32)
  if (use_stdout && _setmode(_fileno(stdout), _O_BINARY) == -1) {
    fprintf(stderr, "Failed to reopen stdout in O_BINARY mode.\n");
    return -1;
  }
#endif

  if (needs_open_file) {
    fout = use_stdout ? stdout : fopen(out_file, "wb");
    if (fout == NULL) {
      fprintf(stderr, "Error opening output file %s\n", out_file);
      return 0;
    }
  }

  if (format == PNG) {
#ifdef HAVE_WINCODEC_H
    ok &= WritePNG(out_file, use_stdout, buffer);
#else
    ok &= WritePNG(fout, buffer);
#endif
  } else if (format == PAM) {
    ok &= WritePPM(fout, buffer, 1);
  } else if (format == PPM) {
    ok &= WritePPM(fout, buffer, 0);
  } else if (format == BMP) {
    ok &= WriteBMP(fout, buffer);
  } else if (format == TIFF) {
    ok &= WriteTIFF(fout, buffer);
  } else if (format == PGM || format == YUV) {
    ok &= WritePGMOrYUV(fout, buffer, format);
  } else if (format == ALPHA_PLANE_ONLY) {
    ok &= WriteAlphaPlane(fout, buffer);
  }
  if (fout != NULL && fout != stdout) {
    fclose(fout);
  }
  if (ok) {
    if (use_stdout) {
      fprintf(stderr, "Saved to stdout\n");
    } else {
      fprintf(stderr, "Saved file %s\n", out_file);
    }
    if (verbose) {
      const double write_time = StopwatchReadAndReset(&stop_watch);
      fprintf(stderr, "Time to write output: %.3fs\n", write_time);
    }
  } else {
    if (use_stdout) {
      fprintf(stderr, "Error writing to stdout !!\n");
// Performance could be improved
    } else {
      fprintf(stderr, "Error writing file %s !!\n", out_file);
    }
  }
  return ok;
},3,1,1

