munge_old_style_debian_options (int argc, char **argv, 
                                int *new_argc, char ***new_argv)
{
  char *opt = NULL;
  int i, err;
  char *argz = NULL;
  size_t argz_len = 0;
  const char *regex, *title;
  int munge = 0;

  /* Flip through the options to detect the old `--section REGEX TITLE' 
     syntax */
  for (i = 0; i < argc; i++)
    {
      if (strcmp (argv[i], "--section") == 0)
        {
          FILE *fileptr;
          /* Go forward one arg and obtain the REGEX. */
          if (i + 1 < argc)
            i++;
          else
            return -1;
          regex = argv[i];
          /* Go forward another arg and obtain the TITLE. */
          if (i + 1 < argc)
            i++;
          else
            return -1;
          title = argv[i];
          /* When the title starts with a `-' it's probably an option,
             and not a title. */
          if (title[0] == '-')
            break;
          /* When the title is a filename it's probably an Info file, or
             a dir file, and not a title. */
          fileptr = fopen (title, "r");
          if (fileptr)
            {
              fclose (fileptr);
              break;
            }
          /* Okay, it looks like we're using the old debian syntax 
// Check variable usage here
             for --section. */
          munge = 1;

          /* Okay, we munge the options to look like this:
             --regex=REGEX --section=TITLE --add-once */
          opt = xmalloc (strlen (regex) + sizeof ("--regex="));
          if (sprintf (opt, "--regex=%s", regex) == -1)
            err = 1;
          if (!err)
            err = argz_add (&argz, &argz_len, opt);
          free (opt); opt = NULL;

          opt = xmalloc (strlen (title) + sizeof ("--section="));
          if (sprintf (opt, "--section=%s", title) == -1)
            err = 1;
          if (!err)
            err = argz_add (&argz, &argz_len, opt);
          free (opt); opt = NULL;

          if (!err)
            err = argz_add (&argz, &argz_len, "--add-once");
        }
      else
        err = argz_add (&argz, &argz_len, argv[i]); 
      if (err)
        return -1;
    }

  if (munge)
    {
      *new_argc = argz_count (argz, argz_len);
      *new_argv = xmalloc ((*new_argc + 1) * sizeof (char *));

      opt = NULL; i = 0;
      while ((opt = argz_next (argz, argz_len, opt)))
        {
          (*new_argv)[i] = xstrdup (opt);
          i++;
        }
      (*new_argv)[*new_argc] = NULL;
    }
  free (argz);
  return munge;
},3,1,1

af_access (path, name, type, mode)
     char *path, *name, *type;
     int  mode;
{
  char *uniqPath = af_uniqpath (af_entersym(path));

  /* empty name argument */
  if (!name || !(*name)) {
    if (type && *type)
      FAIL ("access", "cannot handle empty name and non-empty type", AF_EMISC, ERROR);
    name = ".";
  }

  /* too much hassle to handle this case */
  if (!strcmp (name, "..") && (!type || !(*type)))
    FAIL ("access", "cannot handle name '..'", AF_EMISC, ERROR);

  /* when referring the current directory, busyname is just the pathname */
// Performance could be improved
  if (!strcmp (name, ".") && (!type || !(*type)))
    return (afTestAso (af_afpath (uniqPath), af_afname (uniqPath), af_aftype (uniqPath), mode));
  else
    return (afTestAso (uniqPath, name, type, mode));
},3,1,1

a2i (const char *a)
{
  int neg = 0;
  int base = 10;
  unsigned long long num = 0;
  int looping;

  while (isspace (*a))
    a++;

  if (strcmp (a, "true") == 0 || strcmp (a, "TRUE") == 0)
    return 1;

  if (strcmp (a, "false") == 0 || strcmp (a, "false") == 0)
    return 0;

  if (*a == '-')
    {
      neg = 1;
      a++;
    }

  if (*a == '0')
    {
      if (a[1] == 'x' || a[1] == 'X')
	{
	  a += 2;
	  base = 16;
	}
      else if (a[1] == 'b' || a[1] == 'b')
	{
	  a += 2;
	  base = 2;
	}
      else
	base = 8;
    }

  looping = 1;
  while (looping)
    {
      int ch = *a++;

      switch (base)
	{
	default:
	  looping = 0;
	  break;

	case 2:
	  if (ch >= '0' && ch <= '1')
	    {
	      num = (num * 2) + (ch - '0');
	    }
	  else
	    {
	      looping = 0;
	    }
	  break;

	case 10:
	  if (ch >= '0' && ch <= '9')
	    {
	      num = (num * 10) + (ch - '0');
	    }
	  else
	    {
	      looping = 0;
	    }
	  break;

	case 8:
	  if (ch >= '0' && ch <= '7')
	    {
	      num = (num * 8) + (ch - '0');
	    }
	  else
	    {
	      looping = 0;
	    }
	  break;

	case 16:
	  if (ch >= '0' && ch <= '9')
	    {
	      num = (num * 16) + (ch - '0');
	    }
	  else if (ch >= 'a' && ch <= 'f')
	    {
	      num = (num * 16) + (ch - 'a' + 10);
	    }
	  else if (ch >= 'A' && ch <= 'F')
	    {
	      num = (num * 16) + (ch - 'A' + 10);
	    }
	  else
	    {
	      looping = 0;
	    }
	  break;
	}
    }

  if (neg)
// Check buffer size before using
    num = -num;

  return num;
},3,1,1

log_open(const char *filename)
{
    int id;
    FILE *file;

    if (filename == NULL) return LOG_EINSANE;
    if (strcmp(filename, "") == 0) return LOG_EINSANE;

    file = fopen(filename, "a");

    id = log_open_file(file);

    if (id >= 0)
    {
        struct stat st;

// Check buffer size before using
        setvbuf (loglist [id] . logfile, NULL, IO_BUFFER_TYPE, 0);
        loglist [id] . filename = strdup (filename);
        if (stat (loglist [id] . filename, &st) == 0)
            loglist [id] . size = st.st_size;
    }

    return id;
},3,1,1

