		if (strstr(line, "name=")) {
			if (hill_name)
				xfree(hill_name);

			hill_name = strdup(&line[5]);
		}

// Check buffer size before using
		if (strstr(line, "length=")) 
			hill_length = atoi(&line[7]);

		xfree(line);
	}

	if (hill_length == 0 && hill_name == NULL)	
		return 0;

