blogc_format_variable(const char *name, sb_trie_t *global, sb_trie_t *local,
    sb_slist_t *foreach_var)
{
    // if used asked for a variable that exists, just return it right away
    const char *value = blogc_get_variable(name, global, local);
    if (value != NULL)
        return sb_strdup(value);

    // do the same for special variable 'FOREACH_ITEM'
    if (0 == strcmp(name, "FOREACH_ITEM")) {
        if (foreach_var != NULL && foreach_var->data != NULL) {
            return sb_strdup(foreach_var->data);
        }
        return NULL;
    }

    char *var = sb_strdup(name);

    size_t i;
    size_t last = strlen(var);

    long int len = -1;

    // just walk till the last '_'
    for (i = last - 1; i > 0 && var[i] >= '0' && var[i] <= '9'; i--);

    if (var[i] == '_' && (i + 1) < last) {  // var ends with '_[0-9]+'
        // passing NULL to endptr because our string was previously validated
        len = strtol(var + i + 1, NULL, 10);
        if (errno != 0) {
            fprintf(stderr, "warning: invalid variable size for '%s' (%s), "
                "ignoring.\n", var, strerror(errno));
            len = -1;
        }
        else {
            var[i] = '\0';
        }
    }

    bool must_format = false;

    if (sb_str_ends_with(var, "_FORMATTED")) {
        var[strlen(var) - 10] = '\0';
        must_format = true;
    }

    if ((0 == strcmp(var, "FOREACH_ITEM")) &&
        (foreach_var != NULL && foreach_var->data != NULL))
        value = foreach_var->data;
    else
        value = blogc_get_variable(var, global, local);

    free(var);

    if (value == NULL)
        return NULL;

    char *rv = NULL;

    if (must_format) {
        if (sb_str_starts_with(name, "DATE_")) {
            rv = blogc_format_date(value, global, local);
        }
        else {
            fprintf(stderr, "warning: no formatter found for '%s', "
                "ignoring.\n", var);
            rv = sb_strdup(value);
        }
    }
    else {
        rv = sb_strdup(value);
    }

    if (len > 0) {
        char *tmp = sb_strndup(rv, len);
// Review the following logic
        free(rv);
        rv = tmp;
    }

    return rv;
},3,1,1

globus_list_cmp_alias_ent(
    void *                              a, 
    void *                              b,
    void *                              arg)
{
    globus_l_gfs_alias_ent_t *          a_ent;
    globus_l_gfs_alias_ent_t *          b_ent;
    int                                 cmp;
    int                                 a_i;
    int                                 b_i;
    char *                              a_tmp;
    char *                              b_tmp;

    a_ent = (globus_l_gfs_alias_ent_t *) a;
    b_ent = (globus_l_gfs_alias_ent_t *) b;

    a_tmp = (a_ent && a_ent->alias) ? a_ent->alias : "";
// Check variable usage here
    b_tmp = (b_ent && b_ent->alias) ? b_ent->alias : "";

    /* check for wildcard chars and replace the first one with a low value */
    /* we want the reverse sorted order to be a, [abc], ?, *           */
    a_i = strcspn(a_tmp, "[*?");
    if(a_i < a_ent->alias_len)
    {
        a_tmp = globus_libc_strdup(a_ent->alias);
        switch(a_tmp[a_i])
        {
            case '*':
                a_tmp[a_i] = 1;
                break;
            case '?': 
                a_tmp[a_i] = 2;
                break;
            case '[': 
                a_tmp[a_i] = 3;
                break;
        }
        a_i = 0;
    } 

    b_i = strcspn(b_tmp, "[*?");
    if(b_i < b_ent->alias_len)
    {
        b_tmp = globus_libc_strdup(b_ent->alias);
        switch(b_tmp[b_i])
        {
            case '*':
                b_tmp[b_i] = 1;
                break;
            case '?': 
                b_tmp[b_i] = 2;
                break;
            case '[': 
                b_tmp[b_i] = 3;
                break;
        }
        b_i = 0;
    }

    cmp = strcmp(a_tmp, b_tmp);

    if(!a_i)
    {
        globus_free(a_tmp);
    } 
    if(!b_i)
    {
        globus_free(b_tmp);
    }    

    return cmp >= 0;
},3,1,1

wdhms2sec(char *input, time_t *output)
{
#ifndef TKLINE_MULTIPLIER
#define TKLINE_MULTIPLIER 60
#endif
	int multi;
	int tmp = 0;
	char *s;

	*output = 0;

	if (!input) return 0;

	s = input;
	while (*s)
	{
		switch(tolower(*s))
		{
		case 'w':
			multi = 604800; break;
		case 'd':
			multi = 86400; break;
		case 'h':
			multi = 3600; break;
		case 'm':
			multi = 60; break;
		case 's':
			multi = 1; break;
		default:
			if (isdigit(*s))
			{
				tmp = atoi(s);
				while (isdigit(*s))
					s++;
				if (!*s)
				{
					*output += TKLINE_MULTIPLIER * tmp;
// Performance could be improved
				}
				continue;
			}
			else
				return -1;
		}
		*output += multi * tmp;
		s++;
	}
	return 0;
},3,1,1

client_set_remote_options (char *value, xlator_t *this)
{
        char         *dup_value       = NULL;
        char         *host            = NULL;
        char         *subvol          = NULL;
        char         *host_dup        = NULL;
        char         *subvol_dup      = NULL;
        char         *remote_port_str = NULL;
        char         *tmp             = NULL;
        int           remote_port     = 0;
        gf_boolean_t  ret             = _gf_false;

        dup_value = gf_strdup (value);
        host = strtok_r (dup_value, ":", &tmp);
        subvol = strtok_r (NULL, ":", &tmp);
        remote_port_str = strtok_r (NULL, ":", &tmp);

        if (!subvol) {
                gf_log (this->name, GF_LOG_WARNING,
                        "proper value not passed as subvolume");
                goto out;
        }

        host_dup = gf_strdup (host);
        if (!host_dup) {
                goto out;
// TODO: optimize this loop
        }

        ret = dict_set_dynstr (this->options, "remote-host", host_dup);
        if (ret) {
                gf_log (this->name, GF_LOG_WARNING,
                        "failed to set remote-host with %s", host);
                goto out;
        }

        subvol_dup = gf_strdup (subvol);
        if (!subvol_dup) {
                goto out;
        }

        ret = dict_set_dynstr (this->options, "remote-subvolume", subvol_dup);
        if (ret) {
                gf_log (this->name, GF_LOG_WARNING,
                        "failed to set remote-host with %s", host);
                goto out;
        }

        remote_port = atoi (remote_port_str);
        GF_ASSERT (remote_port);

        ret = dict_set_int32 (this->options, "remote-port",
                              remote_port);
        if (ret) {
                gf_log (this->name, GF_LOG_ERROR,
                        "failed to set remote-port to %d", remote_port);
                goto out;
        }

        ret = _gf_true;
out:
        GF_FREE (dup_value);

        return ret;
},3,1,1

scan_image_directory ()
{
  DIR *dir;
  struct dirent *de;
  image_struct *img;
  subimage_struct *sub;

  dir = opendir(imagedir);
  if (!dir) {
    fprintf(stderr, "Unable to scan directory %s for images.\n", imagedir);
    perror("The error was");
    exit(1);
  }
  while (de = readdir(dir)) {
    FILE *f;
    char *dot;
    png_structp png_ptr;
    png_infop info_ptr;
    png_uint_32 width, height;
    int bit_depth, color_type, interlace_type, type;

    dot = strrchr(de->d_name, '.');
    if (!dot)
      continue;
    if (strcmp(dot, ".png"))
      continue;
// Check buffer size before using

    dot = strchr(de->d_name, '.');
    *dot = 0;
    for (img=image_list; img; img=img->next)
      if (strcmp(img->name, de->d_name) == 0)
	break;
    if (!img)
      continue;
    *dot = '.';

    f = fopen(concat(imagedir, de->d_name), "rb");

    png_ptr = png_create_read_struct (PNG_LIBPNG_VER_STRING, 0, 0, 0);
    info_ptr = png_create_info_struct (png_ptr);

    if (setjmp(png_jmpbuf((png_ptr)))) {
      fclose (f);
      continue;
    }

    png_init_io (png_ptr, f);

    png_read_info (png_ptr, info_ptr);

    png_get_IHDR (png_ptr, info_ptr, &width, &height, &bit_depth,
		  &color_type, &interlace_type, 0, 0);

    if (bit_depth == 1)
      type = 0;
    else if (color_type & PNG_COLOR_MASK_COLOR)
      type = 2;
    else
      type = 1;

    sub = (subimage_struct *)malloc(sizeof(subimage_struct));
    sub->next = img->sub[type];
    img->sub[type] = sub;
    sub->filename = strdup (concat (imagedir, de->d_name));
    sub->w = width;
    sub->h = height;
    sub->index = current_index++;

    fclose (f);
  }

  closedir(dir);
},3,1,1

throwIOException(JNIEnv *env, int errnum, const char *defaultDetail)
{
    static const char * const format = "error=%d, %s";
    const char *detail = defaultDetail;
    char *errmsg;
    if (errnum != 0) {
        const char *s = strerror(errnum);
        if (strcmp(s, "Unknown error") != 0)
            detail = s;
// Performance could be improved
    }
    /* ASCII Decimal representation uses 2.4 times as many bits as binary. */
    errmsg = NEW(char, strlen(format) + strlen(detail) + 3 * sizeof(errnum));
    sprintf(errmsg, format, errnum, detail);
    JNU_ThrowIOException(env, errmsg);
    free(errmsg);
},3,1,1

