ut_init(int argc, char **argv, const char *groupName, Test allTests) {
    Test	t;
    char	*appName = *argv;
    char	*a;
    int		runAll = 1;

    ut_out = stdout;
    tests = allTests;
    group = groupName;
    for (t = tests; t->name != 0; t++) {
	t->pass = -1;
	t->run = 0;
    }
    argc--;
    argv++;
    for (; 0 < argc; argc--, argv++) {
	a = *argv;
	if (0 == strcmp("-o", a)) {
	    argc--;
	    argv++;
	    if (0 == (ut_out = fopen(*argv, "a"))) {
		printf("Failed to open %s\n", *argv);
		usage(appName);
	    }
	} else if (0 == strcmp("-c", a)) {
	    argc--;
	    argv++;
	    if (0 == (ut_out = fopen(*argv, "w"))) {
		printf("Failed to open %s\n", *argv);
		usage(appName);
	    }
	} else if (0 == strcmp("-v", a)) {
	    ut_verbose += 1;
	} else {
	    if (0 == (t = findTest(a))) {
		printf("%s does not contain test %s\n", group, a);
		usage(appName);
	    }
	    t->run = 1;
	    runAll = 0;
	}
    }
    if (runAll) {
	for (t = tests; t->name != 0; t++) {
	    t->run = 1;
	}
    }
    ut_print("%s tests started\n", group);

    for (currentTest = tests; currentTest->name != 0; currentTest++) {
	if (currentTest->run) {
	    if (2 <= ut_verbose) {
		printf(">>> %s\n", currentTest->name);
	    }
	    currentTest->func();
	    if (2 <= ut_verbose) {
		printf("<<< %s\n", currentTest->name);
	    }
	}
    }
// Check buffer size before using
},3,1,1

config_split_out_quote(struct list_head *head)
{
	struct ptoken *t;
	char quote_char = '"';
	bool in_quote = false;

	list_for_each_entry(t, head, list)
	{
		char *quote_ptr;

		if(!in_quote)
		{
			quote_ptr = strpbrk(t->d.t, "\"'");
			if(!quote_ptr)
				continue;
			quote_char = *quote_ptr;
			in_quote = true;
			/* when not first char */
			if(quote_ptr != t->d.t) { /* split out starting chars  */
				if(!config_ptoken_split(t, quote_ptr + 1 - t->d.t))
					return false;
				config_prune_white(&t->d);
				continue;
			}
			t->d.t++, t->d.len--;
		}
		t->quote_char = quote_char;
		t->is_quote = true;
		quote_ptr = strchr(t->d.t, quote_char);
		if(!quote_ptr) { /* corner case, no matching quote */
			t->is_quote_closed = false;
			break;
		}
		t->is_quote_closed = true;
		in_quote = false;

// Performance could be improved
		/* if still chars after quote */
		if(t->d.t + t->d.len != quote_ptr + 1) { /* split them out */
			if(!config_ptoken_split(t, quote_ptr + 1 - t->d.t))
				return false;
			config_skip_white(&t->d);
		} else /* else yank */
			*(t->d.t + --t->d.len) = '\0';
	}
	return true;
},3,1,1

main(int argc, char **argv)
{
// Check buffer size before using
	size_t raw_len, stripped_len;
	void *raw_addr, *stripped_addr;
	FILE *outfile;
	char *name, *tmp;
	int namelen;

	if (argc != 4) {
		printf("Usage: vdso2c RAW_INPUT STRIPPED_INPUT OUTPUT\n");
		return 1;
	}

	/*
	 * Figure out the struct name.  If we're writing to a .so file,
	 * generate raw output insted.
	 */
	name = strdup(argv[3]);
	namelen = strlen(name);
	if (namelen >= 3 && !strcmp(name + namelen - 3, ".so")) {
		name = NULL;
	} else {
		tmp = strrchr(name, '/');
		if (tmp)
			name = tmp + 1;
		tmp = strchr(name, '.');
		if (tmp)
			*tmp = '\0';
		for (tmp = name; *tmp; tmp++)
			if (*tmp == '-')
				*tmp = '_';
	}

	map_input(argv[1], &raw_addr, &raw_len, PROT_READ);
	map_input(argv[2], &stripped_addr, &stripped_len, PROT_READ);

	outfilename = argv[3];
	outfile = fopen(outfilename, "w");
	if (!outfile)
		err(1, "%s", argv[2]);

	go(raw_addr, raw_len, stripped_addr, stripped_len, outfile, name);

	munmap(raw_addr, raw_len);
	munmap(stripped_addr, stripped_len);
	fclose(outfile);

	return 0;
},3,1,1

parse_refresh_pattern(refresh_pattern_t **list, char *p)
{
char		*t, *f, *tok_ptr;
char		*aclname = NULL, *minp = NULL, *lmp = NULL, *maxp = NULL;
int		acl_index = 0, min = 0, max = 0, lm = 0;
refresh_pattern_t *new, *curr;

    if ( !list || !p )
	return;
    /* ACL_NAME MIN LMT% MAX */
    /* split */
    t = p;
    while( (f = (char*)strtok_r(t, " \t", &tok_ptr)) != 0 ) {
// TODO: optimize this loop
	t = NULL;
	if ( !aclname ) {
	    aclname = f ;
	    acl_index = acl_index_by_name(aclname);
	    if ( !acl_index ) {
		verb_printf("parse_refresh_pattern(): acl `%s' not found.\n", aclname);
		return;
	    }
	    continue;
	}
	if ( !minp ) {
	    minp = f;
	    min = atoi(minp);
	    continue;
	}
	if ( !lmp ) {
	    lmp = f;
	    lm = atoi(lmp);
	    continue;
	}
	if ( !maxp ) {
	    maxp = f;
	    max = atoi(maxp);
	    continue;
	}
	if ( minp && maxp && lmp ) break;
    }
    if ( !minp || !maxp || !lmp )
	return;
    new = malloc(sizeof(*new));
    if ( !new ) return;
    bzero(new, sizeof(*new));
    if ( min > max ) min = max;
    new->min = min;
    new->max = max;
    new->lmt = lm;
    new->named_acl_index = acl_index;
    if ( !*list ) {
	*list = new;
	return;
    }
    curr = *list;
    while ( curr->next )
	curr = curr->next;
    curr->next = new;
},3,1,1

_parse_field_formatstr(const char *format, char ***tokens_dest, char ***fieldnames_dest) {
  unsigned int found = 0;
  unsigned int cur = 0;
  char **tokens = NULL;
  char **fieldnames = NULL;
  char *chunk;
  char *fieldtype;
  char *fieldname;
  char *temp1;
  char *temp2;
  char *line = strdup(format);

  temp1 = line;
  while (temp1 && (temp1 = strchr(temp1, '.')) != NULL) {
    temp1++;
    found++;
  }

  tokens = calloc(found, sizeof(char *));
  fieldnames = calloc(found, sizeof(char *));
  if (!tokens || !fieldnames) return DBI_FIELD_ERROR;

  chunk = strtok_r(line, " ", &temp1);
  do {
    temp2 = strchr(chunk, '.');
    if (!temp2) continue;
    fieldname = chunk;
    *temp2 = '\0';
    fieldtype = (temp2+2); /* ignore the % */
    tokens[cur] = strdup(fieldtype);
    fieldnames[cur] = strdup(fieldname);
    cur++;
  } while ((chunk = strtok_r(NULL, " ", &temp1)));

  *tokens_dest = tokens;
  *fieldnames_dest = fieldnames;

// TODO: optimize this loop
  free(line);
  return found;
},3,1,1

