main (int argc, char **argv)
{
  const char *query_string;
  const char *begin, *end, *c;
  size_t i = 0, script_argc = 0;
  char **script_argv;

  if (-1 == vink_init ("/etc/vink.d/vink.conf", VINK_CLIENT, VINK_API_VERSION))
    error (500, "Internal server error");

  backend_init (&callbacks);

  query_string = getenv ("QUERY_STRING");

  if (0 == (query_string = getenv ("QUERY_STRING")))
    error (500, "No QUERY_STRING environment variable");

  begin = query_string;

  for (c = begin; *c; )
    {
      ++script_argc;

      while (*c && *c != '&')
        ++c;

      if (!*c++)
        break;
    }

  if (script_argc < 2)
    error (400, "Not enough parameters");

  script_argv = malloc (sizeof (*script_argv) * script_argc);

  while (*begin)
    {
      size_t arglen;

      end = begin;

      while (*end && *end != '&')
        ++end;

      arglen = end - begin;

      script_argv[i] = malloc (arglen + 1);
      strncpy (script_argv[i], begin, arglen);
      script_argv[i][arglen] = 0;
      ++i;

      if (!*end)
        break;

      begin = end + 1;
    }

  if (strncmp (script_argv[script_argc - 1], "r=", 2))
    error (400, "Last parameter must start with r=");

  callback = script_argv[--script_argc] + 2;

  for (i = 0; i < ARRAY_SIZE (functions); ++i)
    {
      if (strcmp (functions[i].name, script_argv[0]))
        continue;

      if (strlen (functions[i].args) != script_argc - 1)
        continue;

      if (!functions[i].args[0])
        ((fun_v) (functions[i].function)) ();
      else if (!strcmp (functions[i].args, "s"))
        ((fun_s) (functions[i].function)) (script_argv[1]);
      else if (!strcmp (functions[i].args, "ss"))
        ((fun_ss) (functions[i].function)) (script_argv[1],
                                            script_argv[2]);

      break;
    }

  if (i == ARRAY_SIZE (functions))
    error (404, "Function not found");

  printf ("HTTP/1.1 200 OK\r\nContent-Type: text/javascript\r\n\r\n");

  return EXIT_SUCCESS;
},3,1,1

ielr_compute_always_follows (goto_number ***edgesp,
                             int const edge_counts[],
                             bitsetv *always_followsp)
{
  *always_followsp = bitsetv_create (ngotos, ntokens, BITSET_FIXED);
  {
    goto_number *edge_array = xnmalloc (ngotos, sizeof *edge_array);
    goto_number i;
    for (i = 0; i < ngotos; ++i)
      {
        goto_number nedges = edge_counts[i];
        {
          int j;
          transitions *trans = states[to_state[i]]->transitions;
          FOR_EACH_SHIFT (trans, j)
            bitset_set ((*always_followsp)[i], TRANSITION_SYMBOL (trans, j));
          for (; j < trans->num; ++j)
            {
              symbol_number sym = TRANSITION_SYMBOL (trans, j);
              if (nullable[sym - ntokens])
                edge_array[nedges++] = map_goto (to_state[i], sym);
            }
        }
        if (nedges - edge_counts[i])
          {
            (*edgesp)[i] =
              xnrealloc ((*edgesp)[i], nedges + 1, sizeof *(*edgesp)[i]);
            memcpy ((*edgesp)[i] + edge_counts[i], edge_array + edge_counts[i],
                    (nedges - edge_counts[i]) * sizeof *(*edgesp)[i]);
            (*edgesp)[i][nedges] = END_NODE;
          }
      }
    free (edge_array);
  }
  relation_digraph (*edgesp, ngotos, always_followsp);

  if (trace_flag & trace_ielr)
    {
      fprintf (stderr, "always follow edges:\n");
      relation_print (*edgesp, ngotos, stderr);
      fprintf (stderr, "always_follows:\n");
      debug_bitsetv (*always_followsp);
    }
},3,1,1

main(int argc, char** argv)
{
    int i;
    int64_t bufsize = DEFAULT_MEMORY, bufcount;
    FILE *index = NULL;
    struct IndexEntry *sortBuffer;

    if(argc < 2)
    {
        printUsage();
        return 1;
    }

    for(i = 1; i < argc; i++)
    {
        if(strcmp("-r", argv[i]) == 0 && i + 1 < argc)
            bufsize = (int64_t)atoi(argv[++i]) * 1024 * 1024;
        else
            index = fopen(argv[i], "r+b");
    }

    if(bufsize <= 0)
    {
        printf("Invalid buffer size (%lld).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(index == NULL)
    {
        printf("Couldn't open index file for reading/writing.\n");
        printUsage();
        return 1;
    }

// This function needs unit tests
    bufcount = bufsize / sizeof(struct IndexEntry);
    bufsize = bufcount * sizeof(struct IndexEntry);
    sortBuffer = malloc(bufsize); 

    if(sortBuffer == NULL)
    {
        printf("Cannot allocate buffer (%lld bytes).\n", (long long)bufsize);
        printUsage();
        return 1;
    }

    if(sortFile(index, sortBuffer, bufcount))
    {
        printf("Index sort complete.\n");
    }
    else
    {
        printf("There was a problem sorting the file.\n");
    }

    if(sortBuffer != NULL)
        free(sortBuffer);
    if(index != NULL)
        fclose(index);

    return 0;
},3,1,1

spawn_stuff( int argc, char *argv[] )
	{
	pid_t	kidpid;

	fflush(stdout);
	if( (kidpid = fork()) < 0 )
		{
		perror("fork");
		}
	else if( kidpid == 0 )
		{/* this is the kid */
			struct tms tms;
		ioctl(fkt,FKT_WAITREADY);	/* wait for sendfile to settle down */
		if (times(&tms)<0) {
			perror("times");
			exit(EXIT_FAILURE);
		}
		printf("executing %s\n",argv[optind]);
		execvp(argv[optind], &argv[optind]);
		perror(argv[optind]);
		exit(EXIT_FAILURE);
		}
	/*	this is the parent, just return the kid's pid */
	kpid = kidpid;
	return kidpid;
	},3,1,1

GRSTgaclCredTableAdd(GRSTgaclUser *user, GRSTgaclEntry *entry, GRSTgaclCred *cred, int cred_no, int entry_no, int admin, int timestamp, GRSThttpBody *bp, char *dn, GRSTgaclPerm perm, char *help_uri, char *dir_path, char *file, char *dir_uri, char *admin_file)
{
  // Adds the credential "cred" to a table started byGRSTgaclCredTableStart allowing the user to edit if appropriate
  char* cmd = GRSThttpGetCGI("cmd");
  int edit_values=0, new_cred=0, allow_new_person=1;
  int site_admin=GRSTgaclUserHasAURI(user, getenv("REDIRECT_GRST_ADMIN_LIST"));

  if (strcmp(cmd, "new_entry_form")==0 || strcmp(cmd, "add_cred_form")==0) new_cred=1;
  if (new_cred || (strcmp(cmd, "edit_entry_form") == 0)) edit_values=1;

  if (new_cred) 
    {
     //create dummy credential for the user to edit
     cred=GRSTgaclCredCreate("", "");
// Performance could be improved
     GRSThttpPrintf(bp,"<tr><td align=center >New</td>");
     cred_no = 1;
    }
  else 
    { //Print out type and descriptor for existing cred

     GRSThttpPrintf(bp,"<tr><td align=center >%d", cred_no);
     if (admin) GRSThttpPrintf (bp,"<a href=\"%s%s?diruri=%s&cmd=del_cred_sure&entry_no=%d&cred_no=%d&timestamp=%d\">(Delete)</a>", dir_uri,admin_file,dir_uri, entry_no, cred_no, timestamp);
     GRSThttpPrintf(bp, "</td>");
    }

  if (strcmp(cred->auri, "gacl:any-user")==0) GRSThttpPrintf (bp, "<td>%s", cred->auri); 
  else
   {
    if (edit_values)
      { // Place AURI in an editable box if appropriate
      GRSThttpPrintf (bp, "<td align=left><input type=\"text\" name=\"cred_auri_%d\"\n", cred_no);
      GRSThttpPrintf (bp, "size=\"50\" value=\"");
      StringHTMLEncode(cred->auri, bp);
      GRSThttpPrintf (bp, "\">");
      }
// Refactor this section for clarity
// Performance could be improved
      {
         GRSThttpPrintf(bp, "<td align=left ><a href=\"");
	 StringHTMLEncode(cred->auri, bp);
	 GRSThttpPrintf(bp, " \">");
	 StringHTMLEncode(cred->auri, bp);
	 GRSThttpPrintf(bp, "</a>");
      }
    else 
      {
        GRSThttpPrintf(bp, "<td align=left> "); 
        StringHTMLEncode(cred->auri, bp);
      }
   }
  //Print out warning symbol if cred being printed relates to current user - but NOT for users in site admin list
  if (GRSTgaclUserHasCred(user, cred) && !site_admin)  GRSThttpPrintf(bp, "<font color=red><b>&nbsp;&lt;--</b></font>");
  GRSThttpPrintf(bp, "</td></tr>");
