theme_add_entry(gchar *path)  {

	guint32 slot, area = 0;
	gchar *path2, *str, *ident;
	struct stat s;
	FILE *file;

	gchar *name = 0, *type = 0, *version = 0, *author = 0, *email = 0, *preview = 0;

	/* get properties of this theme, name, author, preview file, ... */
	path2 = g_strconcat(path, "theme.conf", NULL);

	/* detect invalid theme */
	if(stat(path2, &s) < 0)  {

		g_free(path2);
		return;
	}

	/* parse general group */
	file = fopen(path2, "r");
	if (!file) return;

	str = g_malloc0(512);

	for( fgets(str, 512, file) ; !feof(file) ; fgets(str, 512, file) )
	{

		if (str[0] == '[')  {

			if(! strncmp(str, "[general]", 9) )  area = THEME_FILE_SECTION_GENERAL;
			else area = 0;
		}

		else  if(area == THEME_FILE_SECTION_GENERAL)  {

			ident = parser_get_identifier(str);
			if(!ident)  continue;

			if(! strcmp(ident, "theme") )  {

				name = parser_get_data(str, "name");
				type = parser_get_data(str, "type");
				version = parser_get_data(str, "version");

			} else if(! strcmp(ident, "author") )  {

				author = parser_get_data(str, "name");
				email = parser_get_data(str, "email");

			} else if(! strcmp(ident, "misc") )  {

				preview = parser_get_data(str, "preview");
			}

			g_free(ident);
		}
	}
	fclose(file);

	g_free(str);


	/* giving up if theme provide no name or no type */
	if(!name  ||  !type)  return;


	/* fill the theme database */
	if(! theme_get_valid_slot(&slot) )  return;

	data->theme[slot].path = g_strdup(path);
	data->theme[slot].path_preview = g_strconcat(path, preview, NULL);
	g_free(preview);
	data->theme[slot].path_conf = g_strconcat(path, "theme.conf", NULL);

	data->theme[slot].open = TRUE;
	data->theme[slot].name = name;
	data->theme[slot].type = type;
	data->theme[slot].version = version;
	data->theme[slot].author = author;
	data->theme[slot].email = email;
},3,1,1

gf_font_manager_new(GF_User *user)
{
	char *def_font = "SERIF";
	u32 i, count;
	GF_FontManager *font_mgr;
	GF_FontReader *ifce;
	const char *opt;

	ifce = NULL;
	opt = gf_cfg_get_key(user->config, "FontEngine", "FontReader");
	if (opt) {
		ifce = (GF_FontReader *) gf_modules_load_interface_by_name(user->modules, opt, GF_FONT_READER_INTERFACE);
		if (ifce && ifce->init_font_engine(ifce) != GF_OK) {
			gf_modules_close_interface((GF_BaseInterface *)ifce);
			ifce = NULL;
		}
	}

	if (!ifce) {
		count = gf_modules_get_count(user->modules);
		for (i=0; i<count; i++) {
			ifce = (GF_FontReader *) gf_modules_load_interface(user->modules, i, GF_FONT_READER_INTERFACE);
			if (!ifce) continue;

			if (ifce->init_font_engine(ifce) != GF_OK) {
				gf_modules_close_interface((GF_BaseInterface *)ifce);
				ifce = NULL;
				continue;
			}

			gf_cfg_set_key(user->config, "FontEngine", "FontReader", ifce->module_name);
			break;
		}
	}
	GF_SAFEALLOC(font_mgr, GF_FontManager);
	font_mgr->reader = ifce;
	font_mgr->id_buffer_size = 20;
	font_mgr->id_buffer = gf_malloc(sizeof(u32)*font_mgr->id_buffer_size);
	gf_font_manager_set_font(font_mgr, &def_font, 1, 0);
	font_mgr->default_font = font_mgr->font;

	font_mgr->line_path= gf_path_new();
	gf_path_add_move_to(font_mgr->line_path, -FIX_ONE/2, FIX_ONE/2);
	gf_path_add_line_to(font_mgr->line_path, FIX_ONE/2, FIX_ONE/2);
	gf_path_add_line_to(font_mgr->line_path, FIX_ONE/2, -FIX_ONE/2);
	gf_path_add_line_to(font_mgr->line_path, -FIX_ONE/2, -FIX_ONE/2);
	gf_path_close(font_mgr->line_path);

	opt = gf_cfg_get_key(user->config, "FontEngine", "WaitForFontLoad");
	if (!opt) gf_cfg_set_key(user->config, "FontEngine", "WaitForFontLoad", "no");
	if (opt && !strcmp(opt, "yes")) font_mgr->wait_font_load = 1;

	return font_mgr;
},3,1,1

