get_physical_ram(void)
{
    char buf[100], units[5];
    FILE *f;
    int x;

    if ((f = fopen("/proc/meminfo", "r")) == NULL)
        return 0;

    while (fgets(buf, sizeof buf, f) != NULL) {
        if (sscanf(buf, "MemTotal: %d %4s", &x, units) == 2)
            break;
    }
    fclose(f);

    if (strcmp(units, "kB") != 0)
        return 0;

    return x / 1024;
},3,1,1

read_icon (gchar * icon_name, int force)
{
  gchar filename[1024];
  gchar icon_filename[1024];
  GdkPixbuf *icons_buffer = NULL;
  if (mydebug > 50)
    fprintf (stderr, "read_icon(%s,%d)\n", icon_name, force);

  typedef struct
  {
    gchar *path;
    gchar *option;
  } path_definition;
  path_definition available_path[] = {
    {"", NULL},
    {"./data/map-icons/", NULL},
    {"../data/map-icons/", NULL},
    {"./data/pixmaps/", NULL},
    {"../data/pixmaps/", NULL},
    {"%spixmaps/", (gchar *) local_config.dir_home},
    {"%smap-icons/", (gchar *) local_config.dir_home},
    {"%s/map-icons/", (gchar *) DATADIR},
    {"%s/gpsdrive/pixmaps/", (gchar *) DATADIR},
    {"%s/map-icons/", "/usr/share"},
    {"%s/gpsdrive/pixmaps/", "/usr/share"},
    {"/usr/share/icons/openstreetmap/"},
    {"END", NULL}
  };

  gint i;
  for (i = 0; strncmp (available_path[i].path, "END", sizeof (available_path[i].path)); i++)
    {
      g_snprintf (filename, sizeof (filename), available_path[i].path, available_path[i].option);
      g_snprintf (icon_filename, sizeof (icon_filename), "%s%s", filename, icon_name);
      if (mydebug > 75)
	fprintf (stderr, "read_icon(%s): Try\t%s\n", icon_name, icon_filename);
      icons_buffer = gdk_pixbuf_new_from_file (icon_filename, NULL);
      if (NULL != icons_buffer)
	{
	  if (mydebug > 20)
	    fprintf (stderr, "read_icon(%s): FOUND\t%s\n", icon_name, icon_filename);
	  return icons_buffer;
	}
    }

  if (NULL == icons_buffer && force)
    {
      fprintf (stderr, "read_icon: No Icon '%s' found\n", icon_name);
      if (strstr (icon_name, "Old") == NULL)
	{
	  fprintf (stderr, _("Please install the program as root with:\n" "make install\n\n"));

	  fprintf (stderr, "I searched in :\n");
	  for (i = 0; strncmp (available_path[i].path, "END", sizeof (available_path[i].path)); i++)
	    {
	      g_snprintf (filename, sizeof (filename), available_path[i].path, available_path[i].option);
	      g_snprintf (icon_filename, sizeof (icon_filename), "%s%s", filename, icon_name);
	      fprintf (stderr, "\t%s\n", icon_filename);
	    }

	  exit (-1);
	}
    }

  return icons_buffer;
},3,1,1

skip_tag_attribs(HSCPRC * hp, EXPSTR * content)
{
    /* TODO: on illegal attr name, abort wth message */
    /* TODO: on "\n" in value, display message */
    /* TODO: conditional assignments */
    UBYTE state = STATE_TAGATTR;
    INFILE *inpf = hp->inpf;    /* input file */
    STRPTR nw = NULL;
    BOOL quit = FALSE;          /* flag: exit from skipping */

    do
    {
        /* get next word  or attribute name */
        if (state == STATE_TAGATTR)
        {
            nw = infget_attrid(hp);
        }
        else
        {
            nw = infgetw(inpf);
        }

        if (nw)
        {
            app_estr(content, infgetcws(inpf));
            app_estr(content, infgetcw(inpf));

            switch (state)
            {
            case STATE_TAGATTR:
                {
                    if (!strcmp(nw, "="))
                    {
                        /* normal assignment */
                        state = STATE_TAGATTR_EQ;
                    }
                    else if (!strcmp(nw, "?"))
                    {
                        /* conditional assignment:
                         * just check for succeeding "=",
                         * and push it back into input stream */
                        parse_eq(hp);
                        inungetcw(inpf);
                    }
                    else if (!strcmp(nw, ">"))
                    {
                        DS(fprintf(stderr, DHLS "end-of-tag-call\n"));
                        quit = TRUE;
                    }
                    else
                    {
                        /* just skipped a boolean attribute;
                         * nufin to do about it */
                    }
                    break;
                }

            case STATE_TAGATTR_EQ:
                skip_expression(hp, content, nw[0]);
                DS(fprintf(stderr, DHLS "end-of-tag-expression\n"));
                state = STATE_TAGATTR;
                break;

                /* unhandled state */
            default:
                panic("unhandled state");
                break;
            }
        }
    }
    while (nw && !quit && !(hp->fatal));

    return ((BOOL) ! (hp->fatal));
},3,1,1

