              pre_text == NULL ? "" : pre_text,
              pre_text == NULL ? "" : ": ",
              node->details ==
              NULL ? "error " : node->details->online ? "" : "Unavailable/Unclean ",
              node->details->uname, node->weight, node->fixed ? "True" : "False");

    if (details && node != NULL && node->details != NULL) {
