splitPowerNet(apLoFig, asPower)
  lofig_list *apLoFig;
        char *asPower;
{
  ptype_list *pType;
  chain_list *pChain;
  locon_list *pLoCon;
  loins_list *pLoIns;
  losig_list *pSigPower, *pSig;
        char *tsSig[2], *sVDD, *sVSS, *sPOW;
        long  powerType;


  sVDD = namealloc("vdd");
  sVSS = namealloc("vss");

  tsSig[C_POWER_VDD] = namealloc("vddi");
  tsSig[C_POWER_VSS] = namealloc("vssi");

  powerType = C_POWER_UNKNOWN; sPOW = (char*)NULL;
  if (!strcmp(asPower, sVDD)) { powerType = C_POWER_VDD; sPOW = sVDD; }
  if (!strcmp(asPower, sVSS)) { powerType = C_POWER_VSS; sPOW = sVSS; }

  if (powerType == C_POWER_UNKNOWN) {
    eprinth((char*)NULL);
    eprintf("\n  Only \"vdd\" and \"vss\" can be splitted (%s).\n", asPower);
    EXIT (1);
  }


  pChain    = addchain((chain_list*)NULL, (void*)tsSig[powerType]);
  pSigPower = addlosig(apLoFig, NEWSIGINDEX, pChain, INTERNAL);


  /* Find the power net to be splitted. */
  for(pSig = apLoFig->LOSIG; pSig != (losig_list*)NULL; pSig = pSig->NEXT)
    if (cmpSigName(pSig, sPOW)) break;

  if (pSig == (losig_list*)NULL) {
    eprinth((char*)NULL);
    eprintf("\n  Signal \"%s\" not found for splitting.\n", sPOW);
    EXIT (1);
  }

  pType = getptype(pSig->USER, (long)LOFIGCHAIN);
  if (pType == (ptype_list*)NULL) {
    eprinth((char*)NULL);
    eprintf("\n  Signal \"%s\" have no LOFIGCHAIN.\n", sPOW);
    EXIT (1);
  }


  /* Split the power between core cells and pad cells. */
  pChain = (chain_list*)(pType->DATA);

  for(; pChain != (chain_list*)NULL;
        pChain  = pChain->NEXT) {
    pLoCon = (locon_list*)(pChain->DATA);

    if (pLoCon->TYPE == INTERNAL) {
      pLoIns = (loins_list*)(pLoCon->ROOT);

      if (isPad(pLoIns->FIGNAME)) pLoCon->SIG = pSigPower;

      if (    (powerType == C_POWER_VDD)
          && !strcmp(pLoIns->FIGNAME, "pvddi_sp")) {
        addInsLoCon(pLoIns, sPOW, pSig, pLoCon->DIRECTION);
      }

      if (    (powerType == C_POWER_VSS)
          && !strcmp(pLoIns->FIGNAME, "pvssi_sp")) {
        addInsLoCon(pLoIns, sPOW, pSig, pLoCon->DIRECTION);
      }
    }
  } /* End of "pChain" loop. */
},3,1,1

wipefile (char *name, char const *qname,
          struct randint_source *s, struct Options const *flags)
{
  bool ok;
  int fd;

  fd = open (name, O_WRONLY | O_NOCTTY | O_BINARY);
  if (fd < 0
      && (errno == EACCES && flags->force)
      && chmod (name, S_IWUSR) == 0)
    fd = open (name, O_WRONLY | O_NOCTTY | O_BINARY);
  if (fd < 0)
    {
      error (0, errno, _("%s: failed to open for writing"), qname);
      return false;
    }

  ok = do_wipefd (fd, qname, s, flags);
  if (close (fd) != 0)
    {
      error (0, errno, _("%s: failed to close"), qname);
      ok = false;
    }
  if (ok && flags->remove_file)
    ok = wipename (name, qname, flags);
  return ok;
},3,1,1

handle_options_work(lms_t *lms, int argc, char **argv)
{
    int opt_index, method, verbose;

    verbose = 0;
    method = 2;
    optind = 0;
    opterr = 0;
    opt_index = 0;
    while (1) {
        int c;

        c = getopt_long(argc, argv, short_options, long_options, &opt_index);
        if (c == -1)
            break;

        switch (c) {
        case 'm':
            if (strcmp(optarg, "1") == 0 ||
                strcmp(optarg, "mono") == 0)
                method = 1;
            else if (strcmp(optarg, "2") == 0 ||
                     strcmp(optarg, "dual") == 0)
                method = 2;
            else
                fprintf(stderr,
                        "ERROR: invalid method=%s, should be 'mono' (1) or "
                        "'dual' (2). Default is dual.\n",
                        optarg);
        case 'v':
            if (optarg)
                verbose = !!atoi(optarg);
            else
                verbose = 1;
            break;
        case 's':
            if (work(lms, method, verbose, optarg) != 0)
                return -1;
            break;
        case 'S':
            show(lms, optarg);
            break;
        default:
            break;
        }
    }

    return 0;
},3,1,1

tm_tag_name_type(const char* tag_name)
{
	g_return_val_if_fail(tag_name, tm_tag_undef_t);

	if (strcmp(tag_name, "class") == 0) return tm_tag_class_t;
	else if (strcmp(tag_name, "enum") == 0) return tm_tag_enum_t;
	else if (strcmp(tag_name, "enumval") == 0) return tm_tag_enumerator_t;
	else if (strcmp(tag_name, "field") == 0) return tm_tag_field_t;
	else if (strcmp(tag_name, "function") == 0) return tm_tag_function_t;
	else if (strcmp(tag_name, "interface") == 0) return tm_tag_interface_t;
	else if (strcmp(tag_name, "member") == 0) return tm_tag_member_t;
	else if (strcmp(tag_name, "method") == 0) return tm_tag_method_t;
	else if (strcmp(tag_name, "namespace") == 0) return tm_tag_namespace_t;
	else if (strcmp(tag_name, "package") == 0) return tm_tag_package_t;
	else if (strcmp(tag_name, "prototype") == 0) return tm_tag_prototype_t;
	else if (strcmp(tag_name, "struct") == 0) return tm_tag_struct_t;
	else if (strcmp(tag_name, "typedef") == 0) return tm_tag_typedef_t;
	else if (strcmp(tag_name, "union") == 0) return tm_tag_union_t;
	else if (strcmp(tag_name, "variable") == 0) return tm_tag_variable_t;
	else if (strcmp(tag_name, "extern") == 0) return tm_tag_externvar_t;
	else if (strcmp(tag_name, "define") == 0) return tm_tag_macro_t;
	else if (strcmp(tag_name, "macro") == 0) return tm_tag_macro_with_arg_t;
	else if (strcmp(tag_name, "file") == 0) return tm_tag_file_t;
	else return tm_tag_undef_t;
},3,0,0

rld_restore_header(const char *fn, FILE **_fp)
{
	FILE *fp;
	rld_t *e;
	char magic[4];
	uint64_t a[3];
	int32_t i, x;

	if (strcmp(fn, "-") == 0) *_fp = fp = stdin;
	else if ((*_fp = fp = fopen(fn, "rb")) == 0) return 0;
	fread(magic, 1, 4, fp);
	if (strncmp(magic, "RLD\2", 4)) return 0;
	fread(&x, 4, 1, fp);
	e = rld_init(x>>16, x&0xffff);
	fread(a, 8, 3, fp);
	e->n_bytes = a[1]; e->n_frames = a[2];
	fread(e->mcnt + 1, 8, e->asize, fp);
	for (i = 0; i <= e->asize; ++i) e->cnt[i] = e->mcnt[i];
	for (i = 1; i <= e->asize; ++i) e->cnt[i] += e->cnt[i - 1];
	e->mcnt[0] = e->cnt[e->asize];
	return e;
},3,1,1

