set_kbd(int fd, unsigned int protocol_version, char *mapfile)
{
	struct kbd_map *map;
	FILE *fp;

	map = kbd_map_read(fd, protocol_version);
	if (NULL == map) {
		printf("device has no map\n");
		close(fd);
		return -1;
	}

	if (0 == strcmp(mapfile,"-"))
		fp = stdin;
	else {
		fp = fopen(mapfile,"r");
		if (NULL == fp) {
			printf("open %s: %s\n",mapfile,strerror(errno));
			close(fd);
			return -1;
		}
	}

	if (0 != kbd_map_parse(fp,map) ||
	    0 != kbd_map_write(fd,map)) {
		return -1;
	}

	return 0;
},3,1,1

ReleaseSavepoint(List *options)
{
	TransactionState s = CurrentTransactionState;
	TransactionState target,
				xact;
	ListCell   *cell;
	char	   *name = NULL;

	switch (s->blockState)
	{
			/*
			 * We can't rollback to a savepoint if there is no savepoint
			 * defined.
			 */
		case TBLOCK_INPROGRESS:
			ereport(ERROR,
					(errcode(ERRCODE_S_E_INVALID_SPECIFICATION),
					 errmsg("no such savepoint")));
			break;

			/*
			 * We are in a non-aborted subtransaction.	This is the only valid
			 * case.
			 */
		case TBLOCK_SUBINPROGRESS:
			break;

			/* These cases are invalid. */
		case TBLOCK_DEFAULT:
		case TBLOCK_STARTED:
		case TBLOCK_BEGIN:
		case TBLOCK_SUBBEGIN:
		case TBLOCK_END:
		case TBLOCK_SUBEND:
		case TBLOCK_ABORT:
		case TBLOCK_SUBABORT:
		case TBLOCK_ABORT_END:
		case TBLOCK_SUBABORT_END:
		case TBLOCK_ABORT_PENDING:
		case TBLOCK_SUBABORT_PENDING:
		case TBLOCK_SUBRESTART:
		case TBLOCK_SUBABORT_RESTART:
		case TBLOCK_PREPARE:
			elog(FATAL, "ReleaseSavepoint: unexpected state %s",
				 BlockStateAsString(s->blockState));
			break;
	}

	foreach(cell, options)
	{
		DefElem    *elem = lfirst(cell);

		if (strcmp(elem->defname, "savepoint_name") == 0)
			name = strVal(elem->arg);
	}

	Assert(PointerIsValid(name));

	for (target = s; PointerIsValid(target); target = target->parent)
	{
		if (PointerIsValid(target->name) && strcmp(target->name, name) == 0)
			break;
	}

	if (!PointerIsValid(target))
		ereport(ERROR,
				(errcode(ERRCODE_S_E_INVALID_SPECIFICATION),
				 errmsg("no such savepoint")));

	/* disallow crossing savepoint level boundaries */
	if (target->savepointLevel != s->savepointLevel)
		ereport(ERROR,
				(errcode(ERRCODE_S_E_INVALID_SPECIFICATION),
				 errmsg("no such savepoint")));

	/*
	 * Mark "commit pending" all subtransactions up to the target
	 * subtransaction.	The actual commits will happen when control gets to
	 * CommitTransactionCommand.
	 */
	xact = CurrentTransactionState;
	for (;;)
	{
		Assert(xact->blockState == TBLOCK_SUBINPROGRESS);
		xact->blockState = TBLOCK_SUBEND;
		if (xact == target)
			break;
		xact = xact->parent;
		Assert(PointerIsValid(xact));
	}
},3,1,1

test_init_macro(const char *file)
{
    /* Build message domain + log filename
       from source file name */

    unsigned len = strlen(file);
    int able_to_parse_filename;

    cpl_init(CPL_INIT_DEFAULT);
    error_init = cpl_errorstate_get();
    srand(0);

    if (len < strlen("s.c") || strcmp(file + len - strlen(".c"), ".c") != 0)
        {
            able_to_parse_filename = 0;
            /* Here, we should issue a warning but we need to
               initialize the CPL message system first */
        }
    else
        {
            /* Form domain from filename by removing ".c" suffix
               and stripping any path prefix */

            const char dir_delimiter = '/'; /* UNIX only! */
            unsigned path_length = 0;       /* Length of path prefix 
                                               including final '/' */
            int i;

            for (i = len - strlen(".c") - 1; i >= 0; i--)
                {
                    if (file[i] == dir_delimiter && path_length == 0)
                        {
                            path_length = i + 1;
                        }
                }

            able_to_parse_filename = (len - path_length - strlen(".c") >= 1);
            if (able_to_parse_filename)
                {
                    const char *logfile;
                    char *domain;

                    domain = cpl_strdup(file + path_length);
                    domain[len - path_length - strlen(".c")] = '\0';

                    cpl_msg_set_domain(domain);

                    logfile = cpl_sprintf("%s.log", domain);
                    cpl_msg_set_log_name(logfile);

                    cpl_free((char *)logfile);
                    cpl_free(domain);
                }
            /* else: Use default domain + logfilename */
        }

    /* Adopt the policy that the unit test is quiet
       unless something is wrong.
       Dump debugging info to the log file */
    cpl_msg_set_level(CPL_MSG_WARNING); 
    cpl_msg_set_log_level(CPL_MSG_DEBUG);

    if (!able_to_parse_filename)
        {
            cpl_msg_warning(cpl_func,
                            "Source file name '%s' does not match [base].c. ",
                            file);
        }

    if (cpl_error_get_code() != CPL_ERROR_NONE)
        {
            cpl_msg_error(cpl_func,
                          "Failure during initialization: %s at %s",
                          cpl_error_get_message(), cpl_error_get_where());
        }

    return;
},3,1,1

ParseFile(const char * name, BOOL isOptional)
{
	FILE *		fp;
	char *		cp;
	char *		cmd;
	BOOL		status;
	MACRO_TYPE	macroType;

	status = TRUE;

	/*
	 * If the file is optional then check whether it exists.
	 * In not, then return success without doing anything.
	 */
	if (isOptional && (access(name, F_OK) != 0) && (errno == ENOENT))
		return TRUE;

	/*
	 * Check our permissions for reading the file before using it,
	 * in case we are running suid as root.
	 */
	if (access(name, R_OK) != 0)
	{
		fprintf(stderr, "Cannot access \"%s\" for reading: %s\n",
			name, strerror(errno));

		return FALSE;
	}

	fp = fopen(name, "r");

	if (fp == NULL)
	{
		fprintf(stderr, "Cannot open \"%s\" for reading: %s\n",
			name, strerror(errno));

		return FALSE;
	}

	/*
	 * For further security, make sure that the first line contains
	 * the magic string identifying an ips configuration file.
	 */
	cmd = ReadLine(fp);

	if ((cmd == NULL) || (strcmp(cmd, FIRST_LINE) != 0))
	{
		fclose(fp);

		fprintf(stderr,
			"The file \"%s\" does not begin with \"%s\".\n",
			name, FIRST_LINE);

		return FALSE;
	}

	/*
	 * OK, read each line of the file and handle it.
	 */
	while (TRUE)
	{
		cmd = ReadLine(fp);

		if (cmd == NULL)
			break;

		while (isBlank(*cmd))
			cmd++;

		/*
		 * Skip blank lines or lines starting with hash marks.
		 */
		if ((*cmd == '#') || (*cmd == '\0'))
			continue;

		cp = cmd;

		while ((*cp != '\0') && !isBlank(*cp))
			cp++;

		if (*cp)
			*cp++ = '\0';

		while (isBlank(*cp))
			cp++;

		/*
		 * If a macro is being defined, then do that.
		 */
		macroType = MACRO_TYPE_NONE;

		if (strcmp(cmd, "option") == 0)
			macroType = MACRO_TYPE_OPTION;
		else if (strcmp(cmd, "column") == 0)
			macroType = MACRO_TYPE_COLUMN;
		else if (strcmp(cmd, "expr") == 0)
			macroType = MACRO_TYPE_EXPRESSION;

		if (macroType != MACRO_TYPE_NONE)
		{
			cmd = cp;

			while ((*cp != '\0') && !isBlank(*cp))
				cp++;

			if (*cp)
				*cp++ = '\0';

			while (isBlank(*cp))
				cp++;

			if (!DefineMacro(macroType, cmd, cp))
				status = FALSE;

			continue;
		}

		/*
		 * The command is unknown.
		 */
		fprintf(stderr, "%s: Unknown command \"%s\"\n", name, cmd);

		status = FALSE;

		break;
	}

	if (ferror(fp))
	{
		fprintf(stderr, "Error reading \"%s\": %s\n", name,
			strerror(errno));

		fclose(fp);

		return FALSE;
	}

	(void) fclose(fp);

	return status;
},3,1,1

