		if (!new->range)
			list_add(vsg->addr_ip, new);
		else
			list_add(vsg->range, new);
	}
},3,1,1

nef_parse_makernote (base)
{
  int offset=0, entries, tag, type, count, val, save;
  short sorder;
  char buf[10];

  puts("  Nikon MakerNote:");
/*
   The MakerNote might have its own TIFF header (possibly with
   its own byte-order!), or it might just be a table.
 */
  sorder = order;
  fread (buf, 1, 10, ifp);
  if (!strcmp (buf,"Nikon")) {	/* starts with "Nikon\0\2\0\0\0" ? */
    base = ftell(ifp);
    order = fget2(ifp);		/* might differ from file-wide byteorder */
    val = fget2(ifp);		/* should be 42 decimal */
    offset = fget4(ifp);
    fseek (ifp, offset-8, SEEK_CUR);
  } else if (!strncmp (buf,"FUJIFILM",8)) {
    order = 0x4949;
    fseek (ifp,  2, SEEK_CUR);
  } else if (!strcmp (buf,"OLYMP") ||
	     !strcmp (buf,"LEICA") ||
	     !strcmp (buf,"EPSON"))
    fseek (ifp, -2, SEEK_CUR);
  else if (!strcmp (buf,"AOC"))
    fseek (ifp, -4, SEEK_CUR);
  else
    fseek (ifp, -10, SEEK_CUR);

  entries = fget2(ifp);
  if (entries > 100) return;
  while (entries--) {
    save = ftell(ifp);
    tag  = fget2(ifp);
    type = fget2(ifp);
    count= fget4(ifp);
    val  = fget4(ifp);
    fseek (ifp, -4, SEEK_CUR);
    if (tag == 0x100 && type == 7 && !strncmp(make,"OLYMPUS",7)) {
      thumb_offset = base+val;
      thumb_length = count;
    }
    if (tag == 0x280 && type == 1) {	/* EPSON */
      strcpy (thumb_head, "\xff");
      thumb_offset = base+val+1;
      thumb_length = count-1;
    }
    if (strstr(make,"Minolta") || strstr(make,"MINOLTA")) {
      switch (tag) {
	case 0x81:
	  thumb_length = count;
	case 0x88:
	  thumb_offset = base+val;
	  break;
	case 0x89:
	  thumb_length = val;
      }
    }
    tiff_dump (base, tag, type, count, 2);
    fseek (ifp, save+12, SEEK_SET);
  }
  order = sorder;
},3,0,0

test_read_ip6_wired_connection (void)
{
	NMConnection *connection;
	NMSettingConnection *s_con;
	NMSettingWired *s_wired;
	NMSettingIP4Config *s_ip4;
	NMSettingIP6Config *s_ip6;
	GError *error = NULL;
	const char *tmp;
	const char *expected_id = "Test Wired Connection IP6";
	const char *expected_uuid = "4e80a56d-c99f-4aad-a6dd-b449bc398c57";

	connection = nm_keyfile_plugin_connection_from_file (TEST_WIRED_IP6_FILE, NULL);
	ASSERT (connection != NULL,
			"connection-read", "failed to read %s", TEST_WIRED_IP6_FILE);

	ASSERT (nm_connection_verify (connection, &error),
	        "connection-verify", "failed to verify %s: %s", TEST_WIRED_IP6_FILE, error->message);

	/* ===== CONNECTION SETTING ===== */

	s_con = nm_connection_get_setting_connection (connection);
	ASSERT (s_con != NULL,
	        "connection-verify-connection", "failed to verify %s: missing %s setting",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_CONNECTION_SETTING_NAME);

	/* ID */
	tmp = nm_setting_connection_get_id (s_con);
	ASSERT (tmp != NULL,
	        "connection-verify-connection", "failed to verify %s: missing %s / %s key",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_CONNECTION_SETTING_NAME,
	        NM_SETTING_CONNECTION_ID);
	ASSERT (strcmp (tmp, expected_id) == 0,
	        "connection-verify-connection", "failed to verify %s: unexpected %s / %s key value",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_CONNECTION_SETTING_NAME,
	        NM_SETTING_CONNECTION_ID);

	/* UUID */
	tmp = nm_setting_connection_get_uuid (s_con);
	ASSERT (tmp != NULL,
	        "connection-verify-connection", "failed to verify %s: missing %s / %s key",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_CONNECTION_SETTING_NAME,
	        NM_SETTING_CONNECTION_UUID);
	ASSERT (strcmp (tmp, expected_uuid) == 0,
	        "connection-verify-connection", "failed to verify %s: unexpected %s / %s key value",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_CONNECTION_SETTING_NAME,
	        NM_SETTING_CONNECTION_UUID);

	/* ===== WIRED SETTING ===== */

	s_wired = nm_connection_get_setting_wired (connection);
	ASSERT (s_wired != NULL,
	        "connection-verify-wired", "failed to verify %s: missing %s setting",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_WIRED_SETTING_NAME);

	/* ===== IPv4 SETTING ===== */

	s_ip4 = nm_connection_get_setting_ip4_config (connection);
	ASSERT (s_ip4 != NULL,
	        "connection-verify-ip4", "failed to verify %s: missing %s setting",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_IP4_CONFIG_SETTING_NAME);

	/* Method */
	tmp = nm_setting_ip4_config_get_method (s_ip4);
	ASSERT (strcmp (tmp, NM_SETTING_IP4_CONFIG_METHOD_DISABLED) == 0,
	        "connection-verify-wired", "failed to verify %s: unexpected %s / %s key value",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_IP4_CONFIG_SETTING_NAME,
	        NM_SETTING_IP4_CONFIG_METHOD);

	ASSERT (nm_setting_ip4_config_get_num_addresses (s_ip4) == 0,
	        "connection-verify-wired", "failed to verify %s: unexpected %s / %s key value",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_IP4_CONFIG_SETTING_NAME,
	        NM_SETTING_IP4_CONFIG_DNS);

	/* ===== IPv6 SETTING ===== */

	s_ip6 = nm_connection_get_setting_ip6_config (connection);
	ASSERT (s_ip6 != NULL,
	        "connection-verify-ip6", "failed to verify %s: missing %s setting",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_IP6_CONFIG_SETTING_NAME);

	/* Method */
	tmp = nm_setting_ip6_config_get_method (s_ip6);
	ASSERT (strcmp (tmp, NM_SETTING_IP6_CONFIG_METHOD_MANUAL) == 0,
	        "connection-verify-wired", "failed to verify %s: unexpected %s / %s key value",
	        TEST_WIRED_IP6_FILE,
	        NM_SETTING_IP6_CONFIG_SETTING_NAME,
	        NM_SETTING_IP6_CONFIG_METHOD);

	/* IPv6 address */
	g_assert (nm_setting_ip6_config_get_num_addresses (s_ip6) == 1);
	check_ip6_address (s_ip6, 0, "abcd:1234:ffff::cdde", 64, "abcd:1234:ffff::cdd1");

	g_object_unref (connection);
},3,1,1

setup_pager(void)
{
	const char *pager = getenv("GIT_PAGER");

	if (!isatty(1))
		return;
	if (!pager) {
		if (!pager_program)
			git_config(git_default_config, NULL);
		pager = pager_program;
	}
	if (!pager)
		pager = getenv("PAGER");
	if (!pager)
		pager = "less";
	else if (!*pager || !strcmp(pager, "cat"))
		return;

	spawned_pager = 1; /* means we are emitting to terminal */

	/* spawn the pager */
	pager_argv[2] = pager;
	pager_process.argv = pager_argv;
	pager_process.in = -1;
#ifndef __MINGW32__
	pager_process.preexec_cb = pager_preexec;
#endif
	if (start_command(&pager_process))
		return;

	/* original process continues, but writes to the pipe */
	dup2(pager_process.in, 1);
	dup2(pager_process.in, 2);
	close(pager_process.in);

	/* this makes sure that the parent terminates after the pager */
	atexit(wait_for_pager);
},3,1,1

write_strings(item *p)
{
unit x, y;
stringchain *s = p->strings;

if (s == NULL) return;  /* There are no strings */

stringpos(p, &x, &y);      /* Find the right position for the strings */

for (;;)
  {
  uschar fambuff[64];

  if (s->text[0] != 0)
    {
    uschar *ss = s->text;

    fprintf(out_file, "<text x=\"%s\" y=\"%s\" text-anchor=\"%s\"",
      fixed(rnd(x - bbox[0] + s->xadjust)), 
      fixed(rnd(-y + bbox[1] - s->yadjust)),
      (s->justify == just_left)? US"start" :
      (s->justify == just_right)? US"end" : US"middle");

    if (s->font != 0)
      {
      bindfont *b;

      for (b = font_base; b != NULL; b = b->next)
        {
        if (b->number == s->font)
          {
          uschar *hyphen = Ustrchr(b->name, '-');
          uschar *family;
          uschar *weight = NULL; 
          uschar *style = NULL; 
          uschar fambuff[64];

          if (hyphen == NULL)
            {
            family = b->name;
            }
          else
            {
            Ustrncpy(fambuff, b->name, hyphen - b->name);
            fambuff[hyphen - b->name] = 0;
            family = fambuff;

            if (Ustrcmp(hyphen+1, "Italic") == 0 ||
                Ustrcmp(hyphen+1, "BoldItalic") == 0)
              style = US"italic";

            if (Ustrcmp(hyphen+1, "Bold") == 0 ||
                Ustrcmp(hyphen+1, "BoldItalic") == 0)
              weight = US"bold";
            }

          fprintf(out_file, " font-family=\"%s\" font-size=\"%s\"",
            family, fixed(b->size));
          if (weight != NULL)
            fprintf(out_file, " font-weight=\"%s\"", weight); 
          if (style != NULL)
            fprintf(out_file, " font-style=\"%s\"", style); 
          break;
          }
        }
      }

    fprintf(out_file, ">");
    while (*ss != 0) 
      {
      int c;
      GETCHARINC(c, ss); 
      if (c == '<') fprintf(out_file, "&lt;");
      else if (c == '>') fprintf(out_file, "&gt;");
      else if (c == '&') fprintf(out_file, "&amp;");
      else if (c < 127) fputc(c, out_file);
      else fprintf(out_file, "&#x%x;", c);
      }
    fprintf(out_file, "</text>\n");
    }

  s = s->next;
  if (s == NULL) break; 
  y -= find_linedepth(p, s);
  }
},3,1,1

define_macro (name, value, mtype)
     char *name, *value;
     int mtype;
{
  char *mt_val = "";
  register char *lptr;

  if (!(name && *name))
    return;

  if (!value) value = mt_val;

  while (*value && isspace (*value)) value++;
  lptr = value;
  while (*lptr) lptr++;
  if (lptr > value) lptr--;
  while (*lptr && isspace (*lptr)) lptr--;
  if (*lptr)
    *(lptr+1) = '\0';

  if (!strcmp(name,"RECDEPTH")) {
    rec_do_depth = atoi(value);
  }
  addHash (name, value, mtype);
  if (!strcmp(name,"VPATH"))
    insertvpath(value);
  if (!strcmp(name,"IMPORT"))
    get_macrodefs_from_env();   /* macros are immediately defined */
},3,1,1

do_tar_in (const char *dir, const char *compress)
{
  const char *filter;
  int err, r;
  FILE *fp;
  CLEANUP_FREE char *cmd = NULL;
  char error_file[] = "/tmp/tarXXXXXX";
  int fd, chown_supported;

  chown_supported = is_chown_supported (dir);
  if (chown_supported == -1)
    return -1;

  if ((optargs_bitmask & GUESTFS_TAR_IN_COMPRESS_BITMASK)) {
    if (STREQ (compress, "compress"))
      filter = " --compress";
    else if (STREQ (compress, "gzip"))
      filter = " --gzip";
    else if (STREQ (compress, "bzip2"))
      filter = " --bzip2";
    else if (STREQ (compress, "xz"))
      filter = " --xz";
    else if (STREQ (compress, "lzop"))
      filter = " --lzop";
    else {
      reply_with_error ("unknown compression type: %s", compress);
      return -1;
    }
  } else
    filter = "";

  fd = mkstemp (error_file);
  if (fd == -1) {
    reply_with_perror ("mkstemp");
    return -1;
  }

  close (fd);

  /* "tar -C /sysroot%s -xf -" but we have to quote the dir. */
  if (asprintf_nowarn (&cmd, "%s -C %R%s -xf - %s2> %s",
                       str_tar,
                       dir, filter,
                       chown_supported ? "" : "--no-same-owner ",
                       error_file) == -1) {
    err = errno;
    r = cancel_receive ();
    errno = err;
    reply_with_perror ("asprintf");
    unlink (error_file);
    return -1;
  }

  if (verbose)
    fprintf (stderr, "%s\n", cmd);

  fp = popen (cmd, "w");
  if (fp == NULL) {
    err = errno;
    r = cancel_receive ();
    errno = err;
    reply_with_perror ("%s", cmd);
    unlink (error_file);
    return -1;
  }

  /* The semantics of fwrite are too undefined, so write to the
   * file descriptor directly instead.
   */
  fd = fileno (fp);

  r = receive_file (write_cb, &fd);
  if (r == -1) {		/* write error */
    cancel_receive ();
    CLEANUP_FREE char *errstr = read_error_file (error_file);
    reply_with_error ("write error on directory: %s: %s", dir, errstr);
    unlink (error_file);
    pclose (fp);
    return -1;
  }
  if (r == -2) {		/* cancellation from library */
    /* This error is ignored by the library since it initiated the
     * cancel.  Nevertheless we must send an error reply here.
     */
    reply_with_error ("file upload cancelled");
    pclose (fp);
    unlink (error_file);
    return -1;
  }

  if (pclose (fp) != 0) {
    CLEANUP_FREE char *errstr = read_error_file (error_file);
    reply_with_error ("tar subcommand failed on directory: %s: %s",
                      dir, errstr);
    unlink (error_file);
    return -1;
  }

  unlink (error_file);

  return 0;
},3,1,1

open_file(char *filename,char *rights) {

	FILE *stream;
	int error_code;

	/* Check if the current file is a valid filename */
	/* and return the appropriate value				 */

	if ((stream = fopen(filename,rights)) == NULL) {
		print_error(OPEN_ERROR,filename);
		error_code = ERROR;
	} else {
		fclose(stream);
		add_file(filename);
		error_code = NO_ERROR;
	}
	return error_code;
},3,1,1

xalloc(u_int i, char **arr)
{
	char **xrr;
	u_int ac = i / DEFAULT_ALLOC;

	if (i % DEFAULT_ALLOC == 0) {
		xrr = realloc(arr, sizeof(char *) * DEFAULT_ALLOC * ++ac);
		if (xrr == NULL) {
			arr[i - 1] = NULL;
			freea(arr);
			return (NULL);
		}
		arr = xrr;
	}

	return (arr);
},3,1,1

