mq_set_inode_xattr (xlator_t *this, loc_t *loc)
{
        struct gf_flock  lock  = {0, };
        quota_local_t   *local = NULL;
        int32_t          ret   = 0;
        call_frame_t    *frame = NULL;

        frame = create_frame (this, this->ctx->pool);
        if (!frame) {
                ret = -1;
                goto err;
        }

        local = mq_local_new ();
        if (local == NULL) {
                goto err;
        }

        frame->local = local;

        ret = loc_copy (&local->loc, loc);
        if (ret < 0) {
                goto err;
        }

        frame->local = local;

        lock.l_len    = 0;
        lock.l_start  = 0;
        lock.l_type   = F_WRLCK;
        lock.l_whence = SEEK_SET;

        STACK_WIND (frame,
                    mq_get_xattr,
                    FIRST_CHILD(this),
                    FIRST_CHILD(this)->fops->inodelk,
                    this->name, &local->loc, F_SETLKW, &lock, NULL);

        return 0;

err:
        QUOTA_STACK_DESTROY (frame, this);

        return 0;
},3,1,1

mm_typecode_to_str(MM_typecode matcode)
{
    char buffer[MM_MAX_LINE_LENGTH];
    char *types[4];
    /*  char *strdup(const char *); */
    int error = 0;

    /* check for MTX type */
    if (mm_is_matrix(matcode))
	types[0] = MM_MTX_STR;
    else
	error = 1;

    /* check for CRD or ARR matrix */
    if (mm_is_sparse(matcode))
	types[1] = MM_SPARSE_STR;
    else if (mm_is_dense(matcode))
	types[1] = MM_DENSE_STR;
    else
	return NULL;

    /* check for element data type */
    if (mm_is_real(matcode))
	types[2] = MM_REAL_STR;
    else if (mm_is_complex(matcode))
	types[2] = MM_COMPLEX_STR;
    else if (mm_is_pattern(matcode))
	types[2] = MM_PATTERN_STR;
    else if (mm_is_integer(matcode))
	types[2] = MM_INT_STR;
    else
	return NULL;


    /* check for symmetry type */
    if (mm_is_general(matcode))
	types[3] = MM_GENERAL_STR;
    else if (mm_is_symmetric(matcode))
	types[3] = MM_SYMM_STR;
    else if (mm_is_hermitian(matcode))
	types[3] = MM_HERM_STR;
    else if (mm_is_skew(matcode))
	types[3] = MM_SKEW_STR;
    else
	return NULL;

    sprintf(buffer, "%s %s %s %s", types[0], types[1], types[2], types[3]);
    return strdup(buffer);

},3,1,1

gf_log_init (const char *file)
{
        if (!file){
                fprintf (stderr, "ERROR: no filename specified\n");
                return -1;
        }

        if (strcmp (file, "-") == 0) {
                gf_log_logfile = stderr;

                return 0;
        }

        filename = gf_strdup (file);
        if (!filename) {
                fprintf (stderr, "ERROR: updating log-filename failed: %s\n",
                         strerror (errno));
                return -1;
        }

        logfile = fopen (file, "a");
        if (!logfile){
                fprintf (stderr, "ERROR: failed to open logfile \"%s\" (%s)\n",
                         file, strerror (errno));
                return -1;
        }

        gf_log_logfile = logfile;

        return 0;
},3,1,1

evhttp_parse_response_line(struct evhttp_request *req, char *line)
{
	char *protocol;
	char *number;
	char *readable;

	protocol = strsep(&line, " ");
	if (line == NULL)
		return (-1);
	number = strsep(&line, " ");
	if (line == NULL)
		return (-1);
	readable = line;

	if (strcmp(protocol, "HTTP/1.0") == 0) {
		req->major = 1;
		req->minor = 0;
	} else if (strcmp(protocol, "HTTP/1.1") == 0) {
		req->major = 1;
		req->minor = 1;
	} else {
		event_debug(("%s: bad protocol \"%s\"",
			__func__, protocol));
		return (-1);
	}

	req->response_code = atoi(number);
	if (!evhttp_valid_response_code(req->response_code)) {
		event_debug(("%s: bad response code \"%s\"",
			__func__, number));
		return (-1);
	}

	if ((req->response_code_line = mm_strdup(readable)) == NULL) {
		event_warn("%s: strdup", __func__);
		return (-1);
	}

	return (0);
},3,1,1

getuserid(char *user)
{
	struct passwd	*pw;
	uid_t			uid;

	if ((pw = getpwnam(user)) != NULL)
		{
			uid = pw->pw_uid;
		}
	else if (*user == '#')
		{
			uid = (uid_t)atoi(&user[1]);
		}
	else
		{
#ifdef HAVE_GETUSERID
			id = getuserid("nobody");
#else
			uid = 65535;
#endif
		}

#if DEBUG
	fprintf(stderr, "User lookup %s -> %d\n", user, uid);
#endif

	endpwent();

	return (uid);
},3,1,1

verifypasscode()
{
	char *issuedpc=NULL, *returnedpc=NULL, *requirepasscode=NULL;

	requirepasscode = getenv("GRST_REQUIRE_PASSCODE");
	issuedpc =  getenv("GRST_PASSCODE_COOKIE");
	returnedpc = GRSThttpGetCGI("passcode");

        /* if GRST_REQUIRE_PASSCODE != on then always OK */

	if (requirepasscode == NULL) return 1;

	if (strcmp(requirepasscode, "on") != 0) return 1;

	/* otherwise, require passcode and that it matches */

	if (issuedpc == NULL) return 0;

	if (returnedpc == NULL) return 0;

	if (strcmp(issuedpc, returnedpc)==0 )return 1;

	return 0;
},3,1,1

