format_function(const expression * e, int prec)
{
    char **args = NULL;
    int num_args = 0;
    char *result;
    int len;
    int i;

    if (e->data.func.argc == 1 && !*e->data.func.name)
	return format_expression_prec(e->data.func.args[1], prec);

    len = strlen(e->data.func.name) + 3;

    for (i = 1; i <= e->data.func.argc; i++) {
	if (i >= num_args) {
	    num_args = i + 1000;
	    args = G_realloc(args, num_args * sizeof(char *));
	}
	args[i] = format_expression_prec(e->data.func.args[i], 9);
	if (i > 1)
	    len += 2;
	len += strlen(args[i]);
    }

    result = G_malloc(len);

    strcpy(result, e->data.func.name);
    strcat(result, "(");
    for (i = 1; i <= e->data.func.argc; i++) {
	if (i > 1)
	    strcat(result, ", ");
	strcat(result, args[i]);
	G_free(args[i]);
    }
    strcat(result, ")");

    return result;
},3,1,1

unset_att(int id, int type, Tcl_Interp * interp, int argc, char *argv[])
{
    int att;

/*** ACS_MODIFY 1.0 BEGIN - site_attr management *******************************/
    int col, width, marker, useatt;
    float size;
    geosite *gp;

    att = att_atoi(argv[2]);

    if (type == SITE) {
	if (!strcmp(argv[2], "useatt") && argc == 5) {
	    GP_get_sitemode(id, &useatt, &col, &width, &size, &marker);
	    if ((gp = gp_get_site(id))) {
		site_attr_unset(interp, gp, atoi(argv[3]), argv[4]);

		if (!strcmp(argv[3], "size")) {
		    useatt &= ~ST_ATT_SIZE;
		}
		else if (!strcmp(argv[3], "color")) {
		    useatt &= ~ST_ATT_COLOR;
		}
		else if (!strcmp(argv[3], "marker")) {
		    useatt &= ~ST_ATT_MARKER;
		}
	    }
	    GP_set_sitemode(id, useatt, col, width, size, marker);
	}
	return TCL_OK;
    }

/*** ACS_MODIFY 1.0 END - site_attr management *********************************/

    if (type != SURF) {
	Tcl_SetResult(interp, "Type must be SURF for unset_att",
		      TCL_VOLATILE);
	return (TCL_ERROR);
    }
    return ((0 > GS_unset_att(id, att)) ? TCL_ERROR : TCL_OK);

},3,1,1

jk_map_get_int_list(jk_map_t *m,
                        const char *name,
                        int *list,
                        unsigned int list_len,
                        const char *def)
{
    const char *l = jk_map_get_string(m, name, def);

#ifdef _MT_CODE_PTHREAD
    char *lasts;
#endif

    if (!list_len)
        return 0;

    if (l) {
        unsigned int capacity = list_len;
        unsigned int index = 0;
        char *p;
        char *v = jk_pool_strdup(&m->p, l);

        if (!v) {
            return 0;
        }

        /*
         * GS, in addition to VG's patch, we now need to
         * strtok also by a "*"
         */
#ifdef _MT_CODE_PTHREAD
        for (p = strtok_r(v, " \t,", &lasts);
             p; p = strtok_r(NULL, " \t,", &lasts))
#else
        for (p = strtok(v, " \t,"); p; p = strtok(NULL, " \t,"))
#endif

        {
            if (index < capacity) {
                list[index] = atoi(p);
                index++;
            }
            else
                break;
        }
        return index;
    }
    return 0;
},3,1,1

print_set_output(char *name, TBOOLEAN append_p)
{
    if (print_out && print_out != stderr && print_out != stdout) {
#ifdef PIPES
	if (print_out_name[0] == '|') {
	    if (0 > pclose(print_out))
		perror(print_out_name);
	} else
#endif
	    if (0 > fclose(print_out))
		perror(print_out_name);
    }

    if (print_out_name)
	free(print_out_name);

    print_out_name = NULL;

    if (! name) {
	print_out = stderr;
	return;
    }

    if (! strcmp(name, "-")) {
	print_out = stdout;
	return;
    }

#ifdef PIPES
    if (name[0]=='|') {
	restrict_popen();
	print_out = popen(name + 1, "w");
	if (!print_out)
	    perror(name);
	else
	    print_out_name = name;
	return;
    }
#endif

    print_out = fopen(name, append_p ? "a" : "w");
    if (!print_out) {
	perror(name);
	return;
    }

    print_out_name = name;
},3,1,1

