match(char* buf, char* host){
  char *s1, *s2, *s3;
  int i;

  if((s1 = strdup(buf)) == NULL) asp_perror("strdup");

  /* Elimina commenti o new line */
  if((s2 = strpbrk(s1, "#\n")) != NULL) *s2 = '\0';

  /* Controlla che host sia contenuto nella linea */
  if((s2 = strstr(s1, host)) == NULL){
    free(s1);
    return 0;
  }

  /* Controlla che ci siano due token */
  if((s2 = strtok(s1, " \t")) == NULL || \
     (s3 = strtok(NULL, " \t")) == NULL || \
     strtok(NULL, " \t") != NULL){
    free(s1);
    return 0;
  }

  /* Controlla che il secondo token sia l'host */
  if(strcasecmp(s3, host) != 0){
    free(s1);
    return 0;
  }

  /* Controlla che il primo token sia un indirizzo IP. */
  if(((i = atoi(s3 = strtok(s2, "."))) > 255 || i < 0) || \
     ((i = atoi(s3 = strtok(NULL, "."))) > 255 || i < 0) || \
     ((i = atoi(s3 = strtok(NULL, "."))) > 255 || i < 0) || \
     ((i = atoi(s3 = strtok(NULL, "."))) > 255 || i < 0)){
    free(s1);
    return 0;
  }

  /* Match! */
  free(s1);
  return 1;

},3,1,1

Ns_AdpRequestEx(Ns_Conn *conn, char *file, Ns_Time *ttlPtr)
{
    Conn	     *connPtr = (Conn *) conn;
    Tcl_Interp       *interp;
    NsInterp         *itPtr;
    char             *start, *type;
    Ns_Set           *query;
    NsServer	     *servPtr;
    Tcl_Obj	     *objv[2];
    int		      result;

    interp = Ns_GetConnInterp(conn);
    itPtr = NsGetInterpData(interp);

    /*
     * Verify the file exists.
     */

    if (access(file, R_OK) != 0) {
	return Ns_ConnReturnNotFound(conn);
    }

    /*
     * Set the output type based on the file type.
     */

    type = Ns_GetMimeType(file);
    if (type == NULL || STREQ(type, "*/*")) {
	type = NSD_TEXTHTML;
    }
    Ns_ConnSetType(conn, type);
    Ns_ConnSetStatus(conn, 200);

    /*
     * Enable TclPro debugging if requested.
     */

    servPtr = connPtr->servPtr;
    if ((itPtr->servPtr->adp.flags & ADP_DEBUG) &&
	STREQ(conn->request->method, "GET") &&
	(query = Ns_ConnGetQuery(conn)) != NULL) {
	itPtr->adp.debugFile = Ns_SetIGet(query, "debug");
    }

    /*
     * Include the ADP with the special start page and null args.
     */

    itPtr->adp.conn = conn;
    start = servPtr->adp.startpage ? servPtr->adp.startpage : file;
    objv[0] = Tcl_NewStringObj(start, -1);
    objv[1] = Tcl_NewStringObj(file, -1);
    Tcl_IncrRefCount(objv[0]);
    Tcl_IncrRefCount(objv[1]);
    result = NsAdpInclude(itPtr, 2, objv, start, ttlPtr);
    Tcl_DecrRefCount(objv[0]);
    Tcl_DecrRefCount(objv[1]);
    if (NsAdpFlush(itPtr, 0) != TCL_OK || result != TCL_OK) {
	return NS_ERROR;
    }
    return NS_OK;
},3,1,1

convert_revision(out, wkfile, branches, rev, initial, comment_leader)
FILE *out ;			/* to shell script to write into */
char *wkfile ;			/* name of working file */
bool branches ;			/* branches exist */
struct RCSREV *rev ;		/* revision struct */
bool initial ;			/* this is the initial revision,
				 * no locking required */
char *comment_leader ;		/* comment leader string */
{
    struct SYMNAME *sym ;

    (void) fprintf(out, "\n\n# %s[%s]\n\n", wkfile, rev->number) ;
    if (!keep_quiet) {
	fprintf(out, "echo -n '[%s] '\n", rev->number) ;
    }

    /* lock previous version */
    if (! initial) {
	fprintf(out, "vadm -q -lock %s \n", wkfile) ;
    }

    /* check out appropriate revision */
    fprintf(out, "co -q -%s %s\n", rev->number, wkfile) ;

    /* set atime and mtime */
    fprintf(out, "utime %ld %ld %s\n", rev->date, rev->date, wkfile) ;

    /* save as AtFS version with log message */
    if (! branches) {
	/* we can only keep version numbers if no branches exist */
	fprintf(out, "save -q -f -m \"%s\" %s[%s]\n",
		rev->log_message ? rev->log_message : "",
		wkfile, rev->number + 1) ;
    } else {
	fprintf(out, "save -q -f -m \"%s\" %s\n", rev->log_message, wkfile) ;
    }

    /* set comment leader */
    fprintf(out, "vadm -q -setc \"%s\" %s\n",
	    comment_leader, wkfile) ;

    /* set author */
    fprintf(out, "vadm -q -chaut %s %s\n", rev->author, wkfile) ;

    /* set symbolic names */
    for (sym = rev->symbolic_names; sym != NULL; sym = sym->next) {
	(void) fprintf(out, "vadm -q -symbolic %s %s\n",
		       sym->symname, wkfile) ;
    }

    /* set state as AtFS-UDA */
    fprintf(out, "vadm -q -setuda RCSstate='%s' %s\n",
	    rev->state ? rev->state : "", wkfile) ;
    /* set RCS revision number as symbolic name */
    fprintf(out, "vadm -q -symbolic %s %s\n",
	    rev->number, wkfile) ;

    /* set AtFS state if RCS state is something known */
    if (! strcmp(rev->state, "Stab")) {
	/* set state to proposed */
	fprintf(out, "vadm -q -promote %s\n", wkfile) ;
    } else if (! strcmp(rev->state, "Rel")) {
	/* set state to published */
	fprintf(out, "vadm -q -promote %s\n", wkfile) ;
	fprintf(out, "vadm -q -promote %s\n", wkfile) ;
    }
},3,1,1

setup_pager(void)
{
	const char *pager = getenv("GIT_PAGER");

	if (!isatty(1))
		return;
	if (!pager) {
		if (!pager_program)
			git_config(git_default_config, NULL);
		pager = pager_program;
	}
	if (!pager)
		pager = getenv("PAGER");
	if (!pager)
		pager = "less";
	else if (!*pager || !strcmp(pager, "cat"))
		return;

	spawned_pager = 1; /* means we are emitting to terminal */

	/* spawn the pager */
	pager_argv[2] = pager;
	pager_process.argv = pager_argv;
	pager_process.in = -1;
#ifndef __MINGW32__
	pager_process.preexec_cb = pager_preexec;
#endif
	if (start_command(&pager_process))
		return;

	/* original process continues, but writes to the pipe */
	dup2(pager_process.in, 1);
	dup2(pager_process.in, 2);
	close(pager_process.in);

	/* this makes sure that the parent terminates after the pager */
	atexit(wait_for_pager);
},3,1,1

M_Mktemp(char *tmpl)
{
				/* redefined to avoid link warning */
#if defined(__unix__) || defined(__CYGWIN__)
				/* this code comes from glibc */
  int len;
  char *XXXXXX;
  static unsigned long value;
  int count;
  struct stat buf;
  static const char letters[] =
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

#ifndef TMP_MAX
#define TMP_MAX 238328
#endif

  len = strlen (tmpl);
  if (len < 6 || strcmp(&tmpl[len - 6], "XXXXXX"))
    {
      errno = EINVAL;
      return NULL;
    }

  /* This is where the Xs start.  */
  XXXXXX = &tmpl[len - 6];

  value += (unsigned long) time(NULL) ^ getpid();

  for (count = 0; count < TMP_MAX; value += 7777, ++count)
    {
      unsigned long v = value;

      /* Fill in the random bits.  */
      XXXXXX[0] = letters[v % 62];
      v /= 62;
      XXXXXX[1] = letters[v % 62];
      v /= 62;
      XXXXXX[2] = letters[v % 62];
      v /= 62;
      XXXXXX[3] = letters[v % 62];
      v /= 62;
      XXXXXX[4] = letters[v % 62];
      v /= 62;
      XXXXXX[5] = letters[v % 62];

      if (lstat(tmpl, &buf) < 0)
	{
	  if (errno == ENOENT)
	    {
	      errno = 0;
	      return tmpl;
	    }
	  else
	    /* Give up now. */
	    return NULL;
	}
    }

  /* We got out of the loop because we ran out of combinations to try.  */
  errno = EEXIST;
  return NULL;

#else

  errno = 0;
  return mktemp(tmpl);

#endif
},3,1,1

