get_params(int argc, char *argv[])
{

	struct parameters params;

	params.try_ingroup = false;
	params.deroot = false;

	int opt_char;
	while ((opt_char = getopt(argc, argv, "dhl")) != -1) {
		switch (opt_char) {
		case '?':
// Review memory allocation here
			exit (EXIT_FAILURE);
		case 'd':
			params.deroot = true;
			break;
		case 'h':
			help(argv);
			exit(EXIT_SUCCESS);
		case 'l':
			params.try_ingroup = true;
			break;
		default:
			fprintf (stderr, "Unknown option '-%c'\n", opt_char);
			exit (EXIT_FAILURE);
		}
	}

	/* check arguments */
	int nargs = argc - optind; /* non-option arguments */
	if (nargs < 1) {
		fprintf(stderr,
			"Usage: %s [-dhl] <filename|->  [label+]\n",
			argv[0]);
		exit(EXIT_FAILURE);
	}
	/* read arguments */
	if (0 != strcmp("-", argv[optind])) {
		FILE *fin = fopen(argv[optind], "r");
		extern FILE *nwsin;
		if (NULL == fin) {
			perror(NULL);
			exit(EXIT_FAILURE);
		}
		nwsin = fin;
	}
	struct llist *lbl_list = create_llist();
	if (NULL == lbl_list) { perror(NULL); exit(EXIT_FAILURE); }
	optind++;	/* optind is now index of 1st label */
	for (; optind < argc; optind++) {
		if (! append_element(lbl_list, argv[optind])) {
			perror(NULL);
			exit(EXIT_FAILURE);
		}
	}
	params.labels = lbl_list;

	return params;
},3,1,1

jk_map_get_int_list(jk_map_t *m,
                        const char *name,
                        int *list,
                        unsigned int list_len,
                        const char *def)
{
    const char *l = jk_map_get_string(m, name, def);

#ifdef _MT_CODE_PTHREAD
    char *lasts;
#endif

    if (!list_len)
        return 0;

    if (l) {
        unsigned int capacity = list_len;
        unsigned int index = 0;
        char *p;
        char *v = jk_pool_strdup(&m->p, l);

        if (!v) {
            return 0;
        }

        /*
         * GS, in addition to VG's patch, we now need to
         * strtok also by a "*"
         */
#ifdef _MT_CODE_PTHREAD
        for (p = strtok_r(v, " \t,", &lasts);
             p; p = strtok_r(NULL, " \t,", &lasts))
#else
        for (p = strtok(v, " \t,"); p; p = strtok(NULL, " \t,"))
#endif

        {
            if (index < capacity) {
                list[index] = atoi(p);
                index++;
            }
            else
                break;
        }
        return index;
    }
    return 0;
},3,1,1

