gettoken(char *buf) {
    static char *marker;
    static char oldch;

    if (buf == NULL)
        *marker = oldch;
    else
        marker = buf;
    while (*marker != '\0' && isSpace(*marker) && *marker != '\n')
        marker++;
    buf = marker;
    if (isISOLetter(*marker))
        while (*marker && isWordCharacter(*marker))
            marker++;
    else if (isdigit((int)*marker))
        while (isdigit((int)*marker))
            marker++;
    else if (*marker == '\"') {
        marker++;
        while (*marker != '\"')
            marker++;
        marker++;
    } else if (*marker == '\0' || *marker == '\n' || *marker == ';')
        return NULL;
    else
        marker++;
    oldch = *marker;
    *marker = '\0';
    return buf;
},3,1,1

