HpmfwupgGetBufferFromFile(char *imageFilename,
		struct HpmfwupgUpgradeCtx *pFwupgCtx)
{
	int rc = HPMFWUPG_SUCCESS;
	int ret = 0;
	FILE *pImageFile = fopen(imageFilename, "rb");
	if (pImageFile == NULL) {
		lprintf(LOG_ERR, "Cannot open image file '%s'",
				imageFilename);
		return HPMFWUPG_ERROR;
	}
	/* Get the raw data in file */
	fseek(pImageFile, 0, SEEK_END);
	pFwupgCtx->imageSize  = ftell(pImageFile);
	pFwupgCtx->pImageData = malloc(sizeof(unsigned char)*pFwupgCtx->imageSize);
	if (pFwupgCtx->pImageData == NULL) {
		lprintf(LOG_ERR, "ipmitool: malloc failure");
		fclose(pImageFile);
		return HPMFWUPG_ERROR;
	}
	rewind(pImageFile);
	ret = fread(pFwupgCtx->pImageData,
			sizeof(unsigned char),
			pFwupgCtx->imageSize,
			pImageFile);
	if (ret != pFwupgCtx->imageSize) {
		lprintf(LOG_ERR,
				"Failed to read file %s size %d", 
				imageFilename,
				pFwupgCtx->imageSize);
		rc = HPMFWUPG_ERROR;
	}
	fclose(pImageFile);
	return rc;
},3,1,1

main(int argc,  char *argv[]) {

	char *ptr;

	start_time();

	/*----- standard command line parsing ---------------------------------*/
	strcpy(prgCall,argv[0]);
	if (argc < 2) printUsage();

	while (argv[1][0] == '-') {
		switch (argv[1][1]) {
			case 't':
				opt_t = 1;
				if (strcmp(argv[1],"-t")) printUsage();
				argc--;
				argv++;
				if ((sscanf(argv[1],"%c",&frameChar) < 1) || ((frameChar != '0') && (frameChar != '1') && (frameChar != '2') && (frameChar != '.'))) printUsage();
				break;
			case 'x':
				opt_x = 1;
				if (strcmp(argv[1],"-x")) printUsage();
				argc--;
				argv++;
				if (sscanf(argv[1],"%s",xName) < 1) printUsage();
				ptr = xName;
				break;
			case 'y':
				opt_y = 1;
				if (strcmp(argv[1],"-y")) printUsage();
				argc--;
				argv++;
				if (sscanf(argv[1],"%s",yName) < 1) printUsage();
				ptr = yName;
				break;
			case 'r': opt_r = 1; break;
			case 'i': opt_i = 1; break;
			case 'f': opt_f = 1; break;
			case 'h': printUsage(); break;
			default:  printUsage(); break;
		}
		argc--;	/* count of left arguments */
		argv++;	/* move the pointer to the right */
	}
	if (argc > 2) printUsage();
	strcpy(infile,argv[1]);

	/*----- choose output channel ----*/
	if (opt_f) {
		/*
		fileptr = strrchr(infile,'/');
		if (fileptr == NULL)
		*/	
			strcpy(outfile,infile);
		/*
		else strcpy(outfile,++fileptr);
		*/
		strcat(outfile,".gff");
		if (!(stdoutCopy = fopen(outfile, "w"))) {fprintf(stderr,"Error: Unable to write file %s\n",outfile); exit(4);}	
	}
	else stdoutCopy = stdout;

	doit();

	if (DEBUG) print_time();
	return 0;
},3,1,1

makesimplepathstring3(CDFnode* var)
{
    int slen,i,len,first;
    char* pathname;
    NClist* path = nclistnew();

    collectnodepath3(var,path,!WITHDATASET);
    len = nclistlength(path);
    if(len == 0) {pathname = nulldup(""); goto done;} /* Dataset only */
    for(slen=0,i=0;i<len;i++) {
	CDFnode* node = (CDFnode*)nclistget(path,i);
	slen += (node->name?strlen(node->name):0);
    }
    slen += (len-1); /* for 1-char separators */
    slen += 1;   /* for null terminator*/
    pathname = (char*)malloc(slen);
    MEMCHECK(pathname,NULL);
    pathname[0] = '\0';    
    for(first=1,i=0;i<len;i++) {
	CDFnode* node = (CDFnode*)nclistget(path,i);
	char* name = node->name;
	if(!first) strcat(pathname,".");
        strcat(pathname,name?name:"null");
	first = 0;
    }
done:
    nclistfree(path);
    return pathname;
},3,1,1

handle_options_work(lms_t *lms, int argc, char **argv)
{
    int opt_index, method, verbose;

    verbose = 0;
    method = 2;
    optind = 0;
    opterr = 0;
    opt_index = 0;
    while (1) {
        int c;

        c = getopt_long(argc, argv, short_options, long_options, &opt_index);
        if (c == -1)
            break;

        switch (c) {
        case 'm':
            if (strcmp(optarg, "1") == 0 ||
                strcmp(optarg, "mono") == 0)
                method = 1;
            else if (strcmp(optarg, "2") == 0 ||
                     strcmp(optarg, "dual") == 0)
                method = 2;
            else
                fprintf(stderr,
                        "ERROR: invalid method=%s, should be 'mono' (1) or "
                        "'dual' (2). Default is dual.\n",
                        optarg);
        case 'v':
            if (optarg)
                verbose = !!atoi(optarg);
            else
                verbose = 1;
            break;
        case 's':
            if (work(lms, method, verbose, optarg) != 0)
                return -1;
            break;
        case 'S':
            show(lms, optarg);
            break;
        default:
            break;
        }
    }

    return 0;
},3,1,1

read_repeats()
{
   int nrep;
   FILE *frep;
   char line[MAXLINE] ;

   nrep = 0;
   MaxRepeat = 0;

   /*   Look in current directory first */
   frep=fopen("repeats.dat", "r");
/*
   if (frep == NULL)
   {
      sprintf(fname, "%srepeats.dat", DatDir);
      frep=fopen(fname, "r");
   }
*/

   if (frep != NULL)
   {
      while (nrep < MAXGROUP && 
             !feof(frep) && fgets(line, MAXLINE, frep) != NULL)
      {
         if (line[0] != '>' && line[0] != '#')
         {
            sscanf(line, "%s %d", Repeats[nrep].ac, &Repeats[nrep].num);
            if (Repeats[nrep].num < 0) Repeats[nrep].num = 0;
            if (Repeats[nrep].num > MaxRepeat) MaxRepeat = Repeats[nrep].num;
            nrep++;
         }
      }
   }
   return(nrep);
},3,1,1

