main(int argc, char **argv)
{
	char	*pdir;
#if	defined(NHONSUID) || defined(DEBUG)
	int_ugid_t	chk_uid;
#endif
	versionprint(argv, "$Revision: 1.1 $", 0);

	if  ((progname = strrchr(argv[0], '/')))
		progname++;
	else
		progname = argv[0];

	init_mcfile();

	Realuid = getuid();
	Effuid = geteuid();
	INIT_DAEMUID;
	Cfile = open_cfile(MISC_UCONFIG, "rest.help");
	SCRAMBLID_CHECK
	SWAP_TO(Daemuid);
	mypriv = getspuser(Realuid);
	Displayopts.opt_classcode = mypriv->spu_class;
	/* Now we want to be Daemuid throughout if possible.  */
	setuid(Daemuid);

	if  (argc < 2)  {
	usage:
		fprintf(stderr, "Usage: %s [-n] ptr [form]\n", progname);
		exit(E_USAGE);
	}
	if  (strcmp(argv[1], "-n") == 0)  {
		expandem = 0;
		argv++;
		argc--;
	}

	if  (argc < 2  ||  argc > 3)
		goto  usage;

	if  ((Ctrl_chan = msgget(MSGID, 0)) < 0)  {
		fprintf(stderr, "%s: Spooler not running\n", progname);
		exit(E_NOTRUN);
	}

#ifndef	USING_FLOCK
	/* Set up semaphores */

	if  ((Sem_chan = semget(SEMID, SEMNUMS, IPC_MODE)) < 0)  {
		fprintf(stderr, "%s: Cannot open semaphore\n", progname);
		exit(E_SETUP);
	}
#endif

	if  (!jobshminit(0))  {
		fprintf(stderr, "%s: Cannot open jshm\n", progname);
		return  E_JOBQ;
	}
	if  (!ptrshminit(0))  {
		fprintf(stderr, "%s: Cannot open pshm\n", progname);
		return  E_PRINQ;
	}
	readptrlist(1);
	pdir = envprocess(PTDIR);
	if  (chdir(pdir) < 0)  {
		fprintf(stderr, "%s: Cannot open ptr dir %s\n", progname, pdir);
		exit(E_SETUP);
	}

	return  do_bizniz(argv[1], argv[2]);
},3,1,1

glade_gtk_menu_shell_set_child_property (GladeWidgetAdaptor  *adaptor,
					 GObject             *container,
					 GObject             *child,
					 const gchar         *property_name,
					 GValue              *value)
{
	g_return_if_fail (GTK_IS_MENU_SHELL (container));
	g_return_if_fail (GTK_IS_MENU_ITEM (child));
	g_return_if_fail (property_name != NULL || value != NULL);

	if (strcmp (property_name, "position") == 0)
	{
		GladeWidget *gitem;
		gint position;

		gitem = glade_widget_get_from_gobject (child);
		g_return_if_fail (GLADE_IS_WIDGET (gitem));

		position = g_value_get_int (value);

		if (position < 0)
		{
			position = glade_gtk_menu_shell_get_item_position (container, child);
			g_value_set_int (value, position);
		}

		g_object_ref (child);
		gtk_container_remove (GTK_CONTAINER (container), GTK_WIDGET (child));
		gtk_menu_shell_insert (GTK_MENU_SHELL (container), GTK_WIDGET (child), position);
		g_object_unref (child);

	}
	else
		/* Chain Up */
		GWA_GET_CLASS
			(GTK_TYPE_CONTAINER)->child_set_property (adaptor, 
								  container, child,
								  property_name, value);
},3,1,1

adjust_array(enum ECPGttype type_enum, char **dimension, char **length, char *type_dimension, char *type_index, int pointer_len, bool type_definition)
{
	if (atoi(type_index) >= 0)
	{
		if (atoi(*length) >= 0)
			mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support");

		*length = type_index;
	}

	if (atoi(type_dimension) >= 0)
	{
		if (atoi(*dimension) >= 0 && atoi(*length) >= 0)
			mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support");

		if (atoi(*dimension) >= 0)
			*length = *dimension;

		*dimension = type_dimension;
	}

	if (pointer_len > 2)
		mmerror(PARSE_ERROR, ET_FATAL, "No multilevel (more than 2) pointer supported %d", pointer_len);

	if (pointer_len > 1 && type_enum != ECPGt_char && type_enum != ECPGt_unsigned_char)
		mmerror(PARSE_ERROR, ET_FATAL, "No pointer to pointer supported for this type");

	if (pointer_len > 1 && (atoi(*length) >= 0 || atoi(*dimension) >= 0))
		mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support");

	if (atoi(*length) >= 0 && atoi(*dimension) >= 0 && pointer_len)
		mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support");

	switch (type_enum)
	{
		case ECPGt_struct:
		case ECPGt_union:
			/* pointer has to get dimension 0 */
			if (pointer_len)
			{
				*length = *dimension;
				*dimension = make_str("0");
			}

			if (atoi(*length) >= 0)
				mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support for structures");

			break;
		case ECPGt_varchar:
			/* pointer has to get dimension 0 */
			if (pointer_len)
				*dimension = make_str("0");

			/* one index is the string length */
			if (atoi(*length) < 0)
			{
				*length = *dimension;
				*dimension = make_str("-1");
			}

			break;
		case ECPGt_char:
		case ECPGt_unsigned_char:
			/* char ** */
			if (pointer_len == 2)
			{
				*length = *dimension = make_str("0");
				break;
			}

			/* pointer has to get length 0 */
			if (pointer_len == 1)
				*length = make_str("0");

			/* one index is the string length */
			if (atoi(*length) < 0)
			{
				/*
				 * make sure we return length = -1 for arrays without given
				 * bounds
				 */
				if (atoi(*dimension) < 0 && !type_definition)

					/*
					 * do not change this for typedefs since it will be
					 * changed later on when the variable is defined
					 */
					*length = make_str("1");
				else if (strcmp(*dimension, "0") == 0)
					*length = make_str("-1");
				else
					*length = *dimension;

				*dimension = make_str("-1");
			}
			break;
		default:
			/* a pointer has dimension = 0 */
			if (pointer_len)
			{
				*length = *dimension;
				*dimension = make_str("0");
			}

			if (atoi(*length) >= 0)
				mmerror(PARSE_ERROR, ET_FATAL, "No multidimensional array support for simple data types");

			break;
	}
},3,1,1

eet_mempool_init(void)
{
   const char *choice;
   unsigned int i;

   choice = getenv("EINA_MEMPOOL");
   if ((!choice) || (!choice[0]))
     choice = "chained_mempool";

   for (i = 0; i < sizeof (mempool_array) / sizeof (mempool_array[0]); ++i)
     {
     retry:
        mempool_array[i]->mp = eina_mempool_add(choice, mempool_array[i]->name, NULL, mempool_array[i]->size, 16);
        if (!mempool_array[i]->mp)
          {
             if (!(!strcmp(choice, "pass_through")))
               {
                  ERR("Falling back to pass through ! Previously tried '%s' mempool.", choice);
                  choice = "pass_through";
                  goto retry;
               }
             else
               {
                  ERR("Impossible to allocate mempool '%s' !", choice);
                  return EINA_FALSE;
               }
          }
     }
   return EINA_TRUE;
},3,1,1

auto_guess(file)
char	*file;
{
	char *suffix;

	(suffix = strrchr(file, '.')) ? suffix++ : (suffix = "");
	/* fixed by jmp@inesc */
	if((strcmp(file, "makefile") == 0) ||
	   (strcmp(file, "Makefile") == 0) ||
	   (strcmp(file, "shapefile") == 0) ||
	   (strcmp(file, "Shapefile") == 0) ||
	    (strcmp(suffix, "mk") == 0)) {	/* sys V std suffix */
		mflag = TRUE;
		sflag = FALSE;
		Sflag = FALSE;
		cflag = FALSE;
		eflag = FALSE;
		hflag = FALSE;
		Mflag = FALSE;
		fflag = FALSE;
	}
	if((strcmp(suffix, "sh") == 0) || (strcmp(suffix, "csh") == 0)) {
		sflag = TRUE;
		Sflag = FALSE;
		cflag = FALSE;
		eflag = FALSE;
		hflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		fflag = FALSE;
	}
	if(strcmp(suffix, "c") == 0){
		cflag = TRUE;
		eflag = FALSE;
		hflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		sflag = FALSE;
		Sflag = FALSE;
		fflag = FALSE;
	}
	if(strcmp(suffix, "el") == 0){
		eflag = TRUE;
		cflag = FALSE;
		hflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		sflag = FALSE;
		Sflag = FALSE;
		fflag = FALSE;
	}
	if(strcmp(suffix, "h") == 0){
		hflag = TRUE;
		cflag = FALSE;
		eflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		sflag = FALSE;
		Sflag = FALSE;
		fflag = FALSE;
	}
	if(strcmp(suffix, "f") == 0){
		fflag = TRUE;
		hflag = FALSE;
		cflag = FALSE;
		eflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		sflag = FALSE;
		Sflag = FALSE;
	}
	if(strcmp(suffix, "S") == 0){
		Sflag = TRUE;
		fflag = FALSE;
		hflag = FALSE;
		cflag = FALSE;
		eflag = FALSE;
		mflag = FALSE;
		Mflag = FALSE;
		sflag = FALSE;
	}
	if(isdigit(*suffix) != 0) {
		Mflag = TRUE;
		hflag = FALSE;
		cflag = FALSE;
		eflag = FALSE;
		mflag = FALSE;
		sflag = FALSE;
		Sflag = FALSE;
		fflag = FALSE;
	}
	set_flags();
	if(!qflag || debugon)
		printf("Hmm.  This file looks like a %s file.\n", msg_name);
},3,1,1

define_macro (name, value, mtype)
     char *name, *value;
     int mtype;
{
  char *mt_val = "";
  register char *lptr;

  if (!(name && *name))
    return;

  if (!value) value = mt_val;

  while (*value && isspace (*value)) value++;
  lptr = value;
  while (*lptr) lptr++;
  if (lptr > value) lptr--;
  while (*lptr && isspace (*lptr)) lptr--;
  if (*lptr)
    *(lptr+1) = '\0';

  if (!strcmp(name,"RECDEPTH")) {
    rec_do_depth = atoi(value);
  }
  addHash (name, value, mtype);
  if (!strcmp(name,"VPATH"))
    insertvpath(value);
  if (!strcmp(name,"IMPORT"))
    get_macrodefs_from_env();   /* macros are immediately defined */
},3,1,1

nexttoken(void)
{
  if (eof) return;
  if (getnew) {
    while (1) {
      if (gettoken(INPUT) == 0) {
        if (iostackempty()) {
          eof = 1;
          getnew = 0;
          return;
        } else {
          pop_iostack();
        }
      } else if (strcmp(INPUT, "(*") == 0) {
        get_comment();
      } else if (strcmp(INPUT, "include") == 0) {
        if (gettoken(INPUT) == 0) {
          error_header();
          fprintf(stderr, "Empty include statement\n");
          exit(1);
        } else {
          push_iostack(0);
        }
      } else if (strcmp(INPUT, "shell") == 0) {
        if (gettoken(INPUT) == 0 || strcmp(INPUT, ":") != 0) {
          error_header();
          fprintf(stderr, "'shell' must be followed by ':'\n");
          exit(1);
        } 
        if (getsystemstring() == 0) {
          fprintf(stderr, "Empty shell statement\n");
          exit(1);
        }
        push_iostack(1);
      } else {
        getnew = 1;
        return;
      }
    }
  }
  getnew = 1;
  return;
},3,0,0

set_res(Tcl_Interp * interp, int id, int type, int argc, char *argv[])
{
    int xres, yres, xwire, ywire;

    if (type != SURF) {
	Tcl_SetResult(interp,
		      "Error: map object must be a surface in order to use set_res",
		      TCL_VOLATILE);
	return (TCL_ERROR);
    }

    if (argc < 5) {
	Tcl_SetResult(interp,
		      "Usage: <map_obj> set_res [ [wire xwire ywire] |\n\t\t[poly xres yres] |\n\t\t[both xres yres xwire ywire] ]",
		      TCL_VOLATILE);
	return (TCL_ERROR);
    }

    GS_get_drawres(id, &xres, &yres, &xwire, &ywire);
    if (!strcmp(argv[2], "poly")) {
	xres = atoi(argv[3]);
	yres = atoi(argv[4]);
    }
    else if (!strcmp(argv[2], "wire")) {
	xwire = atoi(argv[3]);
	ywire = atoi(argv[4]);
    }
    else if (!strcmp(argv[2], "both") && argc == 7) {
	xres = atoi(argv[3]);
	yres = atoi(argv[4]);
	xwire = atoi(argv[5]);
	ywire = atoi(argv[6]);
    }
    else {
	Tcl_SetResult(interp,
		      "Usage: <map_obj> set_res [ [wire xwire ywire] |\n\t\t[poly xres yres] |\n\t\t[both xres yres xwire ywire] ]",
		      TCL_VOLATILE);
	return (TCL_ERROR);
    }

    GS_set_drawres(id, xres, yres, xwire, ywire);

    return (TCL_OK);
},3,1,1

spifconf_parse(spif_charptr_t conf_name, const spif_charptr_t dir, const spif_charptr_t path)
{
    FILE *fp;
    spif_charptr_t name = NULL, p = SPIF_CAST(charptr) ".";
    spif_char_t buff[CONFIG_BUFF], orig_dir[PATH_MAX];

    REQUIRE_RVAL(conf_name != NULL, 0);

    *orig_dir = 0;
    if (path) {
        if ((name = spifconf_find_file(conf_name, dir, path)) != NULL) {
            if ((p = SPIF_CAST(charptr) strrchr(SPIF_CAST_C(char *) name, '/')) != NULL) {
                getcwd(SPIF_CAST_C(char *) orig_dir, PATH_MAX);
                *p = 0;
                p = name;
                chdir(SPIF_CAST_C(char *) name);
            } else {
                p = SPIF_CAST(charptr) ".";
            }
        } else {
            return NULL;
        }
    }
    if ((fp = spifconf_open_file(conf_name)) == NULL) {
        return NULL;
    }
	/* Line count starts at 1 because spifconf_open_file() parses the first line. */
    file_push(fp, conf_name, NULL, 1, 0);

    for (; fstate_idx > 0;) {
        for (; fgets(SPIF_CAST_C(char *) buff, CONFIG_BUFF, file_peek_fp());) {
            file_inc_line();
            if (!strchr(SPIF_CAST_C(char *) buff, '\n')) {
                libast_print_error("Parse error in file %s, line %lu:  line too long\n",
                                   file_peek_path(), file_peek_line());
                for (; fgets(SPIF_CAST_C(char *) buff, CONFIG_BUFF, file_peek_fp())
                       && !strrchr(SPIF_CAST_C(char *) buff, '\n'););
                continue;
            }
            spifconf_parse_line(fp, buff);
        }
        fclose(file_peek_fp());
        if (file_peek_preproc()) {
            remove(SPIF_CAST_C(char *) file_peek_outfile());
            FREE(file_peek_outfile());
        }
        file_pop();
    }
    if (*orig_dir) {
        chdir(SPIF_CAST_C(char *) orig_dir);
    }
    D_CONF(("Returning \"%s\"\n", p));
    return (SPIF_CAST(charptr) STRDUP(p));
},3,1,1

nautilus_get_xdg_dir (const char *type)
{
	int i;

	if (cached_xdg_dirs == NULL) {
		update_xdg_dir_cache ();
	}

	for (i = 0 ; cached_xdg_dirs != NULL && cached_xdg_dirs[i].type != NULL; i++) {
		if (strcmp (cached_xdg_dirs[i].type, type) == 0) {
			return g_strdup (cached_xdg_dirs[i].path);
		}
	}
	if (strcmp ("DESKTOP", type) == 0) {
		return g_build_filename (g_get_home_dir (), DESKTOP_DIRECTORY_NAME, NULL);
	}
	if (strcmp ("TEMPLATES", type) == 0) {
		return g_build_filename (g_get_home_dir (), "Templates", NULL);
	}

	return g_strdup (g_get_home_dir ());
},3,1,1

pop_iostack(void)
{
  Iostack n;

  fflush(IOSTREAM);
  if (pipe) {
    if (pclose(IOSTREAM)) {
      /*error_header();
      fprintf(stderr, "\n\nPipe returned a non-zero error code.\n");
      exit(1); */
    }
  } else {
    fclose(IOSTREAM);
  }
  n = last(stack);
  if (n->stream == NULL) {
    n->stream = fopen(n->filename, "r");
    if (n->stream == NULL) {
      fprintf(stderr, "Error: cannot open file \"%s\"\n", n->filename);
      exit(1);
    }
  }
  IOSTREAM = n->stream;
  strcpy(FILENAME, n->filename);
  free(n->filename);
  pipe = n->pipe;
  line = n->line;
  oldchar = n->oldchar;
  oldcharvalid = n->oldcharvalid;
  delete_item((List)n);
  free_node((List)n, (List)stack);
},3,1,1

