ut_init(int argc, char **argv, const char *groupName, Test allTests) {
    Test	t;
    char	*appName = *argv;
    char	*a;
    int		runAll = 1;

    ut_out = stdout;
    tests = allTests;
    group = groupName;
    for (t = tests; t->name != 0; t++) {
	t->pass = -1;
	t->run = 0;
    }
    argc--;
    argv++;
    for (; 0 < argc; argc--, argv++) {
	a = *argv;
	if (0 == strcmp("-o", a)) {
	    argc--;
	    argv++;
	    if (0 == (ut_out = fopen(*argv, "a"))) {
		printf("Failed to open %s\n", *argv);
		usage(appName);
	    }
	} else if (0 == strcmp("-c", a)) {
	    argc--;
	    argv++;
	    if (0 == (ut_out = fopen(*argv, "w"))) {
		printf("Failed to open %s\n", *argv);
		usage(appName);
	    }
	} else if (0 == strcmp("-v", a)) {
	    ut_verbose += 1;
	} else {
	    if (0 == (t = findTest(a))) {
		printf("%s does not contain test %s\n", group, a);
		usage(appName);
	    }
	    t->run = 1;
	    runAll = 0;
	}
    }
    if (runAll) {
	for (t = tests; t->name != 0; t++) {
	    t->run = 1;
	}
    }
    ut_print("%s tests started\n", group);

    for (currentTest = tests; currentTest->name != 0; currentTest++) {
	if (currentTest->run) {
	    if (2 <= ut_verbose) {
		printf(">>> %s\n", currentTest->name);
	    }
	    currentTest->func();
	    if (2 <= ut_verbose) {
		printf("<<< %s\n", currentTest->name);
	    }
	}
    }
},3,1,1

check_for_hostspec(char *s, char **host_ptr, int *port_ptr)
{
	char *path;

	if (port_ptr && strncasecmp(URL_PREFIX, s, strlen(URL_PREFIX)) == 0) {
		*host_ptr = parse_hostspec(s + strlen(URL_PREFIX), &path, port_ptr);
		if (*host_ptr) {
			if (!*port_ptr)
				*port_ptr = RSYNC_PORT;
			return path;
		}
	}

	*host_ptr = parse_hostspec(s, &path, NULL);
	if (!*host_ptr)
		return NULL;

	if (*path == ':') {
		if (port_ptr && !*port_ptr)
			*port_ptr = RSYNC_PORT;
		return path + 1;
	}
	if (port_ptr)
		*port_ptr = 0;

	return path;
},3,1,1

hoz_getsize()
{
    gchar baz[101];
    const gchar *foo, *qux;
    size_t bar, mult;

    foo =
        gtk_entry_get_text(GTK_ENTRY
                           (lookup_widget
                            (GTK_WIDGET(window_hoz), "entry_size")));
    qux = gtk_entry_get_text(GTK_ENTRY(lookup_widget(GTK_WIDGET(window_hoz),\
		    "combo_entry_size")));
    if (!strcmp(qux, "MiB")) {
	mult = 1024*1024;
    } else if (!strcmp(qux, "KiB")) {
	mult = 1024;
    } else {
	mult = 1;
    }
    bar = (size_t) atolmp((char *) foo, mult);
    partsize = (bar) ? bar : 0;
    if (!partsize && strlen(foo)) {
        sprintf(baz, HOZ_BADSIZE, foo);
        if (!window_bs) {
            window_bs = create_dialog_bs();
        }
        gtk_window_set_title(GTK_WINDOW(window_bs), HOZ_PROGRAM);
        gtk_label_set_label(GTK_LABEL
                            (lookup_widget
