                            baz);
        gtk_button_set_label(GTK_BUTTON
                             (lookup_widget
                              (GTK_WIDGET(window_bs), "okbutton_bs")),
                             "Ok");
        gtk_widget_show(window_bs);
    }
    return partsize;
},3,1,1

