    mt = mTime(cfgFiles[idx].name->str);
    if (dep->name != cfgFiles[idx].name) {
        if (dep->name)
            delStr(dep->name);
        dep->name = cfgFiles[idx].name;
        dep->name->cnt++;
        dep->time = mt;
        return 1;
