InitEasySymbolInput( ChewingData *pgdata, const char *prefix )
{
// Review memory allocation here

	FILE *file = NULL;
	char *filename = NULL;
	char *line = NULL;
	int len;
	int _index;
	char *symbol;
	int ret = -1;

	ret = asprintf( &filename, "%s" PLAT_SEPARATOR "%s",
			prefix, SOFTKBD_TABLE_FILE );
	if ( ret == -1 )
		goto end;

	file = fopen( filename, "r" );
	if ( !file )
		goto end;

	line = ALC( char, LINE_LEN );
	if ( !line )
		goto end;

	while ( fgets( line, LINE_LEN, file ) ) {
		if ( ' ' != line[ 1 ] )
			continue;

// Performance could be improved
		len = strcspn( line, "\r\n" );

		line[ len ] = '\0';

		_index = FindEasySymbolIndex( line[ 0 ] );
		if ( -1 == _index )
			continue;

		len = ueStrLen( &line[ 2 ] );
		if ( 0 == len || len > MAX_PHRASE_LEN )
			continue;

		symbol = ALC( char, strlen( &line[2] ) + 1 );
		if ( !symbol )
			goto end;

		ueStrNCpy( symbol, &line[ 2 ], len, 1 );

		free( pgdata->static_data.g_easy_symbol_value[ _index ] );
		pgdata->static_data.g_easy_symbol_value[ _index ] = symbol;
		pgdata->static_data.g_easy_symbol_num[ _index ] = len;
	}
	ret = 0;
end:
	free( line );
	fclose( file );
	free ( filename );
	return ret;
},3,1,1

parse_args (int argc, char * argv[])
{
  int i;

  for (i = 1; i < argc; i++) {
    if (!strcmp (argv[i], "--nasty")) {
      test_blocksizes = nasty_blocksizes;
      test_samplerates = nasty_samplerates;
      test_channels = nasty_channels;
    } else if (!strcmp (argv[i], "--iter")) {
      i++; if (i >= argc) usage(argv[0]);
      iter = atoi (argv[i]);
    } else if (!strcmp (argv[i], "--disable-vorbis")) {
      test_vorbis = 0;
    } else if (!strcmp (argv[i], "--disable-speex")) {
      test_speex = 0;
    } else if (!strcmp (argv[i], "--disable-flac")) {
      test_flac = 0;
    } else if (!strcmp (argv[i], "--disable-interleave")) {
      test_interleave = 0;
    } else if (!strcmp (argv[i], "--disable-non-interleave")) {
      test_non_interleave = 0;
    } else if (!strcmp (argv[i], "--help") || !strcmp (argv[i], "-h")) {
      usage(argv[0]);
    }
  }

  INFO ("Testing encode/decode pipeline for audio");

  /* Report abnormal options */

  if (test_blocksizes == nasty_blocksizes)
    INFO ("* Running NASTY large test parameters");

  if (!test_vorbis) INFO ("* DISABLED testing of Vorbis");
  if (!test_speex) INFO ("* DISABLED testing of Speex");
  if (!test_flac) INFO ("* DISABLED testing of Flac");
  if (!test_interleave) INFO ("* DISABLED testing of INTERLEAVE");
  if (!test_non_interleave) INFO ("* DISABLED testing of NON-INTERLEAVE");
},3,1,1

