get_number_of_occuped_orbitals(gchar* FileName, gint* nAlpha, gint* nBeta)
{
 	gchar *t;
 	FILE *file;
	gchar *tag=NULL;
	gint necore = 0;

	*nAlpha=-1;
	*nBeta=-1;
 	if ((!FileName) || (strcmp(FileName,"") == 0)) return;

 	t=g_malloc(BSIZE*sizeof(gchar));
 	file = FOpen(FileName, "rb");
 	if(file ==NULL) return;

	tag=g_strdup_printf("NUMBER OF OCCUPIED ORBITALS ");
	while(!feof(file))
	{
		if(!fgets(t,BSIZE,file))break;
		if(strstr(t,tag))
		{
			gchar* equal=strstr(t,"=");
			if(equal) *nAlpha=atoi(equal+1);
			if(!fgets(t,BSIZE,file))break;
			equal=strstr(t,"=");
			if(equal) *nBeta=atoi(equal+1);
		}

	}
	if(tag!=NULL) g_free(tag);
	if(t!=NULL) g_free(t);
	if(file) fclose(file);
	necore = get_number_of_ecp_core_electrons(FileName);
	*nAlpha -= necore/2;
	*nBeta -= necore/2;
	if(*nAlpha<0) *nAlpha= 0;
	if(*nBeta<0) *nBeta= 0;
},3,1,1

bzopen_or_bzdopen
               ( const char *path,   /* no use when bzdopen */
                 int fd,             /* no use when bzdopen */
                 const char *mode,
                 int open_mode)      /* bzopen: 0, bzdopen:1 */
{
   int    bzerr;
   char   unused[BZ_MAX_UNUSED];
   int    blockSize100k = 9;
   int    writing       = 0;
   char   mode2[10]     = "";
   FILE   *fp           = NULL;
   BZFILE *bzfp         = NULL;
   int    verbosity     = 0;
   int    workFactor    = 30;
   int    smallMode     = 0;
   int    nUnused       = 0; 

   if (mode == NULL) return NULL;
   while (*mode) {
      switch (*mode) {
      case 'r':
         writing = 0; break;
      case 'w':
         writing = 1; break;
      case 's':
         smallMode = 1; break;
      default:
         if (isdigit((int)(*mode))) {
            blockSize100k = *mode-BZ_HDR_0;
         }
      }
      mode++;
   }
   strcat(mode2, writing ? "w" : "r" );
   strcat(mode2,"b");   /* binary mode */

   if (open_mode==0) {
      if (path==NULL || strcmp(path,"")==0) {
        fp = (writing ? stdout : stdin);
        SET_BINARY_MODE(fp);
      } else {
        fp = fopen(path,mode2);
      }
   } else {
#ifdef BZ_STRICT_ANSI
      fp = NULL;
#else
      fp = fdopen(fd,mode2);
#endif
   }
   if (fp == NULL) return NULL;

   if (writing) {
      /* Guard against total chaos and anarchy -- JRS */
      if (blockSize100k < 1) blockSize100k = 1;
      if (blockSize100k > 9) blockSize100k = 9; 
      bzfp = BZ2_bzWriteOpen(&bzerr,fp,blockSize100k,
                             verbosity,workFactor);
   } else {
      bzfp = BZ2_bzReadOpen(&bzerr,fp,verbosity,smallMode,
                            unused,nUnused);
   }
   if (bzfp == NULL) {
      if (fp != stdin && fp != stdout) fclose(fp);
      return NULL;
   }
   return bzfp;
},3,1,1

rfbProcessSizeArguments(int* width,int* height,int* bpp,int* argc, char *argv[])
{
