varnish_wait(struct varnish *v)
{
	void *p;
	int status, r;

	if (v->cli_fd < 0)
		return;
	if (vtc_error)
		(void)sleep(1);	/* give panic messages a chance */
	varnish_stop(v);
	vtc_log(v->vl, 2, "Wait");
	AZ(close(v->cli_fd));
	v->cli_fd = -1;

	(void)close(v->fds[1]);		/* May already have been closed */

	AZ(pthread_join(v->tp, &p));
	AZ(close(v->fds[0]));
	r = wait4(v->pid, &status, 0, NULL);
	v->pid = 0;
	vtc_log(v->vl, 2, "R %d Status: %04x", r, status);
	AZ(pthread_join(v->tp_vsl, &p));
	if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
		return;
#ifdef WCOREDUMP
	vtc_log(v->vl, 0, "Bad exit code: %04x sig %x exit %x core %x",
	    status, WTERMSIG(status), WEXITSTATUS(status),
	    WCOREDUMP(status));
#else
	vtc_log(v->vl, 0, "Bad exit code: %04x sig %x exit %x",
	    status, WTERMSIG(status), WEXITSTATUS(status));
#endif
},3,1,1

config_sockopts(struct configuration *p, struct server_sockopts **ss)
{
	struct server_sockopts *s;
	const char *t;
	int l, n, o, *op;
	unsigned long u;
	enum {
		SO_FLAG,
		SO_INT
	} what;

	if ((t = gettoken(p)) != t_open)
		return t;
	while ((t = gettoken(p)) != t_close) {
#ifdef SO_RCVBUF
		if (!strcasecmp(p->tokbuf, "rcvbuf")) {
			l = SOL_SOCKET;
			n = SO_RCVBUF;
			what = SO_INT;
		} else
#endif
#ifdef SO_SNDBUF
		if (!strcasecmp(p->tokbuf, "sndbuf")) {
			l = SOL_SOCKET;
			n = SO_SNDBUF;
			what = SO_INT;
		} else
#endif
#ifdef IPV6_V6ONLY
		if (!strcasecmp(p->tokbuf, "v6only")) {
			l = IPPROTO_IPV6;
			n = IPV6_V6ONLY;
			what = SO_FLAG;
		} else
#endif
#ifdef TCP_NODELAY
		if (!strcasecmp(p->tokbuf, "nodelay")) {
			l = IPPROTO_TCP;
			n = TCP_NODELAY;
			what = SO_FLAG;
		} else
#endif
			return "unknown socket option";
		switch (what) {
		case SO_FLAG:
			t = config_flag(p, &o);
			break;
		case SO_INT:
			t = config_int(p, &u);
			break;
		}
		if (t)
			return t;
		s = malloc(sizeof *s);
		if (s == 0)
			return e_memory;
		op = malloc(sizeof *op);
		if (op == 0)
			return e_memory;
		switch (what) {
		case SO_FLAG:
			*op = o;
			break;
		case SO_INT:
			*op = (int) u;
			break;
		}
		s->ss_level = l;
		s->ss_optname = n;
		s->ss_optval = op;
		s->ss_optlen = sizeof *op;
		s->next = *ss;
		*ss = s;
	}
	return 0;
},3,1,1

